INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8567336048', 'Livro - Til - Capa comum - Ciranda Cultural', 'Berta é uma moça humilde que mora perto da Fazenda das Palmas. Ela ajuda todos que estão à sua volta e cria um laço forte de amizade com Miguel, Linda e Afonso. Mas a história do seu nascimento esconde mistérios que envolvem muitas pessoas, dentre elas o temível Jão Fera, um capanga da região. Editora: Ciranda Cultural Edição: 1, 2017 Autor: José de Alencar Idioma: Português Páginas: 224 Dimensões: L 13.50 x A 20.50 x E 1.20 ISBN: 9788538076964', 19.9, 19.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/41c4a72154dcb08ab9e402d7bb83b07b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F8567336048', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
