INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13546267565', 'Desodorante Old Spice Amadeirado 150ml', 'Descubra o desodorante antitranspirante em spray Old Spice Amadeirado! Sinta-se mais confiante e protegido contra o suor e o mau cheiro, com sua incrível fragrância amadeirada com menta e especiarias. • Elimina 99% das bactérias do mau cheiro**Baseado em testes realizados com bactérias que causam o mau odor corporal: S. EPIDERMIDIS, S. HOMINIS, C. MUCIFACIENS, C. TUBERCULOSTEARICUM • 72 horas de proteção contra o mau cheiro • Sensação de frescor duradouro • Fragrância amadeirada com menta e especiarias • Você longe do cheiro de cecê ou suor • Dura até 20 días****Com base na instruçao de uso para 4.4g por día', 23.69, 23.69, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-8261j-mmacxox6r5s498', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353664457%2F13546267565', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698779017', 'Sapato Feminino Modare Napa Tressê Creme', 'Combinando conforto e estilo, o Sapato Feminino Modare Napa Tressê Creme é a escolha perfeita para completar seu look. O calçado é confeccionado em napa, que se adapta ao formato do pé e assim proporciona mais conforto. O solado em borracha antiderrapante conta com salto baixo embutido, e a palmilha macia contribui para um andar mais estável. Com um design clássico e discreto, o modelo possui detalhe em tira de metal em dourado com uma pedraria no centro, o que confere um charme a mais para combinar com seu visual favorito. Combinando conforto e estilo, o Sapato Feminino Modare Napa Creme é a escolha perfeita para completar seu look. As Lojas Radan conta com 10 lojas físicas no Rio Grande do Sul, oferecendo esta e uma grande variedade de produtos e marcas de calçados e vestuário feminino, masculino, infantil e esportivo. Compre online com entrega rápida para todo o Brasil ou em uma de nossas lojas físicas, aproveitando nossa experiência e adquirindo produtos de qualidade. Aproveite! Produto de autenticidade garantida vendido pela Lojas Radan. A cor do produto nas fotos pode sofrer alteração em decorrência do uso do flash ou da configuração do seu monitor. Características: Nome do produto: Sapato Feminino Modare Napa Tressê Creme Indicado: Dia a dia Tipo de Sapato: Casual Material: Sintético Material interno: Têxtil Palmilha: Espuma Fechamento: Sem fechamento Solado: Borracha Altura do Salto: 4cm Diferencial: Detalhe dourado com pedraria e textura tressê. Peso do produto: 638g', 139.89, 139.89, NULL, 'Women Shoes > Flats > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zuq-mn1g78uf77cy46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577790116%2F23698779017', NULL, NULL, '2026-