INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40929101554', '3 Mebendazole Vetnil - 10 comprimidos', 'Mebendazole Vetnil – 10 Comprimidos O Mebendazole® Vetnil é um vermífugo (anti-helmíntico) de amplo espectro indicado para o combate das principais verminoses gastrointestinais em cães e gatos. Atua de forma eficaz contra vermes redondos e outros parasitas intestinais, auxiliando na saúde e no bem-estar dos animais, sempre sob orientação do médico veterinário. Benefícios: Vermífugo de amplo espectro Combate as principais verminoses gastrointestinais Indicado para cães e gatos Fácil administração por via oral Pode ser administrado puro ou misturado ao alimento Indicações: Ancylostoma caninum Ancylostoma braziliense Ancylostoma tubaeforme Uncinaria stenocephala Toxocara canis Toxocara cati Toxascaris leonina Trichuris vulpis Modo de Uso e Posologia:Administrar por via oral 20 mg/kg de mebendazol. Cães: Até 5 kg: 1 comprimido/dia por 3 a 5 dias De 6 a 10 kg: 2 comprimidos/dia por 3 a 5 dias De 11 a 15 kg: 3 comprimidos/dia por 3 a 5 dias De 16 a 20 kg: 4 comprimidos/dia por 3 a 5 dias De 21 a 30 kg: 6 comprimidos/dia por 3 a 5 dias Gatos: 1 comprimido/dia por 3 a 5 dias Caso necessário, repetir o tratamento após 15 ou 30 dias, conforme orientação do médico veterinário. Especificações: Produto: Vermífugo (anti-helmíntico) Princípio ativo: Mebendazol Marca: Vetnil Indicação: cães e gatos Concentração: 100 mg de mebendazol por comprimido Apresentação: cartucho com 10 comprimidos Via de administração: oral Composição (por comprimido de 150 mg): Mebendazol: 100 mg Veículo: q.s.p. 150 mg', 46.1, 34.58, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/br-11134207-820mb-mlhxuocpq4ue80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F40929101554', NULL, NULL, '202