INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698544484', 'CefaWorld 600 mg Cães e Gatos Com 12 Comprimidos - World', 'Descrição: CefaWorld é um antibiótico à base de cefalexina, seguro em cães e gatos eficaz no combate de bactérias Gram + e Gram -indicado para tratamento de infecções dermatológicas, geniturinárias e intestinais. Comprimidos sulcados e revestidos para maior eficácia, segurança e facilidade de administração. Principais Características: - Comprimidos palatáveis; - Produto com rápida absorção pelo organismo. Indicação: Indicado para cães e gatos no tratamento de infecções bacterianas. Posologia e instruções de uso: Administração por via oral, conforme o peso do animal. Conforme fabricante a administração é de 30mg de cefalexina/kg de peso corporal, a cada 12 horas, durante 8 dias consecutivos, sendo: 01 comprimido de CefaWorld 150mg para cada 5 Kg de peso vivo. 01 comprimido de CefaWorld 300mg para cada 10 Kg de peso vivo. 01 comprimido de CefaWorld 600mg para cada 20 Kg de peso vivo. *Consulte sempre um médico veterinário e, em caso de outra indicação de uso, siga sempre o receitado pelo médico veterinário. _______________________________________________________ A MANADA ANIMAL é um marketplace de produtos veterinários. É a escolha certa para tutores que prezam pela qualidade dos produtos que seu animal necessita. Tudo com o suporte de uma equipe de veterinários e gestores com mais de 10 anos de experiência no mercado. Fique tranquilo, todos os nossos produtos são originais, adquiridos através de distribuidores credenciados! Ah, e todas as vendas acompanham nota fiscal! MANADA ANIMAL, Tranquilidade pra você, cuidado para ele!', 45.51, 45.51, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/br-11134207-820lj-mneg6exzokchf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450664666%2F23698544484', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
