INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43323013155', 'Bíblia Flexível Cruz | NVI | Capa Preta', 'Bíblia Sagrada Cruz | NVI | Capa Flexível Preta Conheça a Bíblia Flexível, uma edição especial em Nova Versão Internacional que combina design elegante e linguagem acessível. Desenvolvida para quem busca uma conexão mais próxima com a Palavra de Deus, esta Bíblia utiliza uma das traduções mais modernas e fiéis aos textos originais, facilitando a compreensão e o aprofundamento espiritual. Com capa flexível e materiais de alta qualidade, esta Bíblia foi pensada para resistir ao uso frequente sem perder o visual sofisticado. Suas páginas apresentam tipografia clara e confortável para a leitura, perfeita para estudos diários, momentos de oração ou uso na igreja. Ideal para novos convertidos, cristãos experientes, jovens em busca da verdade ou líderes dedicados ao ministério, esta Bíblia é uma companheira fiel para todos os momentos. Leve para onde for, mantenha na cabeceira ou presenteie alguém especial com um item que une significado espiritual e qualidade editorial. Mais do que um livro sagrado, esta edição é um convite ao encontro transformador com Deus. A cada leitura, uma oportunidade de fortalecer a fé, compreender as Escrituras e renovar o propósito de vida. Uma Bíblia que une tradução confiável, design funcional e inspiração para sua jornada de fé.', 35.81, 35.81, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824j1-mfi8zem0622y8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F43323013155', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18298021931', 'Corra Com Os Cavalos | Eugene H. Peterson | Ed comemorativa', 'Corra Com Os Cavalos | Eugene H. Peterson | Edição comemorativa "Corra com os Cavalos" de Eugene H. Peterson é uma reflexão poderosa sobre a vida cristã, convidando os leitores a uma jornada de crescimento espiritual e autoconhecimento. Esse livro é um mergulho na vida e obra do profeta Jeremias, oferecendo um convite ao arrependimento, a olhar para o simples e a viver pela fé. Ao contrário da teoria que promete que tudo dará certo e da ideia de prosperidade, Peterson nos confronta com a realidade de que, sem Deus, não há nada. Usando a metáfora dos cavalos, ele nos encoraja a abraçar os desafios da fé e a desenvolver uma relação mais profunda com o Criador, movendo-nos com liberdade e intensidade em nossa caminhada espiritual. Altura: 23 cm Largura: 16 cm Profundidade: 1,5 cm Páginas: 192', 49.95, 49.95, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-823rt-mok59w2zhjijca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F18298021931', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
