INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14428501368', 'Livro Louco Amor | Francis Chan', 'Louco Amor Maravilhado com um Deus que nunca muda Francis Chan dedica sua vida a ser um tipo diferente de cupido. Tendo experimentado com grande intensidade o amor de Deus, empenha-se em contagiar outras pessoas a (re)viverem a mesma paixão. Segundo Chan, apenas experimentando e nutrindo um honesto relacionamento com Deus podemos dar a necessária chacoalhada em nossa vida e espantar a terrível mornidão que caracteriza nossa atitude diante do Pai. O livro Louco Amor tira as nuvens que tornam nossa espiritualidade nublada, reacende a chama por um relacionamento profundo com Deus e mexe com nossa mente. Se você quer deixar de ser um ativista cristão e aprofundar seu relacionamento com Deus não deixe de ler este livro. Josué Campanhã - Diretor Sepal Brasil', 45.17, 45.17, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/ae330e480f46c1a7724c68acacb3d9bf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F14428501368', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194228007', 'Vinho Luiz Argenta Pinot Noir Clássico 2024 Caixa Com 6 Unidades', 'Pinot Noir Luiz Argenta Clássico 2024 - Caixa Com 6 Unidades Coleção: L.A. Clássico Terroir: Indicação de Procedência Altos Montes – Flores da Cunha, RS Tipo: Vinho Fino Tinto Seco Uva: 100% Pinot Noir Teor alcoólico: 13% Maturação: 6 meses em barricas de carvalho francês Vinificação: Este vinho é elaborado com uvas colhidas manualmente, passando por criteriosa seleção dos cachos e bagas. A vinificação é feita por gravidade, com adição de leveduras selecionadas, controle de temperatura durante a fermentação, e maceração pelicular por cerca de 15 dias. O processo inclui remontagens diárias por bin, fermentação malolática, trasfega, estabilização a frio e amadurecimento em barricas de carvalho francês por 6 meses. Notas de Degustação: Cor: Vermelho claro com tons violáceos, típico da variedade. Aroma: Intenso em frutas vermelhas frescas, com sutis notas tostadas provenientes do carvalho. Paladar: Leve, elegante e equilibrado, com final agradável. Temperatura ideal de serviço: 16 a 18 °C Harmonização: Carnes leves, massas com molhos vermelhos ou à base de cogumelos.', 672.0, 537.6, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/sg-11134201-7rdyc-mbz8lr9kdpam92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1496505540%2F22194228007', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
