INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22930830972', 'O Discípulo Radical | John Stott', 'O Discípulo Radical Para muitos, é uma grande surpresa descobrir que os seguidores de Jesus Cristo são chamados de cristãos apenas três vezes na Bíblia. Claro, sabemos que tanto as palavras cristão como discípulo? implicam relacionamento com Jesus. Mas, por que discípulo radical? Para John Stott, a resposta é óbvia. Existem diferentes níveis de comprometimento na comunidade cristã. O próprio Jesus ilustra isso ao explicar o que aconteceu com as sementes na Parábola do Semeador (Mt 13.3-23). A diferença está no tipo de solo que as recebeu. A semente semeada em solo rochoso não tinha raiz. Título:O Discípulo Radical Autor: John Stott Páginas: 136 Formato: 20,6 x 13,6 x 0,8 cm ISBN: 9788577790449 Editora: Ultimato', 28.95, 28.95, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134201-23030-1jz5r04nihovb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F22930830972', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
