INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16468040225', 'DNA e Propósito | Paulo Borges', 'DNA e Propósito Uma consciência de identidade, natureza e função na vida da igreja Cremos que o propósito de Deus para as nossas vidas não se restringe ao que fazemos em nome Dele, mas na pessoa que nos tornamos à Semelhança Dele. Ele nos criou para que nos tornássemos uma expressão visível das Suas Virtudes; nos entregou Suas promessas para que, por meio delas, nos tornássemos co-participantes da Sua Natureza. Portanto, o propósito do que compartilhamos neste livro é cooperar na compreensão da nossa vocação à luz da nossa natureza e identidade. Uma consciência clara e firme de origem. De tal modo que, não estejamos escravizados e subservientes a qualquer forma de pensamento, dogma ou estruturas humanas, mas submissos à natureza a partir da qual fomos gerados. Que tudo o que fazemos seja uma expressão visível e materializada de quem somos. A convicção de que Cristo, como Unigênito do Pai deu a Sua vida para se tornar Primogênito de muitos irmãos.', 41.97, 41.97, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/c459d7557b4f758732bc468fe0b9506b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F16468040225', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16708613851', 'Mangá - Box Blood Blockade Battlefront - Edições 1 a 5', 'Box Blood Blockade Battlefront - Edições 1 a 5 Três anos antes do início da história, um portal foi aberto entre a Terra e o submundo em plena cidade de Nova Iorque. Em uma terrível noite, a cidade foi destruída e reconstruída, prendendo seus cidadãos e seres de outras dimensões em uma bolha impenetrável. Após anos em um convívio caótico, alguém ameaça estourar a bolha. Preocupados com o que pode acontecer, um grupo de super humanos luta contra o impossível, para evitar o inimaginável!Conheça toda a saga de ''Blood Blockade Battlefront'' nesse box completo com os 10 volumes e um marcador exclusivo da série. Tipo de Produto: Box Segmentos: Mangás Marcas: JBC Mangás Autor(es): Yasuhiro Nightow Classificação Etária: 14 anos Gênero: Ação, Aventura Demografia: Shonen Editora: JBC Número de páginas: 1000 Lombada/Encadernação: Quadrada Tipo de capa: Cartão Idioma: Português', 73.9, 73.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/21d41e9b03671b919f0c4e1d48bdd50f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F16708613851', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
