INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22730833203', 'Bíblia Contexto | Salmos e Provérbios | NVT | Capa Dura | Leão', 'Bíblia Contexto Salmos e Provérbios A Bíblia é a seleção de duas obras: Salmos e Provérbios O formato inovador auxilia a pregação e os estudos bíblicos de pesquisadores, teólogos e pastores. O objetivo é que todos possam se beneficiar com esta obra, desde o leitor mais experiente, já habituado com o uso de referências cruzadas no estudo da Bíblia, até o leitor iniciante, que está conhecendo a literatura bíblica, obtendo um grande benefício. As referências bíblicas selecionadas a partir das Escrituras sagradas explicam e contextualizam os versículos presentes nos Livros de Salmos e Provérbios. Para tornar o entendimento ainda mais eficiente, os versículos estão sinalizados com a cor preta e as referências são citadas em vermelho, podendo ser feita de forma fluida ou separada por seções. Título: Bíblia Contexto Salmos e Provérbios Linguagem: Nova Versão Transformadora | NVT Acabamento: Capa Dura | Leão | Verniz Localizado e Soft Touch Borda: Impressa | Preta Índice: Não Palavras de Jesus em destaque: Não Harpa: Não Páginas: 270 Letra: Normal Fitilho: Sim, fitilho duplo Formato: Altura: 23,5 cm Largura: 16 cm Profundidade: 1,8 cm Peso: 490 g ISBN: 7908249102871 Editora: Sankto', 53.31, 53.31, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134201-23030-gb5h8b4nihov29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F22730833203', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197440886', 'Mangá - Fire Punch Vol. 05 - Novo/Lacrado', 'Fire Punch Vol. 05 O ''segredo'' de Togata vem à tona. As suas palavras que colocavam para fora todo o sofrimento que estava dentro do peito de Agni por um longo período mexe violentamente com o coração do jovem!! Para encarar de frente com o seu destino, Agni vai ao encontro ''daquele homem'' que é a fonte de todos problemas.!! Tipo de Produto: Revista Segmentos: Mangás Marcas: JBC Mangás Autor(es): Tatsuki Fujimoto ISBN: 9788545712985, 978-85-457-1298-5 Check-List: Novembro/2019 Classificação Etária: 18 anos Gênero: Ação, Aventura Editora: JBC Número de páginas: 208 Lombada/Encadernação: Quadrada Tipo de capa: Cartão Data de Lançamento: 13/11/2019 Idioma: Português Condição: Novo/Lacrado', 53.9, 53.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rce6-ltuz56suyizxc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F23197440886', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17202042399', 'Mangá - Vinland Saga Deluxe - 01', 'Vinland Saga Deluxe - 01 Quando criança, Thorfinn, filho do lendário guerreiro viking Thors, vive sem saber o passado do pai, que descobriu após anos no campo de batalha algo mais valioso do que matar seus iguais, viver sua vida de paz. Ao saber os tempos de guerra de seu pai, o garoto se revolta e vai à guerra com ele, mas acaba sendo tarde demais quando reconhece o valor dele. No passado, Thors se viu obrigado a lutar na guerra entre Dinamarca e Inglaterra junto aos Jomsvikings. ReimpressãoFormato: 13,7 x 20cm Tipo de Produto: Revista Segmentos: Mangás Marcas: Planet Manga Fase de leitura : Ideal para novos leitores Autor(es): Makoto Yukimura Check-List: Outubro/2021 Classificação Etária: 14 anos Gênero: Ação, Adulto, Aventura, Drama, Drama Histórico Demografia: Seinen Editora: Editora Panini Número de páginas: 464 Lombada/Encadernação: Quadrada Tipo de capa: Cartão Data de Lançamento: 23/10/2021 Idioma: Português', 58.9, 58.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/755e7f47b473e6bf8b5c64a9a447029d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F17202042399', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
