INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22799500625', 'Box Pokémon de Pacotes de Booster - Megaevolução - Fogo Fantasmagórico', '* Não estamos fazendo envios para os seguintes estados: Alagoas, Pernambuco, Distrito Federal, Minas Gerais, Rio Grande do Norte e Ceará. Pedidos aprovados para estes estados serão automaticamente cancelados. INFORMAÇÕES SOBRE O PRODUTO Acenda um espírito abrasador de batalha! Chamas azuis cauterizantes rasgam um campo escuro de batalha enquanto Mega Charizard X ex observa seus oponentes das alturas! Com um calafrio intenso desafiando o calor, a figura sombria de Mega Gengar ex emerge lentamente, e os dois Pokémon se preparam para o combate. Dispostos a provar sua força, Mega Heracross ex, Mega Lopunny ex e muitos outros Pokémon se alinham para dar tudo de si na expansão Megaevolução - Fogo Fantasmagórico do Pokémon Estampas Ilustradas! Aumente a sua coleção com este combo, que conta com 18 pacotes de booster de Megaevolução - Fogo Fantasmagórico do Pokémon Estampas Ilustradas! Características: - Marca: Copag. - Produto em Português. Conteúdo da Embalagem: - Contém 108 unidades de cartas no formato 63mm x 88mm. *Não recomendado para menores de 3 anos. Imagens Meramente Ilustrativas. Todas as Informações divulgadas são de responsabilidade do Fabricante/Fornecedor. Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. *Garantia de 30 dias contra defeitos de fabricação não decorrentes de mal uso (mediante aprovação da fabricante).', 469.9, 263.15, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-823qm-mp55w9szdbta12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F516662816%2F22799500625', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54306114313', 'Kit 2 Bermuda Masculina Dry Fit Shorts Plus Size', 'Seja Bem vindo a Loja Oficial da DAZE MODAS na SHOPEE. Bermuda Masculina Fit Daze Modas, confeccionada em 100% poliéster, leve e respirável. Possui cós elástico, bolso com zíper e ótimo caimento. Disponível do G1 ao G5. Conforto e praticidade para o dia a dia e atividades esportivas. Especificações do Produto: > Marca: Daze Modas > Composição: 100% Poliéster > Bolso com Zíper > Tamanhos: G1 ao G5 > Kit com 2 Peças > Veste muito bem. > Cós com elástico > Confeccionada em alto padrão de qualidade. > Fácil lavagem e secagem. > Tabela de medidas na última foto do anúncio. Especificações do Modelo: Modelo Veste: G2/52 Produto que o modelo usou na foto: G2/52 Altura: 1.80 Tórax: 129cm Cintura: 129cm Quadril: 126cm HORÁRIO DE ATENDIMENTO: De Segunda à Quinta das 08h00 às 18h00 De Sexta das 08h00 às 17h00 Seja Bem vindo a Loja DAZEMODAS na Shopee.', 159.9, 69.9, NULL, 'Men Clothes > Shorts', 'https://cf.shopee.com.br/file/br-11134207-81ztj-mkmakt7ag1z6e1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F287750271%2F54306114313', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
