INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098424288', 'Shampoo Arvensis Repositor Sol a Sol 300ml', 'Descrição: O Shampoo Arvensis Repositor Sol a Sol 300ml foi desenvolvido para cuidar dos cabelos que enfrentam os desafios diários da exposição ao sol, cloro, suor, sal e poluição. Com uma fórmula rica em água de coco e óleo de coco, ele realiza uma higienização suave e eficaz, mantendo os fios protegidos e saudáveis mesmo nas rotinas mais intensas. Hidratação Natural e Emoliência Os ativos naturais promovem hidratação, brilho e maciez, ao mesmo tempo em que removem impurezas, resíduos de cloro e sal acumulados nos fios. Ação Anti-Cloro e Anti-Sal Ideal para quem pratica natação, treina com frequência ou passa muito tempo ao ar livre, o shampoo atua como um verdadeiro escudo contra os danos causados por agentes externos. Benefícios: Remove resíduos de cloro, sal e suor Hidrata e suaviza os fios Protege contra agressões externas Realça o brilho natural do cabelo Indicado para uso frequente MODO DE USAR: Limpeza e preparação: – No dia a dia, use o Shampoo Repositor Sol a Sol para limpar suavemente e preparar os fios para o tratamento. Dica profissional: Para resultados ainda melhores, recomendamos o uso da linha completa Sol a Sol, que inclui máscara, elixir de nutrição e finalizadores com proteção térmica e solar. USO EXTERNO. MANTENHA FORA DO ALCANCE DAS CRIANÇAS. Conteúdo da embalagem: 300ml. #Imagem ilustrativa. Cor do produto poderá variar dependendo da configuração do monitor ou celular.', 69.81, 69.81, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-7renl-m8p66qoih67658', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322432427%2F23098424288', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
