INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250755413', 'Espelho Maquiagem Com Touch E Borda Luz De Led Mesa Portátil', 'O Espelho de Maquiagem com LED Just Beauty é o acessório ideal para quem busca praticidade e precisão na hora de se maquiar, em qualquer lugar. Compacto e elegante, ele possui iluminação em LED integrada, que garante uma visualização perfeita mesmo em ambientes com pouca luz. Basta apertar o botão para acender e ajustar o brilho conforme sua necessidade. Seu design moderno na cor rosa, aliado ao formato portátil, permite levar facilmente na bolsa, mochila ou nécessaire, sendo perfeito para o dia a dia, viagens ou retoques rápidos. 💡 Destaques ✔ Iluminação LED embutida ✔ Controle de brilho com toque ✔ Design compacto e portátil ✔ Acabamento moderno e elegante ✔ Ideal para maquiagem e cuidados pessoais ✔ Perfeito para levar na bolsa 👜 Indicado para Maquiagem do dia a dia Retoques fora de casa Viagens Uso profissional ou pessoal 📦 Conteúdo da Embalagem 1x Espelho de Maquiagem com LED Just Beauty', 53.2, 39.37, NULL, 'Beauty > Beauty Tools > Makeup Accessories', 'https://cf.shopee.com.br/file/br-11134207-820l5-mmumv0i62r5wcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F572166540%2F58250755413', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49602188266', 'Pulseira De Silicone Laranja | Todo Joelho Se Dobrará', 'Pulseira de Silicone Laranja | Todo Joelho Se Dobrará Silicone Confortável e Vibrante Proclame a soberania de Cristo! A pulseira laranja vibrante é feita de silicone macio e durável, assegurando conforto e longa duração. Ela traz a declaração profética que afirma a certeza de que um dia toda a criação reconhecerá Jesus como Senhor.', 15.9, 15.9, NULL, 'Fashion Accessories > Bracelets & Bangles', 'https://cf.shopee.com.br/file/sg-11134201-8226z-mhjkqgnbcfeuca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F49602188266', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43400349613', 'Box Comentário Bíblico Beacon | Novo Testamento 5 Volumes (capa dura)', 'Box Comentário Bíblico Beacon O Comentário Bíblico Beacon traz uma interpretação abrangente da Bíblia Sagrada elaborada por 40 teólogos evangélicos conservadores. São 10 volumes, cinco para o Antigo Testamento e cinco para o Novo. Em cada livro bíblico são comentados versículos de forma expositiva, exegética e sempre com uma sugestão homilética, o que torna o Beacon particularmente útil para pregadores e professores da Escola Dominical. Mas também ele tem uma característica devocional que faz dele uma obra cativante e indispensável a todos os crentes que desejam estudar a Palavra de Deus. Beacon tem erudição teológica, todavia num tom equilibrado na sua interpretação e no seu objetivo inspiracional. Seu formato é atraente e prático. Seus comentaristas e editores acreditam que esta obra é de grande valor para todos que buscam descobrir as verdades profundas da Palavra de Deus, que "subsiste eternamente".', 384.78, 384.78, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9jbgf6ro8oyc2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F43400349613', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210215379', 'Vinil Disney - Hannah Montana 2 (Stylized Black and White) - Importado', 'Vinil Disney - Hannah Montana 2 (Stylized Black and White) - Importado A espera acabou! As músicas da 2ª temporada da icônica série do Disney Channel, HANNAH MONTANA, já estão disponíveis em vinil estilizado em preto e branco e incluem todos os sucessos, como We Got the Party, Nobody’s Perfect, Life’s What You Make It e muito mais! Tracklist: Lado A: 1. We Got the Party 2. Nobody''s Perfect 3. Make Some Noise 4. Rock Star 5. Old Blue Jeans Lado B: 1. Life''s What You Make It 2. One in a Million 3. Bigger Than Us 4. You and Me Together 5. True Friend *Por favor, note que cada vinil é único e as cores podem parecer ligeiramente diferentes da imagem exibida.', 249.9, 249.9, NULL, 'Hobbies & Collections > Vinyl Records', 'https://cf.shopee.com.br/file/sg-11134201-8258t-mr0j5ey075l34d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F58210215379', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258153152', 'Vinil Neil Diamond - All-Time Greatest Hits (Standard Black LP) - Importado', 'Vinil Neil Diamond - All-Time Greatest Hits (Standard Black LP) - Importado Neil Diamond, cantor e compositor americano que tem em sua trajetória cinco décadas extremamente produtivas, ele foi responsável por criar um dos catálogos mais duradouros da música popular americana. Confira essa coletânea de grandes sucessos do cantor com "Sweet Caroline", "Song Sung Blues", "September Morn" e muito mais . Repertório do LP: Lado A: A1. I Am I Said A2. Sweet Caroline A3. Cracklin'' Rose A4. Forever In Blue Jeans A5. Song Sung Blues A6. Holly Holy Lado B: B1. America B2. Play Me B3. Solitary Man B4. Cherry, Cherry B5. September Morn B6. Soolaimon', 229.9, 229.9, NULL, 'Hobbies & Collections > Vinyl Records', 'https://cf.shopee.com.br/file/sg-11134201-82584-mr0j7958vkzmdf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F58258153152', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49962401586', 'O Segredo dos Homens Mais Ricos da Bíblia | Magno Paganelli', 'O Segredo dos Homens Mais Ricos da Bíblia | Magno Paganelli Magno Paganelli Este livro apresenta uma investigação bíblica sobre riqueza e prosperidade, analisando as biografias de três dos homens mais prósperos das Escrituras. O autor oferece uma perspectiva fundamentada nas Escrituras, distante da teologia da prosperidade, para compreender os princípios financeiros bíblicos. Em meio a tantas conferências sobre enriquecimento e tentativas frustradas de conquistar prosperidade, Magno Paganelli recorre à sabedoria milenar da Bíblia para identificar padrões comuns nas trajetórias de Abraão, Jacó e Salomão. A obra também inclui uma análise exegética completa sobre o dízimo, desde o Antigo até o Novo Testamento, respondendo questões práticas sobre sua aplicação nos dias atuais. Análise detalhada das biografias de três patriarcas bíblicos prósperosEstudo exegético sobre o dízimo do Antigo ao Novo TestamentoPerspectiva acadêmica fundamentada em mais de 30 anos de experiência editorialAbordagem distante da teologia da prosperidadeRespostas bíblicas para questões práticas sobre dinheiro e riquezaUma obra essencial para quem busca compreender a perspectiva bíblica sobre finanças e prosperidade, fundamentada na experiência acadêmica de um autor com formação sólida em História das Religiões e Teologia. Especificações do livro O Segredo dos Homens Mais Ricos da Bíblia | Magno Paganelli: Título: O Segredo dos Homens Mais Ricos da Bíblia | Magno Paganelli Autor(es): Magno Paganelli Ano de Edição: 2026 Capa: Brochura Acabamento: Laminação Fosca com Verniz Localizado Miolo: Ivory Bulk Páginas: 128 Dimensões: 23 x 15,5 x 0,58 cm Peso: 150 g ISBN: 9786583007407 Idioma: Português Editora: Berith Família: Livros Assunto: Vida Cristã, Finanças, Dízimo, Prosperidade', 32.9, 32.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824ij-mpkxcpcyk83w4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F49962401586', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58213051608', 'CD Yes - From A Page (2CD Expanded And Remastered Edition) - Importado', 'CD Yes - From A Page (2CD Expanded And Remastered Edition) - Importado Lançado inicialmente como um mini-álbum em 25 de outubro de 2019 pela Yes Records, e posteriormente expandido para um álbum completo com lançamento que ocorreu em 2026. A formação é composta pelo baixista Chris Squire, o guitarrista Steve Howe, o baterista Alan White, o vocalista Benoît David e o tecladista Oliver Wakeman. Wakeman reuniu o material após a morte de Squire. 2CD Limited Edition, Reissue, Remastered, Stereo, Clam Shell Box Repertório dos CDs: CD-1: 1. To The Moment 2. The Man You Always Wanted Me To Be (Alt. Ver.) 3. From The Turn Of A Card 4. Into The Storm (Alt. Ver.) 5. Aliens (Alt. Ver.) 6. Hour Of Need (Alt. Ver.) 7. Words On A Page 8. The Gift Of Love CD-2: 1. Words On A Page (Demo) 2. The Man You Always Wanted Me To Be (Demo) 3. To The Moment (Demo) 4. The Gift Of Love (Demo) 5. Don''t Take No For An Answer (Demo) 6. Updraft (Demo) 7. To The Moment (Single Mix)', 199.9, 179.9, NULL, 'Hobbies & Collections > CD, DVD & Bluray', 'https://cf.shopee.com.br/file/sg-11134201-8259u-mr0j4uchvzt1a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F58213051608', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
