INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18999583361', 'Chave de Roda L 17mm Universal Carro Aço Carbono Sem Espátula VW Polo Gol Onix HB20 Original', 'Chave de Roda L 17mm Universal é a ferramenta ideal para quem busca resistência, praticidade e segurança na hora de trocar o pneu do carro. Fabricada em aço carbono reforçado, garante maior durabilidade e excelente desempenho, suportando uso frequente sem deformar. Compatível com qualquer veículo que utilize porca de roda 17mm, incluindo modelos como VW Polo, Gol, Fox, Voyage, Chevrolet Onix, Prisma, Hyundai HB20, entre outros. Seu formato em L proporciona mais força e conforto na aplicação de torque, tornando o trabalho mais rápido e seguro. Produto leve, prático e fácil de guardar no porta-malas, essencial para emergências na estrada. ✅ Medida: 17mm ✅ Material: Aço carbono reforçado ✅ Formato: L (sem espátula) ✅ Compatível com diversas marcas e modelos ✅ Alta resistência e durabilidade Garanta já a sua e tenha mais segurança e tranquilidade nas viagens!', 49.99, 34.99, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Wrench', 'https://cf.shopee.com.br/file/br-11134207-81z1k-miehi2kamvpf38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1302754239%2F18999583361', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20922907328', 'CAIXA BOB VERTICAL DUTO 3 POLEGADAS ALTO FALANTE DE 12 POLEGADAS APARELHO 1 DIN (L:34 X A:65 X P:28)', 'Conhecidas pelo alto padrão de acabamento e qualidade acústica, as caixas Nandin Sound são confeccionadas com que há de melhor no mercado e todo o processo de corte da madeira é realizado por Router CNC, garantindo encaixes perfeitos e um acabamento inigualável. Todos os projetos são desenvolvidos pelos melhores profissionais da área de som automotivo do Brasil. Desenvolvida em MDF 15 mm com acabamento em carpete resinado e pintura. Especificações da caixa: - Madeira: MDF 15 mm; - Acabamento: Carpete resinado e pintura; - Litragem: 29,5 litros; - Diâmetro do duto: 3 polegadas; - Diâmetro do alto falante: 12 polegadas; - Furo para aparelho 1 DIN; - Dimensões (Largura x Altura x Profundidade): 34,5 x 65,5 x 28,5 cm; *Só aceite receber a mercadoria após verificar se a mesma coincide com a que consta no pedido e se está em perfeito estado;', 179.99, 179.99, NULL, 'Audio > Home Audio & Speakers > Speakers', 'https://cf.shopee.com.br/file/sg-11134201-7rdyi-lynukv7uf25m57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406280808%2F20922907328', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893952106', 'Protetor Solar Facial Panvel Fps70 50g', 'Conte&uacute;do: 50G FPS70 Alta prote&ccedil;&atilde;o &nbsp; Para que serve o Protetor Solar Panvel? O Protetor Solar Facial Panvel FPS 70 possui textura leve e de r&aacute;pida absor&ccedil;&atilde;o, sem cor, garante prote&ccedil;&atilde;o contra as radia&ccedil;&otilde;es UVA e UVB e do envelhecimento causado pela exposi&ccedil;&atilde;o solar, pr&oacute;prio para ser usado diariamente. Enriquecido com &Aacute;cido Hialur&ocirc;nico e Vitamina E que hidratam, protegem e auxiliam na manuten&ccedil;&atilde;o da elasticidade da pele. Cont&eacute;m Niacinamida, que promove o clareamento, uniformiza&ccedil;&atilde;o da pele e a&ccedil;&atilde;o antirrugas. Indicado para todos os tipos de pele, principalmente as extremamente sens&iacute;vel a queimadura solar.&nbsp; &nbsp; Quais os benef&iacute;cios do Protetor Solar Panvel? R&aacute;pida Absor&ccedil;&atilde;o;&nbsp; Resistente a &Aacute;gua e Suor;&nbsp;&nbsp; Textura Leva;&nbsp; Com Vitamina E&nbsp;e&nbsp;extrato Aloe Ver;&nbsp; Previne o fotoenvelhecimento da pele;&nbsp; Dermatologicamente testado.&nbsp; &nbsp; Modo de uso&nbsp; Aplique abundantemente e uniformemente sobre a pele seca, em todas as &aacute;reas a serem expostas ao sol, 30 minutos antes da exposi&ccedil;&atilde;o. Ap&oacute;s o uso, aguarde a secagem. &Eacute; necess&aacute;ria a reaplica&ccedil;&atilde;o do produto para manter a sua efetividade. Reaplicar sempre, ap&oacute;s sudorese intensa, nadar ou banhar-se, secar-se com toalha e durante a exposi&ccedil;&atilde;o ao sol.&nbsp;', 54.99, 54.99, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-821dz-mgpdvam6xde0a8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1609010660%2F23893952106', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
