INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898031455', 'Bola De Futebol De Campo Red São Paulo N5', 'A Bola Futebol de Campo do São Paulo é a pedida certa para o bate-bola da sua turma. Confeccionada em materiais de qualidade, a Bola de Futebol oferece maciez, essencial para as partidas de futebol da criançada. E para complementar, o escudo do seu time do coração em destaque para o orgulho do torcedor. Desperte o craque que existe em você. Informações Técnicas : Composição: Policloreto de Vinila (PVC) Câmara interna: 100% borracha butílica Circunferência aproximada: 68 - 70 cm Peso aproximado: 410 - 440 g Clube: São Paulo Indicado para: Campo Origem: Importada Miolo: Removível Gênero: Unissex Costura: Sim Gomos: 30 Tamanho único Conteúdo da Embalagem: 01 un. Bola de Futebol de Campo Red São Paulo N5 Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 99.0, 99.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/sg-11134201-7renc-m2qzge3gsb2ed1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F22898031455', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41222889092', 'Prancha de Deslizamento Portátil 8 em 1 para Pilates Exercício Multifuncional Equipamento Core Tippi', 'Prancha de Deslizamento Portátil 8 em 1 para Pilates Exercício Multifuncional Equipamento para Força Core Treino Abdominal Tippi O aparelho Core Multifuncional é um equipamento multifuncional desenvolvido para fortalecer a região abdominal, melhorar a postura e tonificar o corpo de forma prática e eficiente. Ideal para treinos em casa, ele combina os benefícios do pilates com exercícios de prancha, proporcionando um trabalho completo da musculatura do core, braços, pernas e glúteos. Com estrutura dobrável, leve e fácil de guardar, é perfeito para quem busca praticidade sem abrir mão de resultados. Conta com trilhos deslizantes, apoio para braços e joelhos, e diferentes níveis de inclinação para ajustar a intensidade do exercício conforme sua evolução. Especificações Técnicas: • Modelo: Core Multifuncional • Função: Exercitador abdominal e prancha de pilates • Uso: Residencial • Material: Estrutura em aço e plástico resistente • Recursos: Trilho deslizante com apoio de joelhos, manoplas com espuma, níveis de inclinação ajustáveis • Tipo de exercício: Core, braços, pernas, glúteos • Dobrável: Sim • Portátil: Sim • Fácil de montar e guardar Dimensões do Produto: • Comprimento: 100 cm • Largura: 40 cm • Capacidade máxima: 120 kg FAQ (Perguntas Frequentes): 1. O equipamento vem montado? Não, ele acompanha manual com instruções simples de montagem. 2. É indicado para iniciantes? Sim, possui regulagem de inclinação para adaptar ao seu nível. 3. Posso usar todos os dias? Sim, desde que respeite seus limites e o tempo de descanso muscular. 4. Serve para treinos de emagrecimento? Sim, combina tonificação muscular com gasto calórico, ideal para definição e perda de gordura. Conteúdo da Embalagem: • 01 Aparelho Core Multifuncional Importante: Valor Unitário. Imagens Meramente Ilustrativas. Não nos responsabilizamos pelo mau uso do produto.', 570.01, 399.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/sg-11134201-824h0-mffw6skf3imk34', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F281898655%2F41222889092', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
