INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998190292', 'Balizador Spot LED Embutir Chão Piso Jardim 10W Luz Quente e Verde IP65 Bivolt 60Hz', '🌱 Balizador Spot LED Embutir para Chão e Jardim – 10W 🌱 💡 Ilumine seu espaço com eficiência e durabilidade! Este Spot LED de Embutir é ideal para iluminação de pisos, caminhos, jardins e áreas externas, garantindo um efeito moderno e sofisticado. ✅ Destaques do Produto: ✔ Opções de Cores: Branco Quente (aconchegante) ou Verde (decorativo). ✔ Potência de 10W: Iluminação eficiente com 1100 lúmens. ✔ Resistente e Durável: Vida útil de até 25.000 horas. ✔ Proteção IP65: À prova d''água, ideal para uso externo. ✔ Bivolt (AC85-265V): Compatível com redes elétricas convencionais. ✔ Ângulo de Abertura de 80°: Distribuição uniforme da luz. ✔ Dimensões: 120x120mm, fácil de embutir no piso. 🏡 Perfeito para jardins, calçadas e áreas externas, trazendo beleza e segurança para seu ambiente! ⚠ O ANÚNCIO SE REFERE A UM KIT DE 1 a 4 LUMINÁRIAS! ESCOLHA DE ACORDO COM SUA PREFERÊNCIA EM NOSSAS VARIAÇÕES DE QUANTIDADE!', 68.0, 29.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6pta8ebigc075', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979730489%2F23998190292', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210592830', 'Camisa do Flamengo Masculina Licenciada Lançamento Original', '🔴⚫🔥 Camisa Flamengo Masculina – Estilo, Tradição e Paixão Rubro-Negra! 🔥⚫🔴 Mostre seu amor pelo Mengão com muito estilo e autenticidade! 🏆 Essa camisa foi criada para o torcedor que carrega a paixão pelo Flamengo dentro e fora dos estádios, unindo conforto, design moderno e identidade rubro-negra. 💥 Visual marcante e cheio de personalidade: Confeccionada com combinação de tecidos lisos e texturizados, ela traz detalhes modernos, recortes vibrantes e mangas raglan que garantem um visual esportivo e sofisticado 😎 🚀 Destaques do produto: ✔ Tecido confortável e leve para o dia a dia ✔ Design moderno com recortes em cores vibrantes 🔥 ✔ Mangas raglan: mais liberdade de movimento ✔ Escudo do Flamengo em destaque no peito 🛡️ ✔ Frase icônica “VENCER, VENCER, VENCER” aplicada nas costas ⚫🔴 ✔ Acabamento premium com transfer termo aplicado 📋 Informações técnicas: • Gênero: Masculino • Indicação: Dia a dia, torcida e lazer • Modelagem confortável • Material leve e resistente 🏟️ Perfeita para: ✔ Jogos do Flamengo ✔ Looks casuais ✔ Demonstrar sua paixão pelo Mengão em qualquer lugar 🔥 Carregue a tradição rubro-negra com orgulho e estilo! 🛡️ Produto de alta qualidade, ideal para os verdadeiros apaixonados pelo Flamengo!', 224.85, 119.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/br-11134207-820lp-mo6qs4gx12ipf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1716040168%2F58210592830', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
