INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21398286132', 'Body Splash Majesty Desodorante Colônia Intenso Elegante Fem Bloom 200ml', 'BODY SPLASH MAJESTY DESODORANTE COLÔNIA INTENSO O Body Splash Majesty combina frescor, doçura e intensidade em uma fragrância equilibrada e luxuosa, inspirada na alta perfumaria. Sua textura leve proporciona frescor imediato, enquanto sua perfumação marcante acompanha você ao longo do dia, sem pesar na pele. Ideal para mulheres modernas que buscam elegância e presença em todos os momentos. Desenvolvido com moléculas que ajudam a prolongar a fixação, mantendo a sensação de perfume por horas, mesmo em climas quentes ou rotinas intensas. Destaques do Produto • Fragrância sofisticada e marcante • Combinação de notas florais, amadeiradas e orientais • Sensação de frescor imediato • Fixação prolongada sem pesar • Toque leve e não oleoso • Ideal para uso diário Caminho Olfativo Floral • Amadeirado • Oriental MODO DE USO: Aplique diretamente sobre a pele limpa, especialmente em áreas de maior circulação como pescoço, colo e pulsos. Reaplique ao longo do dia, se desejar. Informações Técnicas • Tipo: Body Splash / Desodorante Colônia • Volume: 200ml • Público: Feminino • Fixação: Moderada COMPOSIÇÃO Água, álcool, propilenoglicol, fragrância', 85.9, 45.5, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/br-11134207-820lr-mnwt63334xz8ac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1609741857%2F21398286132', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
