INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799493390', 'Camisa Portuguesa Retrô 1965 Branca Masculina Oficial', 'Camisa Portuguesa Retrô 1965 Branca Masculina, desenvolvida em algodão macio e confortável, o escudo retrô mantém a originalidade da peça. Uso casual, indicado para momentos de lazer e ir ao estádio._x000D_ _x000D_ __x000D_ _x000D_ _x000D_ Características:_x000D_ - 100% algodão com toque peletizado_x000D_ - Escudos: Bordado_x000D_ - Retilínea nas mangas_x000D_ _x000D_ _x000D_ Medidas Aproximadas: Largura x Altura_x000D_ - P (BR): 50 x 69_x000D_ - M (BR): 52 x 71_x000D_ - G (BR): 54 x 73_x000D_ - GG (BR): 56 x 75_x000D_ - XG (BR): 62 x 78_x000D_ _x000D_ _x000D_ _x000D_ __x000D_ _x000D_ _x000D_ _x000D_ _x000D_ __x000D_ _x000D_ _x000D_ TOQUE MACIO_x000D_ Algodão Peletizado_x000D_ _x000D_ Formação do fio que se dá através de um efeito felpudo em apenas uma face. Possui toque macio e confortável, conta com um acabamento especial, o tecido passa por um processo de lixamento, deixando o toque mais delicado e suave.', 199.9, 179.91, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/sg-11134201-7rdyl-m0xh5fd1jh2o21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F698219490%2F20799493390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
