INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294169308', 'Bota PVC Cano Médio Cartom CA 32165 - Branco', 'As Botas de PVC Cartom, garantem o máximo de impermeabilidade e têm fácil higienização. No cabedal tipo C, possuimontagem por sistema de injeção por extrusão, classificação II (Inteiro polimérico), é forrado em poliéster simples e o solado tem monodensidade com ressaltos, solado resistente à ação de óleo combustível. Região do salto totalmente fechada, com resistência ao escorregamento. É Um calçado versátil, destinadoa proteção dos pés do usuário contra riscos de natureza leve, contra agentes abrasivos e escoriantes e contra umidade proveniente de operações com uso de águacomo agricultura, pecuária, veterinária, saneamento, indústria alimentícia (frigoríficos, abatedouros, laticínios, apiários, aviários, pescados, fábricas de bebidas), indústria química, hospitais, clinicas, cozinhas industriais, supermercados, padarias, açougues, restaurantes, prestação de serviço, serviços de higienização, hotelaria, postos de combustíveis, construção civil, lavação automotiva, usinas de cana de açúcar, jardinagem, pesca, lazer, camping, motoboy, uso doméstico em geral, entre outros. A restrição desse produto é para não utilizá-lo em operações de combate a incêndio. Altura do cano: 35 cm. A altura do cano cano pode variar dependendo da numeração, podendo ter uma variação de 5 a 10 mm por número.', 99.9, 49.9, NULL, 'Men Shoes > Boots > Safety Boots', 'https://cf.shopee.com.br/file/sg-11134201-7ra3o-mbdudbllu452b6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F23294169308', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
