INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23615042658', 'Escapamento Escape Moto Completo Powercore 4 CRF 250F 2019 a 2020', 'Apostando em tecnologia, design e performance, a Pro Tork traz ao mercado seu novo sistema de escapamento, o Escapamento Powercore 4. Projetado para entregar maiores níveis de potência imediata para motocicletas off road, o equipamento conta com o que há de melhor em matéria-prima e excelência no processo de produção, tudo isso graças ao desenvolvimento de cada detalhe, que proporcionou grandes avanços em relação aos sistemas de escapamento similares. Especificações: - Maior desempenho em potência imediata; - Disponível nas cores: Azul, Dourado, Preto, Rosa, Verde e Vermelho; - Matéria-Prima de alta qualidade; - Curva do motor fabricada em Aço Inox; - Ponteira fabricada em Alumínio de alta resistência; - Tecnologia Bomber Flux que mantém o motor em compressão constante, conferindo retomadas certas nas saídas de curvas; - Marca: Pro Tork. Aplicação: - Honda CRF 250F 2019; - Honda CRF 250F 2020. Instalação: - A instalação deve ser feita por um profissional especializado. A Sportbay não se responsabiliza por instalação mal realizada; - O produto é pronto para instalação de acordo com o modelo da moto, e encaixa-se perfeitamente no lugar do original, não sendo necessário nenhum tipo de adaptação.', 1207.26, 679.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mb3ymwmfguq769', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F23615042658', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55360173894', 'Como Fazer Amigos e Influenciar Pessoas | Dale Carnegie', 'Dale Carnegie (1888–1955) foi um escritor, palestrante e educador norte-americano, reconhecido mundialmente como um dos maiores especialistas em comunicação, relações humanas e desenvolvimento pessoal. Seu trabalho revolucionou a forma como as pessoas se relacionam, lideram e influenciam umas às outras. Autor do clássico “Como Fazer Amigos e Influenciar Pessoas”, um dos livros mais vendidos de todos os tempos, Carnegie dedicou sua vida a ensinar princípios práticos de empatia, escuta ativa, persuasão ética e liderança positiva. Seus métodos deram origem ao Dale Carnegie Training, programa de treinamento presente em diversos países e utilizado até hoje por profissionais, líderes e empresas. Mesmo décadas após sua morte, os ensinamentos de Dale Carnegie continuam atuais, ajudando milhões de pessoas a se comunicar melhor, construir relacionamentos sólidos e alcançar sucesso pessoal e profissional com integridade. Título: Como Fazer Amigos e Influenciar Pessoas | Dale Carnegie Autor: Dale Carnegie Páginas: 192 Formato: 17 x 24 cm Edição: 2026 Capa: Brochura Peso: 0,320 kg ISBN: 9786560954076 Editora: Grupo Online', 15.9, 15.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-820o4-mnzvckep75dub1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F55360173894', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22592603175', 'Triciclo Infantil Ultra Bikes Military Boy Com Number Place [Roda Em Pp]', 'O Triciclo Ultra Bikes Military conta com um novo grafismo camuflado, para trazer ainda mais diversão e aventura para as crianças. Com peças plásticas injetadas em polipropileno e uma tecnologia DGP(Double Glass Polypropylene) produzindo brilho em dobro, enquanto seu quadro, é fabricado em aço para maior segurança. Especificações: - Possui assento reajustável com 2 opções de tamanho; - Buzina a ar; - Cor: Verde militar; - Number plate; - Manoplas antiaderentes; - Pedais ergonômicos fixados nas rodas dianteiras; - Rodas em PP(Polipropileno); - Plataforma no eixo traseiro para apoio; - Indicado para criança a partir de 18 meses de idade, até crianças com um peso máximo de 21kg ou com altura máxima de 112cm; - Certificação INMETRO; - Marca: Ultra Bikes. Benefícios: - Entretenimento infantil; - Estimula a prática de exercícios; - Interação entre pais e filhos; - Diversão e aventura. Dimensões aproximadas do triciclo: - Altura do guidão até o chão: 50 cm; - Largura entre as duas rodas traseiras: 45 cm; - Altura do banco até o chão: 29 cm; - Comprimento: 58 cm.', 257.79, 164.9, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/sg-11134201-7rbne-lnka3pupqco6ce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F22592603175', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
