INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792844137', 'Mixer Rosa Britânia BMX370RS 350W', 'Que tal atingir a melhor textura no preparo das suas receitas? Com o Mixer Rosa Britânia BMX370RS, você alcança a consistência correta para cada tipo de preparo! Com 350W de potência, uma velocidade e função pulsar, o mixer rosa Britânia é capaz de misturar e processar receitas das mais elaboradas as mais simples. Equipado com copo com alça e tampa e capacidade útil de 800ml, o mixer é um aliado à praticidade que sua rotina precisa. Além do corpo ser desmontável, facilitando a limpeza e o armazenamento do aparelho. Outro diferencial, são as lâminas com tecnologia Pro Maxx em aço inox, ou seja, você tem um produto com maior resistência, durabilidade e um altíssimo poder de trituração! Mixer Rosa Britânia BMX370RS 350W, suas receitas mais cremosas e homogêneas. 350W de Potência Design Ergonômico 1 velocidade Turbo Corpo Desmontável 04 Lâminas em inox Copo Plástico – Capacidade total de 1050ml e útil de 800ml Copo acompanha alça e tampa.', 109.9, 89.9, NULL, 'Home Appliances > Kitchen Appliances > Mixers', 'https://cf.shopee.com.br/file/sg-11134201-8259i-mqgac8dvj94y2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811879342%2F23792844137', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
