INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23696332513', 'Spray Hidratante Pet Soft Touch Hydra Groomers 500mL', 'Hydra Groomers Soft Touch 500ml Spray para Hidratação e Cauterização Proporciona hidratação e maciez à pelagem, além de cauterizar os fios, deixando-os brilhantes. Contém Queratina, que ajuda a manter e restaurar a hidratação da pele e pelagem; Pantenol, que age na lubrificação, fortalecimento e nutrição dos fios; além de Ácido Lático, que hidrata e ajuda no fechamento da cutícula. Indicado para uso profissional em cães e gatos para hidratar e cauterizar a pelagem. Uso tópico. Banhe o animal normalmente e retire o excesso de água na toalha. Após o uso do soprador, aplique o Hydra Soft Touch diretamente em toda a pelagem, espalhe bem e finalize a secagem com o secador.', 127.9, 115.11, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/br-11134207-7qukw-ljfpv3rgqa2y23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F688030691%2F23696332513', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
