INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898367527', 'Acquaflora Nutrição Celular - Shampoo 300ml', 'DESCRIÇÃO Shampoo ideal para cabelos enfraquecidos ou estressados, sem acúmulo de química que necessitem de hidratação moderada a intensa. Sua fórmula contém: Carbocisteína: Aminoácido responsável por nutrir, conferir força e resgatar a flexibilidade natural dosfios. Pantenol: Vitamina altamente umectante que proporciona hidratação e maciez aos cabelos. Creatina: Nutriente importante para o metabolismo energético celular, capaz de doar resistência à fibra, reparando-a na sua parte mais interna e reduzindo o dano causado por agressões. DICAS DE USO Aplicar nos cabelos molhados e massagear suavemente até obter uma espuma cremosa. Enxaguar e repetir a operação, desta vez com uma menor quantidade do produto. Espalhar a espuma por todo o comprimento do cabelo sem esfregar um fio no outro. Enxaguar bem. Para um melhor resultado, utilize em seguida o Condicionador Acquaflora Nutrição Celular.', 102.2, 59.9, NULL, 'Beauty > Bath & Body Care > Sun Care', 'https://cf.shopee.com.br/file/sg-11134201-82616-mkts2s72xq1373', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22898367527', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894029692', 'Amend Luxe Creations Blonde Care Fluido Reconstrutor 180ml', 'O Fluído Reconstrutor Amend Blonde Care foi elaborado para devolver a maciez e o aspecto saudável aos cabelos que sofreram processos químicos e ficaram enfraquecidos, porosos e emborrachados. Com Queratina e Blonde Care Force*, age de forma rápida aumentando o diâmetro dos fios, promovendo a reconstrução diretamente no córtex, criando pontes adicionais à estrutura de queratina, refazendo as ligações essenciais para recuperar a força e a vitalidade dos cabelos. Modo de Uso: Após lavar os cabelos, aplique o Fluído Reconstrutor, espalhando bem, principalmente nas regiões mais sensibilizadas pelos processos químicos. Deixe agir por aproximadamente 1 minuto, sem enxaguar. Em seguida aplique a Máscara Blonde Care, conforme modo de uso. Precauções: Mantenha fora do alcance de crianças, em lugar fresco e ao abrigo de luz intensa. Não ingerir. Em caso de contato com olhos, enxaguar imediatamente com água abundante. USO EXTERNO.', 80.7, 64.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rauk-ma4dj70mxosjfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22894029692', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298816604', 'Wella Professionals BlondorPlex - Condicionador 200ml', 'Wella Professionals BlondorPlex - Reparação Profunda Ideal para cabelos loiros, danificados e descoloridos. Reconstrói intensivamente a fibra capilar, devolvendo força e maciez aos fios. Sua fórmula rica em ativos reparadores, nutre e restaura a estrutura capilar. Cabelos visivelmente mais fortes, macies e radiantes, com brilho impecável. Conselho de Aplicação Aplique sobre o comprimento e pontas do cabelo limpo e úmido. Deixe agir por 1-2 minutos e enxágue bem.', 263.45, 144.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rdvn-mdad50cnx79c5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22298816604', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593415609', 'Kit L''Oréal Professionnel Serie Expert Vitamino Color Duo (2 produtos)', 'L’Oréal Professionnel Kit Serie Expert Vitamino Color Duo Kit com shampoo e condicionador para cabelos coloridos. Kit L’Oréal Professionnel Serie Expert Vitamino Color Duo mantém a vitalidade da cor por mais tempo. O Kit L’Oréal Professionnel Serie Expert Vitamino Color Duo traz shampoo e condicionador formulados com Resveratrol e agentes antioxidantes, para proteção da cor e brilho intenso, evitando o desbotamento e garantindo um resultado de cor radiante e duradoura. Conselho de Aplicação Aplique o shampoo no cabelo molhado. Passe uma pequena quantidade no couro cabeludo. Massageie com a ponta dos dedos até surgir espuma e depois enxágue. Repita se sentir necessidade. Após o shampoo, aplique o condicionador no comprimento e pontas. Deixe agir por alguns instantes. Enxágue bem. Nossos Experts Ensinam Faça sempre duas lavagens com o shampoo. A primeira irá retirar todas as impurezas mais pesadas, enquanto a segunda finaliza a higienização do couro cabeludo e inicia o tratamento.', 687.41, 361.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rdvq-m1cuncn35gl62d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F23593415609', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21797926006', 'Kit Wella Professionals Fusion Shampoo Extra e Válvula (4 produtos)', 'Kit Wella Professionals Fusion Shampoo Extra e Válvula (4 produtos) Kit em tamanho salão para cabelos danificados. Kit Wella Professionals Fusion Salon Duo ajuda a recuperar a fibra capilar dos danos e evita a quebra. faz uma limpeza delicada no cabelo, sem comprometer a saúde da fibra capilar, além de deixar os fios mais suaves e desembaraçados. Sua fragrância combina nove aromas que remetem à sofisticação, com seus toques de madeira florestal e notas de base quentes, como cedro e sândalo. Esse Kit Contém Wella Professionals Fusion - Shampoo 1l (2 unidades): limpa e auxilia na reparação dos danos. Válvula Pump para 1L (2 unidades) Conselho de Aplicação Shampoo: aplique o shampoo sobre a raiz do cabelo molhado e massageie até formar espuma. Puxe o produto para a extensão e pontas. Enxágue. Se necessário, repita o procedimento.', 1063.0, 1063.0, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rdvr-m15pimp2dul5d1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F21797926006', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498880592', 'Bio Extratus +Nutrição - Reparador de Pontas 55ml', 'Bio Extratus +Nutrição - Pontas Renovadas com Nutrição Intensa Recupera pontas danificadas e ressecadas, devolvendo brilho e maciez instantaneamente. Sua fórmula rica em nutrientes e óleos nobres, promove um tratamento intensivo que fortalece, sela e protege os fios contra agressões externas. Resultando em pontas saudáveis, sem frizz e com aspecto renovado. Conselho de Aplicação Aplique uma pequena quantidade nos cabelos limpos e úmidos, do meio às pontas. Finalize com secador, chapinha ou deixe secar naturalmente.', 112.55, 63.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-824hp-me8ug9clet4xf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22498880592', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
