INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9473793940', 'Pano De Prato Bainha O Legitimo Branco Atacado Kit Com 5 Peças', 'Clássico mais eficiente, Pano de prato Branco nunca perde suas funcionalidades Pano de prato sacaria de alta qualidade, com excelente absorção, alem da absorção nossos panos de prato são anti-manchas, você pode lavar em água sanitária sem medo de manchar. Contém 5 unidades Estampas: Todo Branco Especificações: Trama 12 acabamento em bainha com costura reforçada Medidas: 41 largura x 66 altura cm Marca: Têxtil H. Carvalho (O Legitimo) LAVAGEM: Nossos panos de prato são de excelente qualidade, além de não manchar com água sanitária. Descrição: O tecido branco do pano de prato é feito em sacaria 100% algodão de excelente qualidade, (conhecido por donas de casa como pé de galinha).', 49.99, 49.99, NULL, 'Home & Living > Home Care Supplies > Cleaning Cloths', 'https://cf.shopee.com.br/file/fc88a89d0fdbc0bba55381a87b30e471', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F388739239%2F9473793940', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
