INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23405385666', 'TÍTULO DO PRODUTO: KIT 10 PLAQUINHAS DIVERTIDAS SELFIE REVEILLON ANO NOVO 2023 (COD 01)', 'REVIVA A ALEGRIA DA VIRADA DE 2023 COM ESTE KIT DE 10 PLAQUINHAS COM FRASES TEMÁTICAS (CÓDIGO 01) PARA SELFIES NA SUA FESTA DE ANO NOVO! IDEAIS PARA FOTOS DESCONTRAÍDAS COM OS AMIGOS E FAMILIARES, RELEMBRANDO OS BONS MOMENTOS DA CELEBRAÇÃO. CADA PLAQUINHA JÁ VEM COLADA EM UM PALITO DE PLÁSTICO RESISTENTE, PRONTA PARA USAR E GARANTIR MUITAS RISADAS AO RECORDAR A FESTA! CONTEÚDO: 10 PLAQUINHAS COM FRASES VARIADAS TEMÁTICAS DE FESTA DE ANO NOVO 2023. CADA PLAQUINHA JÁ VAI COLADA EM UM PALITO DE PLÁSTICO RESISTENTE. TAMANHO: PLAQUINHAS: TAMANHOS VARIADOS, APROXIMADAMENTE 15 CM A 20 CM DE LARGURA. PALITOS: APROXIMADAMENTE 20 CM DE COMPRIMENTO. MATERIAL: PRODUZIDAS EM PAPEL CARTONADO RESISTENTE COM IMPRESSÃO COLORIDA E VIBRANTE, COM DETALHES EM DOURADO OU PRATEADO PARA CELEBRAR A VIRADA. PALITOS DE PLÁSTICO RESISTENTE. ATENÇÃO ❗: AS FRASES DAS PLAQUINHAS PODEM VARIAR LIGEIRAMENTE DEPENDENDO DO LOTE. TODAS AS PLAQUINHAS DESTE KIT ACOMPANHAM PALITO DE PLÁSTICO RESISTENTE. VERIFIQUE O PRAZO DE ENVIO 🚚 ANTES DE FINALIZAR A COMPRA. RELEMBRE A FESTA DA VIRADA DE 2023 COM MUITA ALEGRIA E FOTOS INCRÍVEIS! ADICIONE ESTE KIT DE PLAQUINHAS AO SEU CARRINHO! 🥂🎉🥳', 19.85, 19.85, NULL, 'Home & Living > Party Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-22110-4x6h1eu4yvjv49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F23405385666', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
