INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18898150507', 'Avitrin Coveli Todos os Modelos', 'Linha Avitrin – Saúde e Bem-estar para suas Aves A linha Avitrin oferece uma variedade completa de suplementos e medicamentos especialmente desenvolvidos para a saúde de aves ornamentais, como canários, periquitos, calopsitas, papagaios e outras espécies domésticas. Com fórmulas confiáveis e fácil administração, os produtos Avitrin atendem diversas necessidades, como: - Vitaminas e Minerais: reforço nutricional para aves em crescimento, muda de penas ou reprodutivas. - Estimulantes e Fortificantes: melhora da disposição e vitalidade. - Antibióticos e Antiparasitários: tratamento eficaz contra infecções e verminoses. - Suplementos específicos: como cálcio, ferro e aminoácidos essenciais. - Vermífugos A Avitrin é uma marca tradicional e reconhecida no cuidado com aves, oferecendo segurança, qualidade e resultados comprovados. Ideal para criadores e tutores que desejam o melhor para seus pássaros.', 39.99, 14.9, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/sg-11134201-7rfgj-m9m78u1l8u1h95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F18898150507', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499368683', 'Kit 2 Sistema de Terapia Real H Homeo Pet Displasia - 30 mL', '🐾 Homeopet Displasia – Liberdade de Movimento para seu Melhor Amigo! Seu pet está com dificuldade para levantar, mancando ou evitando brincadeiras? Não deixe a dor limitar a alegria dele! O Homeopet Displasia é a solução natural e eficaz para devolver o bem-estar e a mobilidade que seu cão ou gato merece. 🐕🐈 Desenvolvido com tecnologia homeopática de ponta, ele trata e previne a displasia coxofemoral sem causar efeitos colaterais. É mais saúde, mais saltos e mais amor em cada passo! ✨ POR QUE ESCOLHER O HOMEOPET DISPLASIA? ✅ Alívio da Dor: Atua diretamente nos sintomas locomotores e na rigidez. ✅ Fortalecimento Real: Auxilia na regeneração e proteção das cartilagens. ✅ 100% Seguro: Sem contraindicações, ideal para filhotes, idosos e fêmeas gestantes. ✅ Prevenção Eficaz: Proteja raças predispostas antes mesmo dos primeiros sinais aparecerem. ✅ Multifuncional: Também auxilia no tratamento de colapso de traqueia. 📋 QUANDO USAR? • Pets com diagnóstico de displasia coxofemoral. • Animais que mancam ou têm dificuldade para subir escadas/sofás. • Filhotes de raças grandes (Labrador, Pastor Alemão, Golden, etc.) para prevenção. • Fêmeas gestantes (a partir da 2ª semana) para fortalecer a ninhada. • Pets idosos com desgaste articular natural. ⚠️ INFORMAÇÕES IMPORTANTES: Segurança: Pode ser usado com outros medicamentos sem interações negativas. Intervalo: Se usar outros produtos HomeoPet, aguarde 10 minutos entre eles. Praticidade: Aplicação spray que não estressa o animal. Garanta agora e veja seu pet feliz e ativo novamente! 🛒✨', 241.91, 185.9, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lz82zimi6npx8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F20499368683', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52062435497', 'Kit 3 Areia Eco Gold Biodegradável Fina MyPetOne 4Kg', 'Areia Biodegradável Eco Gold Fina MyPetOne – 4Kg A Areia Biodegradável Eco Gold Fina MyPetOne foi criada para unir praticidade, desempenho superior e responsabilidade ambiental. Produzida à base de milho e mandioca, matérias-primas naturais e renováveis, ela garante um controle eficiente de odores, aglomeração rápida e firme, além de ser 100% biodegradável. Com grãos finos, proporciona maior conforto para o gato, formando torrões ainda mais consistentes e fáceis de remover. Sua textura ajuda a manter a bandeja sempre seca, reduzindo odores e facilitando a limpeza diária. Além disso, seu descarte é ecológico, podendo ser destinado ao lixo orgânico, composteira ou até mesmo ao vaso sanitário em pequenas quantidades. Benefícios - 100% biodegradável e sustentável - Grãos finos que oferecem maior conforto para o gato - Torrões firmes e consistentes para remoção prática - Controle eficaz de odores indesejados - Alta absorção e higiene prolongada Modo de Uso - Preencha a caixa de areia com uma camada de pelo menos 5 cm da Areia Bio Gold MyPetOne - Remova e descarte diariamente os torrões formados e as fezes - Complete a caixa conforme a necessidade para manter a altura indicada Informações Técnicas - Composição: Milho e mandioca - Peso líquido: 4 Kg - Indicação: Gatos de todas as raças - Origem: Indústria Brasileira Uma escolha prática, higiênica e sustentável que garante bem-estar ao seu gato e mais tranquilidade no seu dia a dia', 165.05, 111.44, NULL, 'Pets > Litter & Toilet > Cat Litter & Boxes', 'https://cf.shopee.com.br/file/br-11134207-820m8-mpm9pfpohv5td9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F52062435497', NULL, NULL, '2026-07-28T02:11:31.708458+00:00