INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898468749', '1~6 DECORAÇÃO LANTERNA SANFONADA 27CM-6132-34 FESTA JUNINA (EX) (CHOCO)', 'PARA DEIXAR SEU ARRAIÁ DE 2025 AINDA MAIS CHARMOSO E ILUMINADO! OLHA SÓ ESSA LANTERNA SANFONADA: 1 DECORAÇÃO LANTERNA SANFONADA 27CM DE COMPRIMENTO - 6132-34 FESTA JUNINA 2025 (EIXO FIRME) ✨ ILUMINE SUA FESTA JUNINA COM UM TOQUE TRADICIONAL E COLORIDO! ESSA LANTERNA SANFONADA DE PAPEL É PERFEITA PARA DECORAR O AMBIENTE, CRIANDO UM CLIMA ACONCHEGANTE E FESTIVO. COM SEU EIXO FIRME, É FÁCIL DE PENDURAR E ADICIONA UM CHARME ESPECIAL À DECORAÇÃO. 📏 DIMENSÕES: 27 CM DE COMPRIMENTO 🎨 MODELO: 6132-34 (VERIFICAR DISPONIBILIDADE DE CORES E ESTAMPAS) 🏮 TEMA: FESTA JUNINA ✔️ IDEAL PARA: ✔️ DECORAR BARRACAS, SALÕES E ÁREAS EXTERNAS DA FESTA. ✔️ CRIAR PONTOS DE LUZ DECORATIVOS COM UM VISUAL SANFONADO. ✔️ COMPLEMENTAR A DECORAÇÃO JUNINA COM CORES E FORMAS TÍPICAS. 🇧🇷 PREPARE-SE PARA UM ARRAIÁ INESQUECÍVEL EM 2025 COM DETALHES QUE FAZEM A DIFERENÇA! ESSA LANTERNA SANFONADA VAI TRAZER MAIS COR E ALEGRIA PARA SUA FESTA. ⚠️ OBSERVAÇÃO: AS CORES E ESTAMPAS PODEM VARIAR. VERIFICAR A DISPONIBILIDADE DO MODELO 6132-34. 🚫 NÃO PERSONALIZAMOS ESTE PRODUTO. 🛒 ADICIONE UM TOQUE DE COR E TRADIÇÃO À SUA FESTA JUNINA! GARANTA JÁ SUA LANTERNA SANFONADA! IMPORTANTE: VERIFIQUE OS PRAZOS DE ENTREGA E O VALOR DO FRETE PARA SUA REGIÃO DURANTE A SIMULAÇÃO DA COMPRA.', 13.85, 13.85, NULL, 'Stationery > Gift & Wrapping > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-maa0blt7i8ah0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F22898468749', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
