INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49058587435', 'Fogareiro Portátil Frontier Com Maleta Azul Nautika', 'Fogareiro Portátil Frontier com Maleta 280450 Nautika CARACTERÍSTICAS: - Garantia: 3 Meses - Tipo: Fogareiro Portátil - Modelo: Frontier - Material: Aço esmaltado com enamel atóxico - Combustível: Gás e GLP - Acendimento: Ignição eletrônica automática - Sistema de segurança: Bloqueio automático do fluxo de gás - Portátil: Sim - Acompanha maleta: Sim - Dimensões aproximadas: 3 x 30,5 x 8,9 cm (C x L x A) - Peso aproximado: 2,1 kg - Uso: Camping, viagens e uso doméstico - Código SKU: 280450-UN - Marca: Nautika DETALHES: - O Fogareiro Portátil Frontier Nautika é ideal para quem busca praticidade, segurança e eficiência no preparo de alimentos em qualquer lugar. - Possui sistema de ignição eletrônica automática, permitindo acendimento rápido e sem necessidade de fósforos ou isqueiros. - Conta com sistema de segurança com bloqueio automático do fluxo de gás, garantindo mais proteção durante o uso. - Compatível com cartuchos Campgás e GLP, oferecendo versatilidade e facilidade na escolha do combustível. - Fabricado em aço esmaltado com acabamento atóxico, proporciona maior durabilidade, resistência e segurança no preparo dos alimentos. - Seu design compacto e portátil facilita o transporte e armazenamento. - Acompanha maleta resistente, ideal para proteger o fogareiro e transportar com segurança em viagens e aventuras. - Perfeito para camping, pescarias, trilhas ou até mesmo como opção prática para uso doméstico. - Produto essencial para quem busca mobilidade, praticidade e confiabilidade em qualquer situação. - Une desempenho, segurança e facilidade de uso em um único equipamento. CONTEÚDO DA EMBALAGEM: - 1 Fogareiro Portátil Frontier Nautika - 1 Maleta de transporte', 139.9, 112.5, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/br-11134207-820ln-mq1wim3x3gn6e9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844004880%2F49058587435', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
