INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251144865', 'Regata Infantil Feminina Lilica Ripilica', 'Match perfeito entre delicadeza e conforto, a Blusa Regata Lilica Ripilica em malha laise comfy promete deixar as meninas ainda mais lindas nessa estação! As alças com babados e o babado peplum na cintura garantem um charme especial para o look. Já o decote quadrado nas costas com elástico e Forro voil em algodão oferece conforto para cada movimento das meninas. Além disso, um aplique de flor com a assinatura da marca traz elegância para o visual. Aposte nesse must-have e componha looks incríveis! • Blusa Regata • Possui alças com babados • Detalhe em babado na cintura • Possui Forro voil em algodão • Malha laise comfy', 299.0, 149.5, NULL, 'Baby & Kids Fashion > Girl Clothes > Tops', 'https://cf.shopee.com.br/file/sg-11134201-8227b-mhkryqpmz6yr44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F980954412%2F58251144865', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
