INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19997457997', 'Livro -Mamãe bruxa: a história da vilã da Rapunzel - Universo dos Livros', 'LOJA OFICIAL - LIVRARIA LEITURA PARQUE D.PEDRO - Neste livro, o leitor conhecerá uma história sobre mães e filhas, sobre juventude e magia. É a história da vilã da Rapunzel, a Mamãe Gothel.A história da legendária flor dourada é muito popular, tendo sido contada de diversas maneiras e ao longo de gerações. No entanto, todas as versões concordam em um aspecto: a flor é sempre o objeto de desejo de uma velha bruxa, cuja ambição é se manter bela e jovem. A flor, por sua vez, sempre é usada para salvar uma rainha à beira da morte, que dá à luz uma princesa com cabelos mágicos: Rapunzel. Por isso, a fim de evitar a perda de sua fonte da juventude, a feiticeira sequestra a princesa, tranca-a em uma torre distante e passa a criá-la como sua filha. Anos depois, Rapunzel descobre sua verdadeira identidade e dá um jeito de derrotar a velha bruxa.Entretanto, esta é apenas a metade da história. O que houve com a velha bruxa, conhecida como Mamãe Gothel? Qual é a sua origem e qual foi o caminho que a levou a encontrar a flor mágica, tornando-se obcecada pela juventude eterna? Toda história tem dois pontos de vista.', 63.19, 63.19, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lneofz4qv4y43b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F19997457997', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18797692920', 'Dragon Ball Super Vol. 2 - Panini', 'Os Deuses da Destruição do Sexto e Sétimo Universo entram em uma disputa pelas Superesferas do Dragão em um torneio de artes marciais. Um competidor muito parecido com o temido Freeza aparece e deixa o Goku intrigado… Qual será o verdadeiro poder desse misterioso oponente?', 45.59, 45.59, NULL, 'Books & Magazines > Books > Romance', 'https://cf.shopee.com.br/file/sg-11134201-7rd6w-lvuat62lw6050a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F18797692920', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
