INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398377882', 'Telha Trapezoidal Galvanizada em Aluzinco 300cm x 100cm - 10 unidades', 'Kit 10 Telha Galvanizada Aluzinco Trapezoidal TP-40 Telha Galvanizada Aluzinco Trapezoidal TP-40, é composta de alumínio (55%), zinco (43,5%) e silício (1,5%). É revestida por 150 g/m² de liga de alumínio-zinco aplicado por processo de imersão a quente em linha de galvanização contínua. Apresenta resistência à corrosão oferecida pelo alumínio e proteção galvânica oferecida pelo zinco. Indicada para coberturas e fechamentos laterais de galpões ou então Tapumes de obras. Vantagens: Maior durabilidade para sua cobertura; Menos peso na estrutura; Menos tempo para instalação; Não quebra na montagem; Maior vazão de água mesmo com montagem de 10° no caimento. Kit 10 unidades Telhas Trapezoidal TP-40 Dimensões: Tamanho da Telha (área de cobertura) L: 98cm C: 300cm Área de cobertura: 29,40 m² Garantia: 03 Meses Inclinação: 5 Galvanizada: Sim Impermeável: Sim Espessura (mm): 43 Modelo da Telha: Trapezoidal Acompanha Fixação: Não Origem do Produto: Nacional Recursos Especiais: Convencional Número de Telhas por m²: 1 Informações Complementares (Novo): Telha Trapezoidal TP-40 Marca: Deibe Móveis Cor do Produto: Alumínio Itens Inclusos: 10 Telhas Cor Predominante: Prata Linha ou Coleção: 2025', 1790.99, 1790.99, NULL, 'Home & Living > Tools & Home Improvement > Roofing & Flooring', 'https://cf.shopee.com.br/file/sg-11134201-7rd5f-m7x8v2tosski8d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F22398377882', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698101316', 'Arranhador Adesivo para Gatos Premium Protetor de Sofá e Cama Box - Carpete de Alta Qualidade', 'Arranhador Adesivo Premium para Gatos Protetor de Sofá e Cama Box - Carpete de Alta Qualidade Proteja Seus Móveis com Estilo! Cansado de ver seu gato arranhando seus móveis? Temos a solução perfeita para você e seu pet! Destaques do Produto: Carpete Autoadesivo Irresistível: Desenvolvido especialmente para atrair os felinos e satisfazer seu instinto natural de arranhar. Design Versátil e Funcional: Combina com qualquer ambiente e pode ser usado em diversas superfícies. Proteção para Seus Móveis: Ajuda a manter as unhas do seu gato saudáveis enquanto preserva sua casa intacta. Por Que Seu Gato Vai Amar? Os gatos arranham para cuidar das unhas e liberar energia. O carpete de fibra 100% poliéster oferece uma textura ideal, proporcionando uma experiência prazerosa e saudável para o seu pet. Especificações Técnicas: Material: Carpete de fibra 100% poliéster. Dimensões: 50 cm (comprimento) x 30 cm (largura). Escolha a Quantidade Ideal: 1 ou 2 Unidades Informações Adicionais: Pequenas variações na tonalidade podem ocorrer. Pequenas variações no tamanho podem ocorrer (1cm) Garanta Agora Mesmo! Não espere mais para proteger seus móveis e proporcionar conforto ao seu gato. Clique em "Adicionar ao Carrinho" e leve já o seu arranhador com o melhor preço! Agradecemos por visitar nossa loja. Qualquer dúvida, estamos aqui para ajudar!', 34.99, 17.9, NULL, 'Pets > Pet Accessories > Pet Furniture', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjkpuwn342ddd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F908280603%2F22698101316', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
