INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799264633', 'Balcão Atendimento de Canto para Recepção 2 Gavetas Branco', 'Os balcões de atendimento da Linha Office da NetMobil são uma excelente opção para aqueles que procuram qualidade e conforto para o seu ambiente, seja ele seu escritório, empresa ou casa. Seus traços modernos trazem fácil adaptabilidade à diferentes cenários. O material utilizado na fabricação do produto é o MDP e o acabamento das bordas em ABS. Garantindo a mais alta qualidade e durabilidade aos nossos clientes. DESCRIÇÃO TÉCNICA DO PRODUTO - Altura (cm): 114 - Largura (cm): 140 - Profundidade (cm): 60 - Material: MDP - Bordas: ABS - Sapatas Reguladoras de Nível: Sim - É necessário montagem: Sim (acompanha manual) - Dificuldade da Montagem: Fácil - Laterais e fundo em 15mm de espessura. Garantia: 03 Meses Altura (cm): 108 Largura (cm): 140 Possui Pés: Não Possui Grade: Não Possui Portas: Não Possui Gavetas: Sim Suporta Até (kg): 50 Acompanha Tampo: Sim Profundidade (cm): 60 Suporta Granito: Não Gaveta com Chave: Sim Material do Tampo: MDP Origem do Produto: Nacional Ambiente Principal: Comércio Material da Gaveta: MDP Material Principal: MDP Necessita Montagem: Sim Possui Prateleiras: Não Sapatas Niveladoras: Sim Material da Estrutura: MDP Peso Máximo por Gaveta: 15 Complexidade da Montagem: Baixa: pode ser montado por uma pessoa sozinha Tipo de Puxador da Gaveta: Externo Tipo de Corrediça da Gaveta: Metálica Simples Marca: Netmobil Cor: Branco Itens Inclusos: 1 Produto, 1 Kit de Montagem Quantidade de Gavetas: 02 Gavetas', 1598.68, 1598.68, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-8258g-mr3b6bdnpb7q3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F21799264633', NULL, NULL, '2026-07-28T02:11:31.708458