INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293492688', 'Compressor De Ar Tipo Pistola Bateria 20 V Cpv 20N Vonder', 'Compressor de ar tipo pistola, bateria 20 V, CPV 20N VONDER Compacto, portátil e pronto para uso. Possui LED para melhor visibilidade e visor/indicador de pressão digital. Indicado para encher balões, bolas, boias, pneus de carros e bicicletas. Devido o compressor tipo pistola CPV 20 VONDER não ser calibrado, sempre utilize medidores de pressão para verificar a pressão dos pneus. Modelo: CPV 20N Bateria: 20 V - 2,0 Ah - íons de lítio Capacidade de produção de ar (deslocamento teórico): 6 L/min Pressão máxima de trabalho: 150 lbf/pol² Tensão do carregador de bateria: 100 V~ - 240 V~ - Bivolt automático Frequência (Hz): 50 Hz/60 Hz Nível de ruído: 83 dB(A) Segue norma(s) (nome/sigla): ABNT NBR IEC 60745-1 Dimensões (C x L x A) (mm): 180 mm x 77 mm x 255 mm Aceleração transmitida nas mãos - braços do operador - ah: 2,4 m/s² Incerteza da aceleração transmitida nas mãos - braços do operador - k: 1,5 m/s² Massa aproximada (peso) (kg): 1,998 kg Conteúdo da Embalagem: 1 Compressor tipo pistola. Acompanha: 1 maleta, 1 bateria de 20 V, 1 carregador bivolt automático, 1 bico adaptador para bolas, 1 bico adaptador para uso geral, 1 adaptador para válvulas e 1 mangueira flexível com bico.', 473.07, 356.92, NULL, 'Home & Living > Tools & Home Improvement > Air Pumps, Parts & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rd4u-lvyygowmmpm300', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23293492688', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
