INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793172611', 'Kit Pastilhas e Lonas de Freio Fazer 250 2005-2015 Sob Medida 0.25 Diafrag', 'Kit Pastilhas + Lonas de Freio Diafrag Lona Traseira Sob Medida 0.25 Ideal para cubo desgastado Compatível com: YAMAHA Fazer 250 2005 Fazer 250 2006 Fazer 250 2007 Fazer 250 2008 Fazer 250 2009 Fazer 250 2010 Fazer 250 2011 Fazer 250 2012 Fazer 250 2013 Fazer 250 2014 Fazer 250 2015 Conteúdo da Embalagem: - 01 Par de Pastilhas de Freio Dianteira Diafrag Urban Tech (orgânica) - 01 Par de Lonas de Freio Traseira Diafrag (Sob Medida 0.25) Especificações Técnicas das Pastilhas: - Modelo: URBAN TECH ORGANICA - Material: ferro / lona - Produzido com melhores equipamentos garantindo segurança e durabilidade. - Oferecendo o melhor custo beneficio, unindo qualidade e eficiência na sua utilidade. - Possui medidas originais - Melhor dissipação de calor e atrito com o disco de freio - Ideal Para Reposição - Maior segurança ao motociclista - Alta Qualidade E Resistência Especificações Técnicas Lonas: - Sapata De Freio Com Medidas Originais - Reduz O Nível De Ruídos E Oferece Frenagens Seguras - Durabilidade - Frenagem de alto desempenho - Segurança ao motociclista - Ideal Para Reposição - Alta Qualidade E Resistência A Dia-Frag possui ampla know-how na fabricação de alumínio, materiais de fricção e borracha, e se destaca entre a tecnologia de ponta e as modernas instalações fabris com máquinas de precisão, laboratórios de ensaios, metrologia e equipamentos de precisão. Possui certificados de qualidade nacionais e internacionais. Isso mostra que todos os produtos são produzidos de acordo com as mais rígidas normas técnicas de fabricação e controle de qualidade. Importante Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto. Ver