INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893427640', 'L''Oréal Professionnel Serie Expert Absolut Repair Gold Quinoa Protein - Shampoo 300ml', 'Shampoo para cabelos danificados. L''Oréal Professionnel Serie Expert Absolut Repair Gold Quinoa + Protein Instant Resurfacing reestrutura a fibra capilar, confere brilho e leveza durante a limpeza diária dos fios. O Shampoo Absolut Repair Gold Quinoa + Protein L''Oréal Professionnel traz ativos que ajudam restaurar a superfície dos fios para que o cabelo revele uma aparência mais saudável. Com shampoo Absolut Repair seu visual ganha muito mais brilho e um toque macio incrível. Conselho de Aplicação Aplique o shampoo sobre o cabelo molhado e massageie com suavidade. Enxágue e, se necessário, repita o processo. Lembre-se sempre de colocar o shampoo na mão, e esfregá-lo nas suas palmas antes de passar no couro cabeludo. Isso evita com que o produto fique concentrado em apenas uma região do cabeludo.', 188.2, 126.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rdy6-m1d2z14fij5q73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22893427640', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198545661', 'Bio Extratus Homem 3 em 1 - Shampoo 250ml', 'Bio Extratus Homem 3 em 1 - Shampoo 250ml Fórmula multifuncional que associa o poder nutritivo da cevada à refrescância da hortelã. Limpa e condiciona os cabelos. Facilita o deslizamento da lâmina durante o barbear, deixando a pele macia e perfumada. Conselho de Aplicação Aplique nos cabelos molhados massageando suavemente. Enxágue. Se necessário, repita a aplicação. Para barbear, espalhe o produto no rosto umedecido e barbeie como de costume. Enxague.', 112.75, 58.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7ravr-ma4bps76xeq7fe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22198545661', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
