INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497677009', 'Guarda Roupa Solteiro 2 Portas 2 Gavetas Costa Rica Cinamomo', 'Este lindo Guarda Roupa Costa Rica Sallêto é fabricado em MDP/MDF, diferenciado pela sua resistência, durabilidade, funcionalidade e beleza, ele é a melhor opção para deixar seu dormitório mais arrumado e convidativo. Com corrediças telescópicas que permitem uma abertura total das gavetas, Portas de correr com trilho em alumínio com trava de segurança evitando que a porta se solte do trilho, costa inteiriça sem perfil H, parte interna clean toda branca, divisões internas amplas quem oferecem praticidade e organização, contando também com sapateira embutida. Se encaixa facilmente em vários estilos de decoração. Aproveite, você merece! Estilo: Moderno Modular: Não Peso (kg): 73 Garantia: 03 Meses Altura (cm): 208 Acabamento: Pintura UV Largura (cm): 126.5 Possui Pés: Não Possui Nichos: Não Possui Portas: Sim Possui Gavetas: Sim Tipo de Gaveta: Interna Profundidade (cm): 47 Possui Calceiros: 1 Material da Porta: MDP Origem do Produto: Nacional Possui Cabideiros: Sim Ambiente Principal: Quarto Material da Gaveta: MDF Material Principal: MDF/MDP Necessita Montagem: Sim Possui Penteadeira: Não Possui Prateleiras: Sim Acabamento da Porta: Pintura Texturizada UV Nicho com Cabideiro: Não Espessura do Fundo (mm): 3 Material da Prateleira: MDP Peso Máximo por Gaveta: 5 Espessura das Portas (mm): 15 Acabamento da Prateleira: Pintura Texturizada UV Complexidade da Montagem: Alta: deve ser montado por um montador especializado Espessura da Estrutura (mm): 12 Peso Máximo por Prateleira: 8 Tipo de Corrediça da Gaveta: Metálica Telescópica Espessura das Prateleiras (mm): 12 Material do Puxador da Porta: MDF Espessura do Fundo das Gavetas (mm): 3 Tipo de Dobradiça/Corrediça da Porta: Metálica Telescópica Marca: Sallêto Móveis Cor: Cinamomo Itens Inclusos: 1 Guarda Roupa, kit ferragens e manual de montagem. Linha ou Coleção: Costa Rica Cor do Puxador: Marrom Quantidade de Portas: 2 Portas Quantidade de Portas com Espelhos: Nenhuma', 944.09, 944.09, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-824gb-mpn9b56icbnld7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F18497677009', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55559645260', 'Viseira Fumê Pro Tork Liberty 4 Liberty 5 R8 + Kit Reparo Lateral', 'Viseira Fumê com Reparo Liberty 4 / 5 R8 Pro Tork – Completa Viseira fumê desenvolvida para capacetes Pro Tork Liberty 4 e Liberty 5 (Liberty Four), R8 ideal para reposição com encaixe preciso e instalação simples. Produto com excelente acabamento, proporcionando melhor proteção contra vento, poeira e luminosidade no uso diário. Fabricada com material resistente, oferece boa durabilidade e mantém a visibilidade adequada durante a pilotagem, além de valorizar o visual do capacete com acabamento fumê. Compatibilidade Pro Tork Liberty 4 Pro Tork Liberty 5 Pro Tork R8 Liberty Four Especificações Técnicas Cor: Fumê Espessura: 2mm Material: Policarbonato resistente Fixação: Sistema com reparo (kit completo) Instalação: Encaixe padrão, sem adaptação Benefícios Reduz a incidência de luz solar Melhora o conforto visual na pilotagem Proteção contra vento e detritos Encaixe preciso e firme Instalação rápida e prática Conteúdo da Embalagem 01 Viseira fumê 01 Kit reparo completo Importante Antes da compra, confirme se o modelo do seu capacete é Liberty 4 ou Liberty 5. Recomendamos que a instalação seja realizada corretamente para garantir o melhor desempenho do produto.', 54.99, 42.99, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmet Visor Shields', 'https://cf.shopee.com.br/file/br-11134207-820lt-mqgq3ziao8ow18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1302754239%2F55559645260', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201839889', 'Refil de Folhas Reposicionável para Caderno Smart Universitário Rosa - DAC', 'Refil de Folhas Caderno Smart Universitário Rosa - DAC Reponha ou acrescente novas folhas ao seu Caderno Smart com o Refil DAC Rosa, ideal para quem busca praticidade e cor nas anotações. As folhas com pauta branca mantêm tudo alinhado e organizado, e o papel 90g garante escrita suave e sem transparência. Compatível com o Caderno Universitário Smart da marca DAC, é um refil indispensável para continuar escrevendo com estilo. Ficha Técnica: Quantidade: 1 pacote com 48 folhas Tamanho: Universitário - 27,5 cm x 20 cm Tipo: Reposicionável - 21 furos Cor da folha: Rosa Tipo de folha: Com linha ( pauta ) Cor da linha : Branca Gramatura: 90g Composição: Papel off-set 90g/m² Compatibilidade: Caderno Smart Universitário da marca DAC Marca: DAC Palavras-chave: refil caderno smart rosa DAC, folhas pautadas rosa, refil universitário DAC, folhas reposição caderno smart, papel 90g DAC, folhas avulsas caderno smart, refil de folhas universitário DAC, caderno inteligente, caderno reposicionável, caderno de disco, caderno smart inteligente', 46.9, 46.9, NULL, 'Stationery > Notebooks & Papers > Notebooks & Notepads', 'https://cf.shopee.com.br/file/sg-11134201-822y5-mi5barc7ow7592', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1042749449%2F58201839889', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
