INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998332465', 'Limpa Vidros Tira Manchas Antiembacante Luxcar 500 Ml', 'LIMPA VIDROS LUXCAR 500 ML --------------------------------------------------------------------------------------- O LIMPA VIDROS LUXCAR E FORMULADO ESPECIALMENTE PARA A LIMPEZA DE VIDROS E ESPELHOS AUTOMOTIVOS. ELE DESENGRAXA E CRIA UMA PELICULA PROTETORA DIMINUINDO O EMBACAMENTO. --------------------------------------------------------------------------------------- CONTEUDO NA EMBALAGEM: 1 NOTA FISCAL 1 LIMPA VIDROS LUXCAR 500 ML --------------------------------------------------------------------------------------- CARACTERISTICAS DO PRODUTO: IMAGEM ILUSTRATIVA ALTA QUALIDADE E DURABILIDADE COD INTERNO DO PRODUTO: 11020064 --------------------------------------------------------------------------------------- ANTES DE FINALIZAR A COMPRA: VERIFIQUE COM MUITA ATENCAO ATRAVES DAS FOTOS E DESCRICAO SE O PRODUTO E COMPATIVEL COM O MODELO QUE DESEJA ADQUIRIR. NOS NAO NOS RESPONSABILIZAMOS POR MA INSTALACAO OU MAU USO DO PRODUTO. PARA EVITAR TRANSTORNO PROCURE UM PROFISSIONAL ESPECIALIZADO.', 26.8, 26.8, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd3q-m7mn98995f0t2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F390168708%2F23998332465', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200024549', 'Cama Box e Colchão Airtech Spring Pocket - Queen (158x198)', 'O Conjunto Ortobom Airtech Spring Pocket foi desenvolvido para oferecer noites de sono mais tranquilas, com o equilíbrio ideal entre conforto, estabilidade e design moderno. O colchão Airtech Spring Pocket Queen Ortobom (25x158x198 cm) conta com o sistema de molas ensacadas Superpocket, que atuam de forma independente, proporcionando suporte personalizado e reduzindo a transferência de movimentos entre os lados . O Ortopillow em espuma D26 Pró Aditivada adiciona uma camada extra de maciez e adaptação ao corpo, garantindo um toque suave e aconchegante. Seu revestimento em malha mantém o colchão fresco e agradável ao toque, enquanto o bordado em matelassê e as laterais em camurça realçam o visual sofisticado. A tecnologia No Turn dispensa a necessidade de virar o colchão, preservando sua performance por mais tempo. Com tratamentos antiácaro e antialérgico, o ambiente de sono se torna mais limpo e saudável. Suporta até 120 kg por pessoa. A Base Sommier Ortobom, revestida em Corino branco, complementa o conjunto com um toque moderno e elegante. Sua estrutura em madeira de reflorestamento e espuma de poliuretano assegura resistência e durabilidade, suportando até 150 kg por lado (além do colchão). Com 36 cm de altura total (23 cm da base + 13 cm dos pés), proporciona o apoio e a elevação ideais para o colchão. Com design harmonioso e acabamento premium, o Conjunto Ortobom Airtech Spring Pocket transforma o quarto em um espaço de conforto, elegância e bem-estar, garantindo noites revigorantes e um descanso de alta qualidade. Garantia do Colchão Airtech Spring Pocket: 12 meses Garantia da Base Sommier: 12 meses', 2284.9, 2010.71, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-82595-mgdmoshwcyyz56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1537615778%2F58200024549', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19025832041', 'Inseticida Aerossol Raid Ação Total 285ml', 'Raid Ação Total possui fórmula de alta eficácia, que age contra insetos voadores e rasteiros. Mata formigas, baratas e moscas e acaba com problemas de infestação de mosquitos, incluindo os que podem transmitir a dengue, o zika vírus e a febre Chikungunya.', 27.39, 27.39, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/8bd9661a08eaa373cfdcdf573b3bb0e1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819102498%2F19025832041', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29017253435', 'Lanterna Recarregável Sofirn Green SC18 USB Tipo C , Luz Pequena Super Brilhante Para Emergência , LED SST-40 De Alta Po', 'Pacote da Embalagem: Conjunto SC18 com clipe dourado (conjunto SC18 com clipe dourado)Verde SC18: a embalagem contém um difusor dentro): tocha SC18, uma bateria de 18650, 1 cabo de carregamento USB, 1 manual do usuário, 2 o-rings sobressalentes, 1 clipe dourado Bateria SC18 com bateria(Verde Embalagem contém um difusor dentro): SC18Torch, uma bateria de 18650, 1 cabo de carregamento USB, 1 manual do usuário, 2 o-rings sobressalentes): SC18Torch, uma bateria de 18650, 1 cabo de carregamento USB, 1 manual do usuário, 2 o-rings sobressal 1.Entrega em 24 horas 2. Orientado por alta qualidade e serviço 3. Siga nossa loja e ganhe cupons Nossa loja fornece vários equipamentos de iluminação ao ar livre, como lanternas, faróis, luzes de acampamento, luzes de bicicleta, luzes de trabalho, luzes de pesca, etc. Todos os pedidos serão enviados dentro de 24 horas após os dias úteis, e os pedidos nos fins de semana e feriados serão enviados dentro do próximo dia útil. Se você tiver alguma dúvida, sinta-se à vontade para entrar em contato conosco através do chat e responderemos o mais rápido possível. A Sofirn SC18 é a das lanternas EDC compactas mais poderosas do mercado. Proporciona uma saída incomparável de 3 lúmens a 1800 lúmens amplamente utilizado na leitura noturna para pesquisa ao ar livre, tornando a SC18 um companheiro prático para uso diário. Características da Embalagem: Desempenho de chumbo: Esta lanterna LED está equipada com Luminus SST-40, acendendo facilmente o caminho à sua frente com arremesso significativamente melhorado: entrega uma saída máxima de 1800lm a uma distância de até 217 Produzindo um perfil de feixe particularmente macio e equilibrado para preservar uma visão confortável. Recarregável USB Tipo C integrado, ele recarregará rapidamente em qualquer lugar se houver acesso a uma tomada USB Tipo C integrada, ele recarregará rapidamente em qualquer lugar se houver acesso a uma tomada USB. Totalmente carregado a bateria 18650 recarregável 3000mAh incluída em 60 minutos através de um cabo USB Tipo a para USB Tipo C e um carregador 5V/2A sem desmontar a luz. Mais fácil do que nunca. Aprox. Bateria totalmente carregada.. 3 horas a 350lm (Médio) ao usar uma bateria totalmente carregada. Operação de uso diário: Acesse diferentes saídas com os interruptores eletrônicos laterais para qualquer cenário de uso diário. Lembrete de nível de bateria no interruptor lateral para obter um lembrete de nível de bateria de relance. Possui seis níveis de brilho: Lua(3Lm)/Baixo(100Lm)/ Médio(350Lm)/ Alto(800Lm)/ Turbo(1800Lm)/ Estroboscópico(1800Lm). A luz EDC suporta condições climáticas extremas.Pronto para Realizar: Nominal na resistência à água IP68, a luz EDC é capaz de suportar condições climáticas extremas. Se preocupa com o deslizamento da mão para nossa lanterna de mão é feita de liga de alumínio sólido; Não se preocupe em deslizar da mão facilmente com o deslizamento único para o nosso estilo único e aderência sólida. Especificações: 1. Emissor: LED SST40 2. Tensão de Trabalho de Trabalho: 2,7V - 4,2V 3. Opções da bateria da bateria de lítio: 1 X bateria de íon de lítio 18650 4. Dimensão: 101,5mm (comprimento) × 24,7mm (diâmetro da cabeça) 5. Peso: 55g (sem bateria) 6. Corpo da lanterna da lanterna de grau aeroespacial: liga de alumínio de grau aeroespacial 6061 graus 7. Carregamento USB Tipo-C 8. Memória do modo: memoriza o último nível de brilho usado nos modos gerais (exceto Lua, Turbo e Estroboscópio) 9. Tecnologia de temperatura avançada (ATR): ATR ajustará o nível de brilho automaticamente quando a temperatura do motorista avançada atinge a temperatura relativamente alta para evitar superaquecimento. 10. Proteção contra polaridade reversa: corta a energia enquanto a bateria inserida inversamente. LVP: enquanto liga, se a tensão da bateria for inferior a 2,7V, desliga automaticamente. HVP: enquanto liga, se a tensão da bateria for superior a 4,35V, desliga automaticamente. 11. O indicador de energia mostra o status de energia por 5 segundos após ligar o SC18. Verde O nível da bateria restante é bom A energia da bateria restante é ruim. Flashing Red = nível crítico da bateria, substitua ou recarregue sua lanterna o mais rápido possível. Mais detalhes de operação, sinta-se à vontade para verificar o manual Não hesite em conversar conosco e vamos lhe atender quaisquer problemas ou dúvidas, por favor fique a vontade para nos chat e vamos lhe atender oportuno! 💕Instruções de pré-uso: 1.Remova o papel de isolamento. 2. Por favor, aperte totalmente a cabeça e a tampa traseira da lanterna quando você usá-la.', 243.83, 127.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/cn-11134207-7ras8-m2gh43rru9a645', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F243233406%2F29017253435', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498547140', 'Colchão Ortoclass D28 – Casal (138x188x14)', 'O Colchão Ortoclass D28 é produzido em 100% espuma D28 Pró Aditivada de Alta Performance, oferecendo conforto e maciez na medida certa. Sua estrutura suporta até 80 quilos por pessoa, garantindo noites de sono agradáveis e relaxantes. O revestimento em Malha proporciona toque suave e aconchegante, enquanto a lateral em camurça marrom valoriza o design moderno e elegante do colchão. Além disso, conta com tratamento antialérgico e antiácaro, contribuindo para um descanso mais seguro e saudável. Com a reconhecida qualidade Ortoclass e acabamento diferenciado, o Colchão Ortoclass D28 é ideal para quem busca um colchão macio, durável e cheio de estilo. Invista no seu conforto e transforme suas noites em momentos de verdadeiro descanso.', 704.9, 620.31, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rasm-ma2wbrssjquh60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1537615778%2F22498547140', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992976854', 'Mesa Gamer Escrivaninha Cyber 136cm Tecno Mobili Preto e Vermelho Preto/Vermelho', 'Você que é gamer e procura uma Mesa para melhor conforto para sua horas de entretenimento, temos para você a Mesa Gamer Cyber. Ela é feita em MDP, com acabamento em finish foil, possui um nicho para o CPU, que ajuda na ventilação, proporciona o melhor para cada jogador, seu visual é diferenciado e inovador. Acomoda até 2 monitores. Estilo: Moderno Peso (kg): 23 Dobrável: Não Garantia: 03 Meses Altura (cm): 75 Acabamento: Finish Foil Largura (cm): 136 Possui Portas: Não Suporta Até (kg): 20 Modelo Infantil: Não Profundidade (cm): 60 Escala de Brilho: Fosco Ambiente Principal: Escritório Espessura do Tampo (mm): 15 Material Principal: MDP Necessita Montagem: Sim Possui Prateleiras: Sim Formato da Escrivaninha: Retangular Complexidade da Montagem: Baixa: pode ser montado por uma pessoa sozinha Possui Suporte para Teclado: Não Possui Acabamento na Parte de Trás: Sim Marca: Espresso Móveis Cor Interna: Preto Cor: Preto/Vermelho Cor do Produto: Preto/Vermelho Cor Predominante: Preto', 396.49, 396.49, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-8259k-mr36k9ompn9g57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F22992976854', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893093143', 'Diário de uma garota nada popular 4', 'Nikki faria de tudo para ajudar seu paquera gatíssimo Brandon, principalmente quando o assunto é filhotinhos adoráveis! Para impedir que um abrigo de animais feche, ela e suas amigas entram numa competição de patinação no gelo e precisam impedir que Mackenzie cause problemas. Depois de conquistar o público brasileiro, Nikki Maxwell compartilha novamente o quarto volume de seu Diário de uma garota nada popular. Nikki Maxwell não ficou totalmente surpresa ao descobrir que sua paixão, Brandon, trabalha como voluntário em um abrigo de animais, pois ele é tão doce que seria mesmo capaz de ajudar aqueles filhotinhos adoráveis!Mas Brandon diz a ela que o abrigo está correndo o risco de fechar, e Nikki sabe que não pode deixar isso acontecer - especialmente após descobrir um segredo chocante sobre Brandon. Então Nikki e suas amigas, Chloe e Zoey, entram numa competição de patinação no gelo para ajudar a levantar recursos para o abrigo.Mas Mackenzie, para variar, vai se intrometer e causar problemas no intuito de se passar por solucionadora de todos os problemas. E em Diário de uma garota nda popular 4, Nikki terá que pensar em ideias mais criativas desta vez para não deixar isso acontecer de jeito nenhum!Da série que já conquistou milhares de meninas (e meninos também!) Pelo Brasil, com milhões de exemplares vendidos, Diário de uma garota nada popular traz novas aventuras de Nikki e seus amigos para cativar e divertir o leitor ainda mais. Se aventure com essa vida escolar nada fácil e deixe o seu lado nada popular brilhar ainda mais!', 57.9, 57.9, NULL, 'Books & Magazines > Books > History & Cultures', 'https://cf.shopee.com.br/file/sg-11134201-7rd5c-lwlh8nax8zvce1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F22893093143', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16193333681', 'Óleo Ipiranga 10w40 Semissintético 4 Tempos 1 Litro', 'Óleo Ipiranga 10w40 Semissintético 1L Óleo lubrificante semissintético para motores 4 tempos de motocicletas a gasolina, etanol ou flex de última geração, inclusive as de alta cilindrada. Possui aditivos detergentes e antioxidantes especialmente desenvolvidos para evitar a formação de depósitos e borras. O IPIRANGA MOTO PERFORMANCE 10W40 SL foi elaborado para atender aos mais exigentes requisitos tecnológicos aplicados às motoclicletas, oferecendo benefícios exclusivos que atuam na proteção do motor, embreagem e transmissão, oferecendo conforto e praticidade na pilotagem nos mais diversos tipos de tráfego e terreno aos quais as motocicletas são submetidas diariamente. Possui desempenho superior em relação aos óleos de base mineral. Com exclusiva tecnologia Nano ARMOR™ capaz de criar uma armadura de proteção extra para desempenho otimizado e longa vida da sua motocicleta. As pequenas moléculas modificadas são adsorvidas quimicamente pelas partes metálicas, formando uma camada de interação a nível molecular, garantindo a devida proteção e cuidado que o seu veículo necessita. Conteúdo da Embalagem: 01 Frasco de 1 Litro de Óleo Ipiranga 10W40 Especificações: - Aplicação: Lubrificantes para Motor - Qualidade: Semissintetico - Tipo de motor: 4 Tempos - Viscosidade: 10W40 - Atende ou excede: SAE 10W40, API SL e JASO MA2.. (as mais exigentes classificações mundiais para motores a gasolina.) - Número de Registro ANP: 16711 Características: - MAIOR CONTROLE DE FRICÇÃO: O controle de fricção reduz significativamente o deslizamento da embreagem, proporcionando maior eficiência e suavidade nas trocas de marcha, garantindo melhor resposta de transferência de torque nas acelerações, oferecendo maior segurança nas retomadas. - MAIOR PROTEÇÃO NO MOMENTO DA PARTIDA: A rápida fluidez do óleo no momento da partida confere uma excelente lubrificação nos componentes mais críticos, reduzindo assim o desgaste inicial. - EXCELENTE RESISTÊNCIA AO CALOR E À OXIDAÇÃO: Sua formulação semissintética, aliada a um pacote efetivo de aditivos antioxidantes, oferece maior resistência à oxidação causada pelas altas temperaturas de funcionamento do motor, minimizando o espessamento do óleo e mantendo por mais tempo as características originais do lubrificante, mesmo sob o regime severo do anda e para encontrado no trânsito das grandes cidades. - ELEVADA PROTEÇÃO CONTRA O DESGASTE: A ação antidesgaste cria uma camada protetora ultrarresistente que reduz o metálico entre as peças, diminuindo o desgaste prematuro e prolongando a vida útil dos componentes do motor e da transmissão. - COMPATIBILIDADE COM SISTEMA DE CATALISADOR: Sua formulação balanceada possui um eficiente controle de metais prejudiciais ao sistema de catalisador, prolongando a vida útil deste importante componente do sistema de escape, garantindo eficiência no controle de emissões na atmosfera. - MANUTENÇÃO DA LIMPEZA INTERNA DO MOTOR: A exclusiva tecnologia detergente / dispersante oferece um controle eficiente contra a formação de depósitos e o acúmulo de borra, garantindo a limpeza e a eficiência do motor, mantendo as características próximas das originais de fábrica. Importante: - Recomendamos que a troca seja feita por um profissional de sua confiança! - Ao descartar o produto, tenha o devido cuidado com o meio ambiente. - Em caso de dúvidas, entre em contato através dos nossos canais de atendimento.', 69.9, 55.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1iiof3oxt5d15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F16193333681', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4963417657', 'Kit Relação Fazer 250 Abs Fz25 2018-2026 Com Retentor 46/15 Vaz', 'Kit Relação Com Retentor Vaz Black Edition Para a sua moto rodar tranquila e para você apreciar cada quilômetro, o Kit Relação Vaz oferece durabilidade e segurança. Disponível na versão black, o kit tem alta performance e maior resistência. Contém coroa e pinhão desenvolvidos em aço 1045 e corrente reforçada com retentor. Compatível com: YAMAHA FZ25 250 ABS 2018 FZ25 250 ABS 2019 FZ25 250 ABS 2020 FZ25 250 ABS 2021 FZ25 250 ABS 2022 FZ25 250 ABS 2023 FZ25 250 ABS 2024 FZ25 250 ABS 2025 FZ25 250 ABS 2026 Conteúdo da Embalagem: - 01 Coroa Temperada 46 Dentes - 01 Corrente com Retentor O.Ring Passo 428 x 136 Elos - 01 Pinhão 15 Dentes Especificações Técnicas do Kit: - Kit Transmissão Composto por Coroa, Corrente com Retentor e Pinhão - Peças com Medidas Originais - Código do Kit: Y04594X - Ideal para Reposição - Certificado pelo INMETRO Especificações Técnicas da Coroa: - Coroa Fabricada em Aço Temperado - Acabamento Powder Coat Black: Acabamento que Protege da Oxidação - Coroa Temperada com Dentes Menores que Resistem Melhor ao Atrito - Número de Dentes da Coroa: 46 dentes - Código da Peça: YA12.246TB Especificações Técnicas da Corrente: - Fabricada em Ligas de Aço com Tecnologia Antifadiga - Corrente com Tratamento em Cromo para Reduzir o Nível de Alongamento - Pré-Tensionadas e Lubrificadas a Vácuo - Modelo com Retentor O.Ring: Oferece Menor Atrito, Maior Durabilidade, Baixo Índice de Ruído e Menor Perda da Lubrificação Original de Fábrica - Passo da Corrente: 428 - Número de Elos: 136 - Código da Peça: 428HOR136 Especificações Técnicas do Pinhão: - Pinhão Fabricado a Partir de Aços Microligados à Base de Titânio e Nióbio - Possui Maior Resistência, Durabilidade e Desgaste Uniforme - Número de Dentes: 15 Dentes - Código da Peça: YB15.215 Importante: Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 349.9, 332.4, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh96k1rihbt18a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F4963417657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797483906', 'Cabeceira Extensível Florida com Painel Ripado e 2 Mesas de Cabeceira com 2 Gavetas Laranja Naturale', 'A linda cabeceira Florida extensível com painel ripado pode ajustar o seu tamanho de casal até a medida king, essa flexibilidade faz com que o produto seja flexível e continue sendo usado mesmo após uma troca de colchão. Peso (kg): 57 Garantia: 03 Meses Altura (cm): 128.5 Acabamento: Pintura UV Possui Pés: Não Largura Máxima: 279 Largura Mínima: 217.5 Profundidade (cm): 36.5 Escala de Brilho: Fosco Origem do Produto: Nacional Ambiente Principal: Quarto Material Principal: MDF/MDP Necessita Montagem: Sim Complexidade da Montagem: Alta: deve ser montado por um montador especializado Possui Mesa de Cabeceira: 2 Revestimento da Cabeceira: MDF Largura do Colchão Indicado: 138cm/158cm/198cm Material da Mesa de Cabeceira: MDF/MDP Acabamento da Mesa de Cabeceira: Pintura Escala de Brilho da Mesa de Cabeceira: Fosco Marca: Carmolar Cor Flex: Não Cor: Naturale Cor do Produto: Naturale Cor Predominante: Laranja Linha ou Coleção: Florida', 918.92, 918.92, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-824h8-mfiv9wxeyvwu7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F22797483906', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206344072', 'Bota Campesí Em Couro de Cano Curto Feminina CE573', 'Produto marca Campesí. A Bota Campesí é a escolha definitiva para quem não abre mão da durabilidade e do prestígio do couro legítimo. Com um design monocolor em tom terroso profundo, ela apresenta um acabamento impecável que une resistência e sofisticação. o grande diferencial visual fica por conta da fivela metalizada estrategicamente posicionada no cano, um detalhe elegante que eleva o status do calçado, transformando um item básico de inverno em uma peça de destaque no seu closet. Desenvolvida com foco no seu bem-estar, a bota possui um salto bloco baixo de 3 cm, que garante a estabilidade necessária para enfrentar a rotina sem cansar os pés. É o calçado ideal para o estilo de vida dinâmico da mulher moderna, transitando perfeitamente entre o ambiente de trabalho e momentos de lazer, pesando 0,773 kg. o investimento em um material nobre como o couro assegura que o produto mantenha sua aparência de novo por muito mais tempo, oferecendo o melhor custo-benefício para quem busca qualidade superior. Sinta a confiança de estar bem vestida em qualquer ocasião com um item que é sinônimo de conforto e praticidade. Seja para um passeio no shopping ou para um dia intenso de compromissos, a bota Campesí de cano curto se adapta ao seu pé, proporcionando um caminhar macio e seguro. Não perca a oportunidade de adquirir um clássico atemporal que combina com jeans, vestidos ou alfaiataria, garantindo um visual polido e autêntico todos os dias. Peso: 0,773 kg Altura da sola: 3,00 cm Altura do cano: 14,0 cm Circunferência do cano: 28,0 cm', 344.9, 344.9, NULL, 'Women Shoes > Boots > Fashion Boots', 'https://cf.shopee.com.br/file/sg-11134201-820ml-mnd0cf5wjaiwc3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F58206344072', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597592041', 'É meu! - Editora do Brasil', 'É dia do brinquedo na escola. Uma boneca-faz-tudo, um gato que mia e pula e um ursinho que repete tudo o que ouve... A cada semana Patrícia leva alguma coisa diferente, o que seria muito divertido se ela emprestasse e dividisse os brinquedos com os colegas. Mas isso logo muda. Com a ajuda do ursinho, ela percebe que ser egoísta não é nada divertido.', 44.55, 44.55, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd4w-lwqhehoed0db6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23597592041', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
