INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44807608858', 'Bebê Reborn Boneca Silicone 55cm Menina Olho AZUL Realista Brastoy', '👀🛒Clique em “Mais” para ver a descrição detalhada do produto! Boneca realista Certificado pelo INMETRO 💯 Material ecológico seguro, puro, muito macio, confortável, macio, real ao toque 🟣Características:Este bebê é 100% artesanal. Produto: Boneca Altura da boneca: aproximadamente 55cm Peso da boneca: aproximadamente 1.4kg Gênero:menina Material: 100% Silicone Cor dos olhos:azul Idade mínima recomendada: 3 anos Tipo: Bebê Reborn 💨💨💨 Cabeça: A simulação de cabeça real tamanho do bebê, muito bonito. Cabelo: Cabelo enraizado à mão, lavável e disponível; O cabelo pode ter qualquer forma, pode ser lavado. Olhos: Olhos em acrílico de qualidade superior, de cor azul, não podem fechar-se nem pestanejar. Material do Corpo: materiais de silicone completo, muito macio, muito confortável, 100% seguro, real ao toque. Roupas: o vestido será exatamente igual ao da foto. Você pode trocar as roupas dela por conta própria. O tamanho das roupas de bebê Premie é adequado para a boneca Ocasião: Dia das Crianças / Aniversários / Ano Novo / Presente de Natal. 🛒Lista de pacotes: 1X Boneca Reborn 1X Mamadeira 1X Chupeta magnética com cordão 1X Fralda 1X Certidão de Nascimento 1X Cordão para Chupeta 1X Boneca de Pelúcia 1X Conjunto de roupas (idêntica as fotos) 💡👉🏻Devido à influência da iluminação e da tela, a cor real do produto pode ser ligeiramente diferente da cor da imagem. A medição manual pode resultar em erros, portanto, fique atento. A realização de um pedido significa que você aceita essas diferenças', 699.0, 229.09, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/br-11134207-820lk-mm6xc52fffno8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F4