INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993470400', 'Copo Sky Corvinal - Harry Potter', 'Depois de um dia aprendendo feitiços incríveis, você precisa de um copo que te ajude a derrotar a sede? A gente te ajuda! Com uma tampa hermética e 500ml de capacidade, te acompanha em todas as aventuras! Com uma pegada confortável, não importa qual é a bebida, esse copo te acompanha até o último gole! O produto é importado, feito em aço inoxidável e plástico, com detalhes incríveis que vão fazer você se apaixonar! Se você é do time que prefere um café quentinho, esse copo é para você, com paredes duplas que ajudam a manter a sua bebida! E para completar o espetáculo, você conta com uma tampa por pressão e com abre e fecha em clique, que garante que não vaze nada! Não importa se você vai bailar nas festas, ir para o trabalho ou faculdade, esse copo te acompanha em todos os lugares até o último gole! Especificações: Altura: 18cm| Largura: 8,5cm| Comprimento: 8,5cm| Material: Aço Inoxidável e Plástico| Capacidade: 500ml| BPA Free Cuidados e recomendações de uso: Não preencha com líquidos até a superfície, deixe pelo menos 1,5cm de espaço para poder fechar o copo. Choques ou quedas podem trincar ou quebrar o produto. Não é a prova de pequenos vazamentos, carregue o produto apenas na posição vertical e não coloque em bolsas ou mochilas. Lavar com água, esponja macia e sabão neutro. Não recomendado colocar no freezer. Não vai ao micro-ondas. Não utilizar produtos químicos e abrasivos.', 84.9, 84.9, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-8258f-mqp40nuyjnk245', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F23993470400', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
