INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20999563975', 'Guarda-Sol Guarapari em Bagum e Haste de Madeira 1,80m Amarelo Bel', 'Proteção, estilo e durabilidade em um só produto! Descubra a linha exclusiva de guarda-sóis em Bagum da Bel, com cores vibrantes que se destacam em qualquer ambiente! Perfeitos para praias, piscinas, jardins e áreas externas, eles combinam sombra com elegância, além de oferecer alta resistência e durabilidade. ✔️ Haste em madeira: resistente e de alta durabilidade ✔️ Cobertura em Bagum reforçado: mais proteção e resistência contra sol e vento ✔️ Ventilação extra: maior estabilidade e conforto térmico ✔️ Proteção solar elevada: segurança garantida contra os raios UV ✔️ Design moderno e funcional: estilo e praticidade para qualquer ambiente ✔️ Varetas em Aço com Pintura Branca: Maior durabilidade, com acabamento que previne oxidação. Medidas: ✔️ Altura total: 2,00 metros ✔️ Envergadura: 1,80 metros Garanta o seu e aproveite o sol com mais conforto e proteção!', 250.26, 250.26, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Umbrellas', 'https://cf.shopee.com.br/file/sg-11134201-82582-mfsgf8ainwumbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757094384%2F20999563975', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21498723877', 'Bomba de Filtragem 1.136 L/H para Piscina 220V Bel', 'Bomba de Filtragem para Piscinas Bel - Essencial e Eficiente Água sempre cristalina e pronta para o mergulho! Desfrute de uma piscina livre de impurezas com a nossa Bomba de Filtragem de última geração, projetada para combinar eficiência e desempenho. ✔️ Consumo eficiente: Potência de apenas 20W. ✔️ Alta vazão: Sistema com capacidade de 1.136 L/H, garantindo água sempre limpa. ✔️ Versatilidade: Compatível com piscinas estruturais ou de borda inflável. Especificações:✔️ Corrente: 25 A ✔️ Frequência: 60 Hz ✔️ Grau de proteção: IPX7 ✔️ Classe de isolamento: Classe I ✔️ Medidas do filtro: 8,0 cm x 8,0 cm x 8,9 cm Mantenha sua piscina impecável com praticidade e desempenho superior. Adquira agora a Bomba de Filtragem Bel e aproveite momentos incríveis!', 259.1, 259.1, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Swimming & Diving', 'https://cf.shopee.com.br/file/sg-11134201-7rasw-maisiaa12n37cc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757094384%2F21498723877', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18158204509', 'L''Oréal Professionnel Serie Expert Pro Longer Máscara 250g', 'Máscara de Tratamento Pro Longer Serie Expert Feita Para Um Cabelo Mais Longo, Denso e com Brilho. Sua Tecnologia Exclusiva Foi Desenvolvida Para Preencher a Fibra Capilar Reforçando e Devolvendo a Densidade Aos Fios, Além De, Proporcionar Menos Pontas Duplas. * RESULTADO: Multifuncional * SUGESTÕES DE USO: 1. Aplique a máscara após a lavagem com o shampoo; 2. Distribua mecha por mecha; 3. Deixe agir de 3 a 5 minutos; 4. Finalize enxaguando abundantemente. * OBSERVAÇÕES: Imagem Meramente Ilustrativa * ITENS INCLUSOS: 1 L''Oréal Professionnel Serie Expert Pro Longer Máscara 250g', 248.9, 211.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-22100-58m1o884k7iv7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F18158204509', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21197806946', 'Kit Magic Beauty Hydra Hero - Shampoo 250ml e Condicionador 250ml', 'A linha Hydra Hero proporciona hidratação intensa e duradoura da raiz às pontas dos cabelos. Sua fórmula com ácido hialurônico, aloe vera e aminoácidos reequilibra os níveis de hidratação do cabelo e do couro cabeludo, blinda o fio contra a desidratação e repara a fibra, garantindo cabelos hidratados, saudáveis, macios e brilhantes. A Magic Beauty representa uma nova geração de tratamento capilar de alta performance que une inovação e responsabilidade em uma nova visão sobre beleza. Acreditamos no poder transformador da beleza livre e responsável e desejamos inspirar a nossa comunidade a celebrar a sua própria magia - assim como a das pessoas ao seu redor - ao ajudar a construir uma nova visão sobre a beleza pautada em empatia, amor-próprio e autenticidade. Somos todos feitos de magia. Isso é simplesmente extraordinário.', 131.9, 131.9, NULL, 'Beauty > Beauty Sets & Packages', 'https://cf.shopee.com.br/file/sg-11134201-7rdxs-lzi1v4ia1nzr3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F21197806946', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498435388', 'BOCA ROSA MÁSCARA PARA SOBRANCELHAS TRANSPARENTE 3G', 'A Máscara para Sobrancelhas Boca Rosa possui uma textura em gel de alto desempenho que combina formadores de filme que criam uma película elástica, translúcida e flexível, proporcionando uma alta resistência e performance em um único produto.', 59.9, 59.9, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-7repo-m8z4jlk85r5sf1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F22498435388', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697984382', 'Jogo De Formões Para Escultura Com 6 Peças Vonder', 'Jogo de formões para escultura, com 6 peças, VONDER. Lâminas com geometrias diferenciadas e resistentes, além de cabo de madeira envernizado, proporcionando maior durabilidade. Indicado para serviços de acabamento em carpintaria e marcenaria. Pode ser utilizado em esculturas de madeira e em trabalhos técnicos (escolas de arte). Espessura da lâmina do formão: 4,4 mm Material da lâmina: Aço carbono Material do cabo: Madeira Acabamento do cabo do formão: Envernizado Diâmetro do cabo do formão: 18 mm Massa aproximada (peso) (kg): 0,201 kg Quantidade de peças: 6 peças Conteúdo da Embalagem: 1 Jogo de formões para escultura, composto por: 1 formão com lâmina reta e ponta goivada de 6 mm de largura, 1 formão com lâmina reta e ponta reta de 10 mm de largura, 1 formão com lâmina reta e ponta ângular de 10 mm de largura, 1 formão com lâmina curvada e ponta em ''V'' de 6 mm de largura, 1 formão com lâmina curvada e ponta goivada de 9 mm de largura e 1 formão com lâmina curvada e ponta goivada de 10 mm de largura.', 84.47, 65.49, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m26v0aqf1ugh3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23697984382', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22891768763', 'Relógio De Pulso Masculino De Luxo À Prova D''água NAVIFORCE 8029 Quartzo Casual De Aço Inoxidável', 'Descrição do produto Movimento de movimento de alta qualidade: Movimento Seiko: Movimento Seiko, 100% novo de alta qualidade, economia de energia e durável. À prova d''água: 30m 98FT resistente à água diária, adequado para uso diário, lavagem à mão, dias chuvosos, respingos ou imersão curta, sem problemas. Não suporta banho e natação, não opere o relógio debaixo d''água, não opere o relógio debaixo d''água, (Obs: Por favor, não opere o botão na água) Material: Vidro mineral de alta dureza (chave resistente a riscos), caixa de liga de aço inoxidável, caixa de aço inoxidável para trás, resistente à pressão Ideias de Presente: relógios são para Natal, Aniversário, Dia dos Pais, Dia de Graduação e Dia dos Namorados ou como presente para negócios e festas. Atendimento a: Qualquer dúvida sobre o produto, entre em contato conosco, ofereceremos o melhor atendimento!Qualquer dúvida sobre o produto, entre em contato conosco, ofereceremos o melhor atendimento! ——————————————————————————————————————— Nome da marca: NAVIFORCE Modelo do modelo: NF8029 Características da Caixa: Impermeável Movimento do Quartzo Movimento: Movimento de Quartzo Estilo de luxo: casual moderno, esportivo, empresa, luxo Profundidade à prova d''água 3Bar (não suporta chuveiro e natação, não opere o relógio debaixo d''água); Forma da casca do escudo: redondo Características principais da principal características: 100% novo e de alta qualidade; Mostrador de design de luxo de alta qualidade com exibição de data; Material de proteção: liga de zinco Tipo de material de janela giratória: Hardlex Material da alça de alça: aço inoxidável Material da tampa inferior: aço inoxidável Tipo de fivela: Fivela Esp