INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098181639', 'TARÔ DO JARDIM DA BRUXA DESPERTE A MAGIA LATENTE QUE EXISTE EM VOCÊ COM ESTE ENCANTADOR BARALHO ESTILO WAITE SMITH', 'TARÔ DO JARDIM DA BRUXA DESPERTE A MAGIA LATENTE QUE EXISTE EM VOCÊ COM ESTE ENCANTADOR BARALHO ESTILO WAITE SMITH O Tarô do Jardim da Bruxa é um deck encantador e poderoso, projetado para aqueles que buscam mais do que simples previsões, mas uma experiência de conexão profunda com o mundo espiritual e natural. Baseado no sistema Waite Smith, este tarô autoral apresenta seres mágicos, criaturas mitológicas, lagos fantásticos e plantas encantadoras que povoam o jardim da bruxa. Composto por 78 cartas e seu livro complementar, a autora Sasha Graham ensina como interpretar as imagens e ajuda você a descobrir o que significam as cartas invertidas e a incorporar associações astrológicas a cada uma delas. Desperte a sua própria magia interior e encontre as respostas para todas as suas perguntas!. Informações Adicionais Autor: SASHA, GRAHAM Data Publicação: 06/03/2025 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: TARÔ DO JARDIM DA BRUXA DESPERTE A MAGIA LATENTE QUE EXISTE EM VOCÊ COM ESTE ENCANTADOR BARALHO ESTILO WAITE SMITH Idioma: INDEFINIDO Páginas: 320 Edição: 1 ISBN-13: 9788531523984 ISBN-10: 8531523982', 211.1, 146.71, NULL, 'Books & Magazines > Books > Horoscopes', 'https://cf.shopee.com.br/file/sg-11134201-7rbnc-m5vdzmmecm7o3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23098181639', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47407097417', 'Mangueira Ar Espiral 10m Rosca 1/4 NPT 1 Peça STELS', 'A mangueira ar espiral STELS de 10 m foi desenvolvida para facilitar o transporte de ar comprimido em oficinas e aplicações industriais leves. Com rosca 1/4 NPT, oferece conexão padrão para ferramentas pneumáticas, garantindo montagem rápida e segura. O formato espiral confere compactação quando não está em uso e alcance estendido durante a operação, reduzindo emaranhados e otimizando o espaço de trabalho. Produto indicado para quem busca praticidade e durabilidade em um componente essencial do sistema pneumático. Características: Modelo: 5700455 Referência: 5700455 Comprimento: 10 m Rosca: 1/4 NPT Tipo: Mangueira ar espiral Peças: 1 Marca: STELS EAN: 7899612786159 Benefícios: Extensão de 10 m para maior alcance sem comprometer mobilidade. Formato espiral que evita emaranhamento e facilita o armazenamento. Rosca 1/4 NPT compatível com ferramentas pneumáticas padrão. Leve e prática para uso em oficinas e serviços móveis. Instalação rápida, reduzindo tempo de montagem e manutenção. Conteúdo da embalagem: 1 Mangueira Ar Espiral 10m Rosca 1/4 NPT STELS (1 peça).', 48.51, 38.71, NULL, 'Home & Living > Tools & Home Improvement > Air Pumps, Parts & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-8262v-mlp1mmylihvm03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F47407097417', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
