INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598694440', 'JMJN Parafusadeira Furadeira Recarregável 12V OU 21V com 1 OU 2 Baterias + Carregador', 'Tenha praticidade e potência na palma da mão com a Parafusadeira Furadeira Recarregável 12V! Ideal para trabalhos domésticos e profissionais, ela é leve, ergonômica e muito eficiente para perfurar madeira, plástico e apertar parafusos com rapidez. 💡 Disponível em duas opções de kit: ✔️ Kit com 1 bateria 12V ✔️ Kit com 2 baterias 12V, para autonomia estendida sem interrupções! ✅ Características: Tensão: 12V Tipo: Furadeira/parafusadeira sem fio Bateria: Íon de lítio recarregável Mandril: 10mm (3/8") Velocidade variável e reversível 25 níveis de torque + modo perfuração Botão de avanço e reverso Design ergonômico com empunhadura confortável LED frontal para iluminação da área de trabalho ⚙️ Itens Inclusos no Kit: - 1 ou 2 Baterias 12V (de acordo com a variação escolhida) - 1 Carregador bivolt - 1 Parafusadeira 📦 Ideal para: Montagens de móveis Reparos rápidos Instalação de prateleiras Perfurações em madeira e plástico ⚠️ Escolha a variação desejada (1 ou 2 baterias) antes de finalizar a compra. 💥 Potência, mobilidade e eficiência reunidas em um só produto! Aproveite! TEMPO DE GARANTIA: 1 MÊS TIPO DE GARANTIA: GARANTIA DO FORNECEDOR Warranty Duration:1 Month Warranty Type:Supplier Warranty Quantity:1 Custom Product:No', 300.0, 115.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhu9o9yyr3ep45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1430000636%2F23598694440', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
