INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210311464', 'SPIDEY E SEUS AMIGOS ESPETACULARES – OS SUPER-HERÓIS REÚNEM FORÇAS!: MEU PRIMEIRO QUADRINHO!', 'Prepare suas teias! Aranha, Aranha-Fantasma, e Spin lançam teias super animadas enquanto derrotam os vilões — e se unem ao Pantera Negra, Hulk e à Ms. Marvel! As histórias de Meu primeiro quadrinho são escritas para crianças que estão começando a ler de forma independente. Essas histórias contêm diagramações fáceis de acompanhar, texto adequado para crianças e são uma ótima introdução ao mundo das histórias em quadrinhos. Esta é uma revista para leitores iniciantes, pensado para crianças.', 20.9, 20.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-820nu-mnyrla24mz9d1e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F58210311464', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
