INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598831762', 'Proteína Clean Pro Whey Zero Lactose Nutrify', 'O melhor da proteína zero lactose. 100% nutritiva.O CleanPro Whey é a nova opção de whey zero lactose da Nutrify, desenvolvido para quem busca uma suplementação proteica leve, sem lactose e livre de compostos artificiais. Com 22g de proteína por porção, é ideal para intolerantes à lactose, pessoas sensíveis ou quem evita o consumo do açúcar do leite no dia a dia. Possui alto teor proteico, que auxilia na manutenção e ganho de massa muscular, além da formação dos ossos. Disponível em dois sabores deliciosos! Experimente o sabor marcante do chocolate ou o sabor delicado da baunilha, combinados com a leveza dessa formulação pensada para otimizar sua rotina com praticidade, saúde e nutrição de qualidade.', 174.0, 156.6, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-7ra3f-mbct72lf1shi73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F548889079%2F22598831762', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259714282', 'Cotonetes Hastes Flexíveis', 'Cotonetes Hastes Flexíveis são ideais para a higiene pessoal de toda a família. Perfeitos para limpar delicadamente a parte externa da orelha (sem atingir o canal do ouvido), as dobrinhas do pescoço e pernas do bebê, além de serem recomendados para aplicar e remover maquiagem. Feitos com algodão 100% puro e hastes plásticas flexíveis, proporcionam maior suavidade, conforto e segurança para o seu dia a dia.', 8.49, 8.49, NULL, 'Health > Personal Care > Ear Care', 'https://cf.shopee.com.br/file/sg-11134201-8258x-mqnektutqcr3cb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554977%2F58259714282', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
