INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794753281', 'Kit 2 Copos Treinamento Infantil Magic Cup 230ml Neutro Nuk', 'Kit 2 Copos Antivazamento e Treinamento Infantil 360º Magic Cup Evolution 230ml Cada Neutro Nuk O Kit de Copos Magic Cup 360° da NUK foi desenvolvido para tornar a fase de transição do bebê para o uso do copo convencional mais prática, segura e divertida. Com design moderno e funcional, ele estimula a autonomia da criança enquanto acompanha seu desenvolvimento com conforto e eficiência. Pensado especialmente para ensinar o bebê a beber sozinho(a), o Magic Cup 360° auxilia em um dos marcos mais importantes da primeira infância: o uso independente do copo. Seu formato ergonômico facilita o manuseio pelas pequenas mãos, contribuindo para o desenvolvimento das habilidades motoras e oferecendo uma experiência semelhante à de um copo tradicional, porém com muito mais segurança e menos bagunça. O grande diferencial dos Copos Magic Cup está em seu sistema 360°, que permite beber de qualquer lado da borda, liberando o líquido apenas quando os lábios da criança entram em contato. Além disso, conta com tampa protetora e borda com estrutura antivazamento altamente eficiente, evitando derramamentos mesmo quando o copo é virado ou agitado — ideal para uso em casa, passeios ou para levar na mochila. Indicado para crianças a partir de 8 meses, o Magic Cup 360° é a escolha ideal para unir funcionalidade, aprendizado e praticidade no dia a dia das famílias. Principais Características: - Idade recomendada: A partir de 8 meses - Capacidade: 230ml - Modelo: Magic Cup 360° Evolution - Totalmente Livre de BPA - Borda 360º Antivazamentos - Tampa Protetora Higiênica - Frasco Ergonômico Antivazamento - Estimula a autonomia e o desenvolvimento das habilidades motoras. - Material Leve e Resistente - Fácil Higienização Especificações Técnicas - Conteúdo da Embalagem: Kit 2 Copos Magic Cup 360° Evolution - NUK - Composição/Material: Polipropileno - Garantia: 30 dias (contra defeito de fabricação pelo fabricante) - Referência do Fabricante: PA7659-1N - EAN: 7896098815250 - Marca: NUK Imagens meramente ilustrativas, as cores e estampas podem variar de acordo com o lote do fabricante.', 139.9, 134.99, NULL, 'Mom & Baby > Feeding Essentials > Utensils', 'https://cf.shopee.com.br/file/sg-11134201-81zua-mizzt56qtvr678', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F467697231%2F23794753281', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3563551191', 'AVENTURAS DE MIKE, AS - OUTRO PLANETA', 'Sabe aquele garoto popular da escola? Que é descolado se veste bem e faz sucesso com as garotas? Pois é, esse com certeza não é o Mike. Na verdade, o Mike é exatamente o contrário de tudo isso! Ele é desastrado, prefere videogames e salgadinhos no lugar de futebol, e é PÉSSIMO com as garotas. Ao lado do seu fiel amigo Nando (que é o ser humano mais distraído do planeta Terra) vão se aventurar em uma competição de biscoitos em busca de um misterioso prêmio que irá mudar suas vidas para sempre. “Este é o melhor livro de todos os tempos”. Mike “É impossível parar de ler”. Nando', 53.0, 53.0, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-824gc-mffk900s31u579', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F3563551191', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
