INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17129051424', 'Jogo De Velas de Ignicao Cronos 1.3 NGK ILMAR8C9D', 'IDEAL AUTO PECAS - Desde 1992 - IDEAL PARA SEU CARRO! Jogo De Velas De Ignicao - NGK APLICACAO: Fiat Cronos 1.3 8v de 2017 a 2021 DESCRICAO DO PRODUTO A vela de ignicao e o item responsavel pelo inicio da combustao no veiculo, ou seja, a queima da mistura de ar-combustivel presente na camara de combustao. Portanto, sem esse item presente no motor, o veiculo nao da partida ou vai a lugar algum.', 553.9, 553.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/b234e5e5421e3188bc53c5db2fd1f58f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616290090%2F17129051424', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
