INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12344197212', 'Creme Dental Colgate Total Whitening 180g', 'O creme dental Colgate Total Whitening enriquecido com flúor é perfeito para ajudar a remover manchas nos dentes e manter um sorriso saudável e radiante, graças à sua fórmula desenvolvida para um desempenho superior** com benefícios preventivos e duradouros*. Colgate Total Whitening é ideal para uso diário, é clinicamente comprovado, oferece 24 horas de ação contra bactérias* e ajuda a prevenir problemas bucais antes que apareçam: bactérias nas gengivas, erosão do esmalte, sensibilidade dentária, placa bacteriana, tártaro dental, manchas nos dentes, mau hálito e cárie dental. Inclui esta pasta dental com tecnologia poderosa, patenteada*** e preventiva que é segura para exibir um sorriso saudável. Complemente sua rotina com o uso de enxaguante bucal e fio dental e siga sempre as recomendações do seu dentista para obter uma boa saúde bucal. *Com escovação 2 vezes ao dia e uso contínuo por 4 semanas. **vs. Creme dental com flúor sem ingrediente antibacteriano. ***Patenteado nos Estados Unidos.', 31.19, 31.19, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7ra0v-m4t97zpzuyby46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F12344197212', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21475554805', 'Diga Sim! | Rick Renner', 'DIGA SIM! Experimente uma Vida Tão Plena e Prfunda Que Você Jamais Voltará Atrás Você já teve a sensação de ter ouvido a voz de Deus e ficou se questionando e dizendo que deveria ser sua imaginação, porque Deus certamente não escolheria algém como você? Você deixou o inimigo convencê-lo a abrir mão da sua missão porque ela parecia grande e gloriosa demais para uma pessoa "comum" como você? Você pode ter certeza de que Deus está falando ao seu coração hoje, chamando-o para fazer algo... Maior que seus talentos naturais... Maior que seus dons naturais... Maior que sua experiência passada. Título: Diga Sim! Subtitulo: Experimente uma Vida Tão Plena e Prfunda Que Você Jamais Voltará Atrás Autor: Rick Renner Páginas: 276 Formato: 23 x 16 x 2 cm Peso: 0.380 Kg ISBN: 9788566217568 Editora: Editora Rhema', 52.47, 52.47, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134201-23030-u4vhc0lnihovaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F21475554805', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
