INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593725319', 'Silicone Spray Finalizador Automotivo Perfumado Fragrâncias 400ml/230ml', '**ATENÇÃO: Selecione a fragrancia na variação** Conteúdo da embalagem: 01 Silicone Spray 400ML / 230g Silicone Spray Finalizador Automotivo Perfumado Fragrâncias 400ml/230ml **PRODUTOS Á PRONTA ENTREGA** Descrição Produto a base de polímeros de uso múltiplo e atuador exclusivo, que facilita a aplicação nas superfícies com economia e alto rendimento. Desenvolvido para utilização em automóveis, barcos e equipamentos industriais. Não mancha, conserva sem ressecar, possui secagem rápida e não fica pegajoso. Protege, renova e dá brilho em plásticos, borrachas, couro, madeiras, cerâmicas, vinil, componentes elétricos e eletrônicos. Adequado para lubrificação de superfícies metálicas e não metálicas. Faz deslizar suavemente trilhos de bancos e teto solar. Impede chiados e ruídos de catracas. Tem efeito antiestático, lubrifica e evita os efeitos da maresia. Disponível nas versões: Neutro, Lavanda, Carro Novo e Bambu. APLICAÇÃO: Utilizado em automóveis, barcos e equipamentos industriais, inclusive como desmoldante, em superfícies plásticas como painéis, para-choques, frisos, cabos elétricos, peças, dentre outros. Em caso de dúvidas, estamos à disposição! AutoStileMotors – Qualidade e confiança para o seu veículo.', 24.9, 21.99, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6frk2359lrb1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F954990910%2F22593725319', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
