INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19697881324', 'Perfume Masculino Vibez Deo Colônia HINODE 75ml', 'Vibez Deo Colônia Masculino Hinode Vai do seu jeito com esta fragrância amadeirada envolvente. As notas de saída de abacaxi, anis e cravo te ajudam a sentir o mix do frescor, frutal e picante logo de cara. Aos poucos vai percebendo o equilíbrio dos ingredientes florais e aromáticos que surgem com a evolução das notas de corpo. E para finalizar, as notas de fundo inspiradas de vetiver, baunilha e couro ficam na pele e te acompanham por mais tempo. Pra você expressar a sua personalidade. FAMÍLIA OLFATIVA: Amadeirado Envolvente NOTAS OLFATIVAS: Topo: Abacaxi, Anis, Cravo Corpo: Lavanda, Flor de Laranjeira, Pêssego Fundo: Vetiver, Âmbar, Couro', 139.9, 139.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-820m4-mqf0qd4yf400b8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F876865394%2F19697881324', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
