INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799855690', 'Kit 2 Lenço de Limpeza Nivea Demaquilante Ação Hidratante 3 em 1 25 Unidades', 'Lenço de Limpeza Nivea Demaquilante Ação Hidratante 3 em 1 O que é? NIVEA Lenços de Limpeza Ação Hidratante 3 em 1 são lenços de limpeza suaves e eficazes, ideais para remover maquiagem, inclusive máscara à prova d’água. Além de limpar profundamente, eles proporcionam uma sensação de pele hidratada. Para que serve? Os lenços removem até a maquiagem mais resistente e máscaras à prova d''água, deixando a pele limpa e hidratada. Enriquecidos com óleo de amêndoas que limpa suavemente o seu rosto, enquanto o Complexo Suave com Pró-Vitamina B5 e Hidramina protege a pele contra o ressecamento. Benefícios e diferenciais: - Remove maquiagem e máscara para cílios à prova d''água - Limpa a pele profundamente - Hidrata a pele - Dermatologicamente e oftalmologicamente testado - Remove os resíduos e impurezas da pele - Limpa a pele gentilmente* *Teste em uso durante 2 semanas. MODO DE USO Uso diário. Retire um lenço de limpeza do pacote e passe delicadamente no rosto, pescoço e colo. Ao passar na região dos olhos, tome cuidado para mantê-los fechados ao limpar. Não é necessário enxaguar. Após o uso, feche bem a embalagem com o rótulo adesivo para evitar que os lenços sequem. PREOCAUÇÕES Uso externo. Em caso de irritação, suspenda o uso e procure orientação médica. Manter em local seco e arejado, ao abrigo de luz e fora do alcance de crianças.', 46.98, 46.98, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/sg-11134201-823r3-mojpqeagzdot49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F21799855690', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
