INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41451138594', 'Bota Texana Menina E Bolsa Infantil Menina Blogueira Coturno Feminina Infantil Saltinho Cano Longo Country', 'Composto por uma bota infantil moderna e uma bolsinha super fofa, ideal para acompanhar as crianças em todas as ocasiões. Confeccionada em material sintético de alta qualidade, resistente e fácil de limpar. A bota infantil garante conforto durante todo o dia, com sola emborrachada antiderrapante oferece segurança extra para os passinhos das pequenas. A bolsa feita em material resistente e leve.Possui alça ajustável e espaço ideal para carregar acessórios ou brinquedos com praticidade. Características Da bota: Marca: Angipé Material Interno: Têxtil Material Externo: Sintético Fecho: Zíper Solado: Borracha Altura do Salto: 3cm Guia de Tamanhos: 28 - 19,00 29 - 19,30 30 - 20,00 31 - 21,00 32 - 21,50 33 - 22,00 34 - 22,50 35 - 23,50 Características da Bolsa: Material: Sintetico Fecho: De contato Dimensões: Altura 12cm x Largura 14cm x Profundidade 4cm', 159.9, 99.95, NULL, 'Baby & Kids Fashion > Girl Shoes > Boots', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9u638z51oua59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F287287585%2F41451138594', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3194319909', 'Livro - A planta de ferro - Capa comum - Principis', 'Ambientado em Londres, em 1930, tem como tema principal a ambição romântica de Gordon Comstock de desafiar a adoração do deus do dinheiro e do status. A Planta de Ferro referência à aspidistra não é tão agressivamente político quanto as obras mais famosas de Orwell. O romance está mais preocupado com as relações interpessoais, mas ainda aborda as questões maiores do capitalismo, do socialismo e a divisão de classes de forma sombriamente humorística. O olhar nada sentimental aos detalhes reveladores com seu humor seco e sereno, seu fascínio pelas loucuras e sua corajosa recusa em aceitar o conforto de respostas fáceis é o que faz com que o livro seja quase sempre engraçado, sem nuances de amargor. Editora: Principis Edição: 1, 2021 Autor: George Orwell Idioma: Português Páginas: 256 Dimensões: L 15.50 x A 22.60 x E 1.80 ISBN: 9786555523690', 29.9, 29.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/6ab90d9a2c031223887757c6c8af8169', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F3194319909', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23095887188', 'Livro O arquivo secreto de Sherlock Holmes', 'Quando você elimina tudo o que é impossível, então o que resta, por mais improvável que seja, só pode ser a verdade.O intrépido detetive e seu fiel companheiro Doutor Watson examinam e resolvem doze casos que intrigam clientes, confundem a polícia e proporcionam aos leitores muita emoção.São doze histórias de aventuras de Sherlock Holmes, e a maior diferença dos outros livros é que nem todos os contos são narrados pelo Doutor Watson, o que dá um sabor diferente à narrativa._x000D_ _x000D_ Editora: Principis_x000D_ Edição: 1, 2023_x000D_ Autor: Arthur Conan Doyle_x000D_ Idioma: Português_x000D_ Páginas: 256_x000D_ Dimensões: L 15.50 x A 22.60 x E 1.79_x000D_ ISBN: 9786555528305_x000D_ Coleção: Sherlock Holmes_x000D_ Linha Editorial: Principis - Clássicos da literatura_x000D_ Faixa Etária: + 12 anos_x000D_ Assuntos (tags): Detetive, Literatura estrangeira, Literatura Inglesa, Crime, Mistério, Aventura, Investigação , Suspense_x000D_ BISAC: Ficção / Ação & Aventura_x000D_ Linha de Produto: Principis_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação brilho_x000D_ Material: Papel', 34.9, 34.9, NULL, 'Books & Magazines > Books > Adult''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7qvfg-lhja65d6tmml77', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F23095887188', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998637619', 'Gloss Labial Mari Maria Makeup Lip Juice 5ml', 'Descrição: O Lip Juice é formulado com poderosos ativos, que proporcionam hidratação intensa e cuidados para os lábios. MODO DE USAR: Com o aplicador do próprio produto, aplique nos lábios do centro para as extremidades USO EXTERNO. MANTENHA FORA DO ALCANCE DAS CRIANÇAS. Conteúdo da embalagem: 5ml. Composição: O Lip Juice é formulado com poderosos ativos, como Vitamina E, D-Pantenol, Ácido Hialurônico, Manteiga de Karité. #Imagem ilustrativa. Cor do produto poderá variar dependendo da configuração do monitor ou celular.', 47.9, 32.99, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-823ov-moslw16vq4gc2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322432427%2F22998637619', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23797335855', 'Teclado Musical Digital Kobe KB-300 5/8 61 Teclas Sensíveis ao Toque com Pedal Sustain', 'Teclado Musical Digital Kobe KB-300 5/8 61 Teclas Sensíveis ao Toque com Pedal Sustain O Teclado musical KB-300 é uma excelente escolha para o público iniciante que busca um teclado com SENSIBILIDADE nas teclas e PEDAL SUSTAIN, recursos que são indispensáveis para o para os estudos e o desenvolvimento das técnicas e criatividade musical. A sensibilidade das teclas permite controlar com precisão a dinâmica do som das teclas, variando o volume, intensidade e velocidade das notas tocadas, isso proporciona um maior realismo nas canções. Além disso, o KB-300 possui uma grande variedade de timbres, incluindo piano, órgão, cordas, metais, sintetizadores. Também possui uma variedade de ritmos proporcionando uma gama de possibilidades musicais. Em resumo, o teclado musical KB-300 da Kobe Music é uma ótima opção para quem procura um instrumento de qualidade e versátil, sem dúvidas tudo que você precisa para iniciar seus estudos com o MELHOR custo-benefício do mercado. Confira todas as especificações técnicas mais abaixo: Especificações: Marca: KOBE MUSIC Cor: Preto Modelo: KB-300 61 Teclas 5/8 estilo piano com 2.2cm de largura Teclas com sensibilidade ao toque (resposta ao toque) Entrada para Pedal Sustain p2 (pedal incluso) 200 Timbres 200 Ritmos 80 Musicas Demo 48 Polifonias Display em LCD e painel de fácil acesso Possui 2 alto-falantes de 3W *Não possui memória FUNÇÕES: Sensitive (habilitar ou desabilitar sensibilidade nas teclas) Metrônomo, função aprendizagem (follow), transpose (manipular o tom dos timbres), Sustain (sustentação de notas), gravação e programação de acompanhamentos de percussão, função "Split" (Dual keyboard), que permitem dividir o teclado em duas partes com dois timbres diferentes. CONEXÕES: Entrada para Pedal Sustain p2. Entrada de áudio p2: Você pode conectar um dispositivo e reproduzir o som nos alto-falantes. Entrada para microfone p2: Você pode conectar um microfone para cantar e reproduzir o som nos alto-falantes do teclado. Saída para fone de ouvido: Ideal para fazer seus estudos sem incomodar ninguém, pois o som sairá apenas no fone de ouvido. Essa saída também serve para conectar o teclado em uma mesa de som, caixa de som, placa de gravação, entrada de som do seu computador, etc. Entrada USB: Você pode conectar um pendrive e reproduzir músicas ou acompanhamentos em MP3 enquanto toca ou simplesmente escutar suas músicas. Entrada MIDI: NÃO possui Acompanha: 01 - Fonte bivolt 5V 1A 01 - Pedal Sustain 01 - Suporte para partitura 01 - Adesivos para teclas 01 - Manual em português. Medidas: Peso 3.7kg Tamanho: 92 x 26 x 7.2 centímetros Alimentação: fonte bivolt 5V 1A, ou também funciona com 4 pilhas tamanho AA 1.5v. Garantia de fábrica: 6 meses', 639.0, 594.27, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Keyboards & Pianos', 'https://cf.shopee.com.br/file/sg-11134201-7rcc7-lrht85gjn63s5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F569545665%2F23797335855', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19199552913', 'Paleta de Blush creme e pó Catrice Blush Affair 020 Pleasing Pink', '✨ Paleta de Blush Catrice Blush Affair A Paleta de Blush Catrice Blush Affair combina dois tipos de blushes — um em creme e outro em pó — para criar looks versáteis e duradouros. Ambos são altamente pigmentados e podem ser usados individualmente ou em conjunto: aplique primeiro o blush cremoso e sele com o blush em pó para garantir um efeito de longa duração e acabamento impecável. 🎨 Dois Tipos de Blush Combinação de blush cremoso e em pó para maior versatilidade. 💗 Altamente Pigmentados Cores intensas que realçam as maçãs do rosto com facilidade. 🖌 Uso Individual ou Complementar Permite criar diferentes efeitos e garantir duração prolongada. ⏳ Look de Longa Duração Blush cremoso + pó proporciona acabamento duradouro e uniforme. ✔ Benefícios • Blush em creme e em pó na mesma paleta • Alta pigmentação • Versátil: uso individual ou combinado • Acabamento duradouro • Fácil de aplicar e esfumar 🌍 Sobre a Marca Desde 2004, a marca europeia Catrice está comprometida em oferecer produtos sofisticados com fórmulas e ingredientes de alta qualidade, sempre em harmonia com as pessoas, os animais e o meio ambiente. Own your magic ✨', 47.0, 47.0, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-7reqg-m2cg37m527pxf0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F878128394%2F19199552913', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
