INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393591191', 'KIT 3 Mantas Asfalticas Fita Vedatudo Autoadesiva Impermeabilizadora Aluminizada 30cm x 10m', 'KIT 3 Fita autoadesiva multiuso à base de asfalto modificado, auto protegida com filme de alumínio que permite sua exposição a intempéries e aos raios solares, sendo de fácil aplicação, na qual proporcionam medidas imediatas para solucionar problemas como infiltração, goteiras e telhas quebradas. Onde aplicar: Telhados; Rufos e chapas metálicas; Dutos de ventilação e ar condicionado; Sheds e cúpulas, Vedações de domos e claraboia; Reparos rápidos em baús, toldoe similares; Sistema de reflexão térmica. - Material da fita adesiva impermeável: Filme de alumínio e asfalto - Espessura aproximada:0,75 mm - Temperatura de trabalho da fita adesiva impermeável:- 5°C a 60°C - Temperatura de aplicação da fita adesiva impermeável:15°C a 50°C - Tamanho: 30cm X 10m Atuando há mais de 10 anos no mercado, a LB Materiais oferece tudo o que você precisa para realizar seu sonho de construção e reforma! Em caso de dúvidas, fale conosco deixando a sua pergunta, Estamos à disposição para melhor atendê-los. Boas compras, Equipe LB Materiais.', 281.9, 191.7, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3w7zx8w6ypk79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F705932885%2F22393591191', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698137949', 'Camiseta Unissex Branca Básica - Kidstok', 'Camiseta Unissex Branca Básica - Kidstok A camiseta lisa é leve, básica e versátil. Faz ótimas combinações para o dia a dia escolar dos pequenos! Características Gerais do Produto: • Composição Parte de Cima: 100% algodão • Cor: Branco • Gênero: Unissex • Manga: Manga Curta • Modelagem: Normal • Outros: Conforto garantido! Modelagem padrão. Consulte a tabela de medidas.', 25.0, 25.0, NULL, 'Baby & Kids Fashion > Boy Clothes > Tops', 'https://cf.shopee.com.br/file/br-11134201-820la-mqxtzieskflx21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F688191470%2F22698137949', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204732937', 'Camiseta Masculina Manga Longa Calvin Klein Jeans - Branco', 'A camiseta masculina Calvin Klein oferece um toque suave e um ajuste perfeito que envolve seu corpo de forma natural. Feita com materiais de alta qualidade, você sentirá o conforto excepcional assim que vesti-la. Seu design minimalista e contemporâneo transmite uma imagem de casualidade refinada, perfeita para um look descontraído e elegante. A peça possui modelagem básica, tecido meia malha, manga longa, gola ribana e estampa exclusiva da marca. Com estética minimalista e caimento impecável, traduz a essência da Calvin Klein. Ideal para compor produções modernas, do casual ao urbano sofisticado.', 239.0, 239.0, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/sg-11134201-825b1-mr2a24xey51j02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1593932205%2F58204732937', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
