INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21099834780', 'Mon Bijou Amaciante Regular + Perfume 1,7L', 'Fragrância: Clássico Modo de uso: Após a lavagem completa, adicione 1/2 copo americano (80ml) de Mon Bijou diretamente no reservatório ou diluído em água limpa e enxágue novamente. Conservação: Mantenha o produto em sua embalagem original. Com Mon Bijou +perfume e suas fragrâncias inspiradas na perfumaria fina, suas roupas ficarão perfumadas por muito mais tempo, até depois de secas. Sua fórmula sustentável com base vegetal tem mais cremosidade e fixação, proporcionando uma experiência única de perfumação e cuidado durante o uso, deixando suas roupas mais macias e fáceis de passar. Mon Bijou, Amaciante, Clássico, 1,7l. Mais perfumação;Mais fixação;Muito mais cremosidade;Fórmula sustentável.', 23.88, 18.9, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/sg-11134201-7rdve-mdeonzmwf8ic9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1506316714%2F21099834780', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
