INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203977406', 'Kit 10 Farinha Empanar Alfa Panko Flocada 1kg', 'A Farinha Panko é ideal para o preparo de pratos empanados orientais, como tempurá, camarão frito, hot roll e outros. Com farinha Panko, os pratos orientais fritos tornam-se mais crocantes, assemelhando-se à qualidade dos restaurantes orientais renomados. Características: Ingredientes: Farinha de trigo, Fermento e Sal. Informações Adicionais: “Contém Glúten”. Embalagem: Contém 10 pacotes de farinha Panko Alfa 1Kg. Origem: Brasil Fabricante: Alfa. Recomendações: Conservar em local seco e arejado.', 209.99, 209.99, NULL, 'Food & Beverages > Baking Needs > Flour', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjurmpwao3yef0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1732495279%2F58203977406', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17782712376', 'Fralda Pampers Confort Sec Super Tamanho P 72 Unidades', 'Experimente a NOVA Pampers confort sec com canais de ar! Que permitem que o ar circule livremente dentro da fralda, para o bumbum ficar menos abafado, e a pele arejada e sequinha durante a noite. Até 2X mais seco* e arejado * vs fraldas comuns. Canais de Ar: Permitem que o ar circule livremente dentro da fralda, para o bumbum ficar menos abafado, e a pele arejada e sequinha durante a noite. Gel Mágico que absorve e retém a umidade no interior da fralda para noites mais sequinhas Camada ultra absorvente:absorve rapidamente a umidade mantendo a pele do bebê sequinha. Barreiras Anti Vazamento: se adaptam suavemente ao redor das pernas do seu bebê. Ajuste cômodo e flexível para dar uma proteção anti vazamentos todas as noites. Loção hipoalergênica: ajuda a prevenir irritaçãoes.', 139.99, 128.16, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/fb09c5e8f130eca23edcecd7240912b7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F17782712376', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997684738', 'Caneca Pop Cruela – Disney', 'Você é uma vilã poderosa, mas peca na hora de se hidratar e precisa de uma mãozinha? A gente te ajuda! Com 350ml de capacidade, essa caneca é a parceira ideal para todas as suas aventuras! Não importa se é no mundo invertido ou não, essa caneca te acompanha em todos os lugares! O produto é produzido em território nacional, possui detalhes incríveis que vão fazer você se apaixonar! Feita em porcelana, com estampa em alta qualidade e 350ml é a companhia perfeita para deixar a hora do seu café muito mais divertida! Não importa se você é uma princesa hidratada ou não, essa caneca vai te ajudar a salvar o dia! Especificações: Altura: 9,5cm| Largura: 8cm| Comprimento: 8cm| Material: Porcelana| Capacidade: 350ml Cuidados e recomendações de uso: Lavar com água, esponja macia e detergente neutro. Não vai ao micro-ondas, nem a lava-louças. Não utilizar químicos e abrasivos. Choques ou quedas podem trincar ou quebrar o produto, pois trata-se de um produto de Porcelana', 54.9, 54.9, NULL, 'Home & Living > Dinnerware > Tea Pots & Sets', 'https://cf.shopee.com.br/file/sg-11134201-820mc-mnei2oqfb5kx49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F20997684738', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
