INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208792689', 'Alto Falante 6 Polegadas 140W Par Som Automotivo Porta Potente Alta Performance Leson', 'DANJASOM | Qualidade, confiança e envio rápido Par Alto-Falantes Automotivos Leson 6 Pol 140W Quadriaxial 4 Ohms O Par de Alto-Falantes Automotivos Leson 6 Polegadas foi desenvolvido para quem deseja melhorar o sistema de som original do veículo com mais definição, presença de médios e agudos e resposta equilibrada de graves, mantendo excelente custo-benefício. Modelo quadriaxial com tweeter piezo integrado, ideal para instalação em portas padrão 6 polegadas. ESPECIFICAÇÕES TÉCNICAS Potência RMS (cada unidade): 70 W Potência Máxima (par): 140 W Impedância Nominal: 4 Ohms Resposta de Frequência: 37 Hz a 20.000 Hz Sensibilidade: 87 dB Configuração: Quadriaxial Tipo de Tweeter: Piezo integrado Bobina: Simples CONSTRUÇÃO E MATERIAIS Diâmetro do Woofer: 6 Polegadas Cone: Polipropileno (PP) Borda: Emborrachada Estrutura: Carcaça resistente para aplicação automotiva Construção robusta voltada para durabilidade, resistência a vibração e estabilidade térmica no uso contínuo. DIMENSÕES Diâmetro Externo: 16,5 cm Profundidade de Encaixe: 6,5 cm Peso Total do Par: 0,870 kg APLICAÇÃO Instalação em portas compatíveis com padrão 6 polegadas Ideal para upgrade de sistema original (OEM) Pode ser utilizado com rádio original ou módulo amplificador DIFERENCIAIS Sistema quadriaxial com tweeter piezo integrado, ampliando a faixa de resposta sem necessidade de crossover externo Boa sensibilidade, garantindo desempenho satisfatório mesmo sem amplificação dedicada Cone em PP e borda emborrachada para maior durabilidade no ambiente automotivo Excelente custo-benefício para projetos de som interno Produto indicado para quem busca mais qualidade sonora no dia a dia, com instalação simples e desempenho equilibrado. DANJASOM ¬ Distribuidor oficial das maiores marcas ¬ Todos os produtos com NOTA FISCAL ¬ Envio rápido e seguro ¬ Garantia direto do fabricante Em caso de dúvidas, utilize o chat e converse conosco — nossa equipe está pronta pra ajudar você a montar seu projeto com segurança e performance.', 89.9, 69.89, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-820l9-mn0vf7y97kec1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F901722804%2F58208792689', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
