INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29288668960', 'Jogo Cartas Salsicha Familia Diversão Jovens Adultos Copag', 'Diversão garantida para toda a família com o Jogo de Cartas Salsicha Copag! Um jogo de cartas moderno onde os jogadores competem para montar o melhor cachorro salsicha, combinando as cartas certas para formar as partes do corpo do cachorro. O jogo envolve sorte, estratégia e interação entre os jogadores, com o objetivo de ser o primeiro a completar seu "Salsicha Perfeito". SOBRE O PRODUTO: - Jogo de cartas com 68 unidades. - Marca: Copag. - Tempo médio de partida: 30 minutos. - Estimula o raciocínio lógico e a interação social. - Regras simples e fáceis de aprender. - Embalagem compacta e resistente. - 1 a 5 jogadores. INDICADO PARA: - Idade a partir de 14 anos. - Jovens e adultos. MODO DE USO: - Abra a embalagem e distribua as cartas conforme as instruções. 1 - Escolha uma combina-cão para montar. 2 - Complete seu Salsicha com as melhores cartas. 3 - Faça mais pontos para vencer ou monte o Salsicha Perfeito e vença na hora! - Siga as regras do jogo presentes no manual. O Jogo de Cartas Salsicha Copag é perfeito para todas as ocasiões. Fácil de transportar, aprender e jogar, ele garante risadas e competição saudável em qualquer lugar. Transforme qualquer momento em pura diversão! Surgiu alguma dúvida? Entre em contato com a gente! Boas Compras :)', 164.98, 123.74, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-8259o-mqhzqpj131moe1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371678536%2F29288668960', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
