INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250167472', 'Kit Shampoo Automotivo Esfregação Neutro V-floc V-mol Vonixx', 'Kit Shampoo Automotivo Esfregação Neutro V-floc V-mol Vonixx - V-FLOC 500ML VONIXX DESCRIÇÃO: V-FLOC é um lava autos de alta performance e de pH neutro. Contém agentes condicionadores e tensoativos especiais que proporcionam uma lavagem suave e eficiente. Tem alto grau de lubrificação, promovendo redução significativa do coeficiente de atrito e um melhor deslize da luva de microfibra, reduzindo as chances de microrriscos na pintura. Além disso, promove brilho e aspecto de renovação. DILUIÇÃO: 1:20 – Uso na Snow Foam 1:400 – Lavagem comum com balde MODO DE USO: 1- Realizar a pré-lavagem do veículo para retirada do excesso de sujeira; 2- Diluir aproximadamente 10ml de V-FLOC em 4 litros de água; Ajustar a quantidade de produto de acordo com o nível de sujeira; 3- Iniciar a lavagem com o auxílio de Luva de Microfibra, começando pela parte superior do veículo; 4- Mergulhar a luva na solução e esfregar suavemente, até completar todo o veículo; 5- Enxaguar até a retirada de todo o produto; 6- Utilizar a Toalha de Secagem para finalizar. - V-MOL 500ML VONIXX DESCRIÇÃO: V-Mol é um lava autos biodegradável com pH levemente básico que não agride a superfície. Ideal para lavagem de automóveis, eficaz na remoção de sujeiras mais difíceis, como barro e óleo. MODO DE USO: 1- Diluir o produto na proporção indicada; 2- Iniciar a lavagem com o auxílio de uma luva de microfibra, começando pelas partes superiores do veículo; 3- Mergulhar a luva na solução e esfregar suavemente até completar o veículo; 4- Enxaguar até a retirada de todo o produto; 5- Secar o veículo por completo para evitar manchas.', 73.2, 54.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mggg3snmp7gl46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1618050749%2F58250167472', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
