INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19497687441', 'Rei da Ira (Reis do Pecado – Livro 1)', 'Primeiro volume da série Reis do Pecado, Rei da Ira é um romance sexy sobre casamento arranjado.Ela é a esposa que ele nunca quis… e a fraqueza que ele nunca pensou que teria.Implacável. Meticuloso. Arrogante.Dante Russo gosta de estar no controle, tanto na vida pessoal quanto na profissional.O CEO bilionário nunca cogitou se casar, até que uma chantagem o obriga a aceitar o noivado com uma mulher que mal conhece: Vivian Lau, herdeira de um império de joias e filha do seu mais recente inimigo.Ela é bonita e encantadora, mas Dante está disposto a fazer de tudo para destruir as evidências da chantagem e terminar o noivado.O único problema é que, depois de ter Vivian para si, ele não consegue mais pensar em perdê-la.Ele parece detestável... Mas ela não vai conseguir resistir à atração.Elegante. Ambiciosa. Educada.Vivian Lau é a filha perfeita, que pode levar sua família ao topo da alta sociedade. Casar-se com um Russo significa ganhar acesso a lugares inalcançáveis para novos-ricos.Embora Dante tenha um jeito rude e distante, Vivian concorda em se casar com ele por uma questão de dever familiar.Desejar seu toque não fazia parte dos planos. Assim como cometer o erro mais fatal de todos: Se apaixonar por seu futuro marido.', 58.41, 58.41, NULL, 'Books & Magazines > Books > Romance', 'https://cf.shopee.com.br/file/sg-11134201-7rd4j-lvv3xvrpxf8kff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F19497687441', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
