INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18199766650', 'Par Pneu Pirelli Corsa Pro 700x23c - Arame', 'O Pneu Pirelli Corsa Pro 700x23c - Arame é o companheiro perfeito para os seus treinos e competições. Este pneu versátil e resistente é o resultado da aplicação das tecnologias DualCompound e APS, que garantem uma performance excepcional em todas as condições. Este é o mais recente produto da linha de bicicletas Speed da Pirelli, uma marca reconhecida mundialmente pela qualidade e inovação dos seus produtos. A combinação perfeita entre a carcaça e o composto do pneu garante precisão e aderência, permitindo-lhe atingir a máxima performance em cada pedalada. O Pneu Pirelli Corsa Pro 700x23c - Arame pode suportar uma pressão máxima de 100psi, garantindo a sua durabilidade e resistência mesmo nas condições mais adversas. Com 120 TPI, este pneu oferece uma excelente resposta em todas as situações. Finalmente, a cor preta do pneu adiciona um toque de estilo e sofisticação à sua bicicleta, tornando-a não só funcional, mas também esteticamente agradável. Escolha o Pneu Pirelli Corsa Pro 700x23c - Arame e experimente a diferença que a qualidade Pirelli pode fazer na sua performance.', 119.9, 109.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rfh5-m9u5wtilhjrtab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F990966849%2F18199766650', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23396931270', 'Seringa para Lavagem Nasal Leão 10ml 1 Uni Fisher Price - HC396', 'Seringa para Lavagem Nasal Leão 10ml 1 Uni Fisher Price - HC396 Sabemos o quanto as crianças e bebês sofrem durante uma gripe ou resfriado por conta de nariz entupido, pensando nisso, a Fisher Price que sempre desenvolve seus produtos com amor e carinho oferece a vocês uma seringa em formato temático para que as limpezas nasais se tornem mais divertidas e sem medo. Em plástico livre de BPA; Bico em plástico flexível que encaixa perfeitamente nas narinas, sem causar desconforto; Encaixe circular para o dedo que proporciona maior conforto ao empurrar a seringa; Uso individual e recomendado para bebês e crianças; 10ml: quantidade exata para fazer a lavagem nasal; Ficha Técnica Marca: Fisher Price Modelo: Seringa para Lavagem Nasal Leão 10ml 1 Uni Fisher Price - HC396 Cor: Transparente Ideal para: Uso infantil Capacidade: 10ml Dimensões (LxAxC): 5 x 2.8 x 10cm Peso: 30.00g Conteúdo Da Embalagem: 1 Seringa nasal de 10ml Garantia: 3 meses Imagens meramente ilustrativas.', 22.69, 19.0, NULL, 'Mom & Baby > Baby Healthcare > Nasal Care', 'https://cf.shopee.com.br/file/sg-11134201-7rbm3-lly0d51kbk2i5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F750964153%2F23396931270', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
