INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51554672945', 'Roda Livre Paco 7V 14/28 Dentes Cubo Rosca Aço Dourada', 'A roda livre Paco de 7 velocidades é indicada para bicicletas que utilizam cubo com sistema de rosca, oferecendo trocas de marcha suaves e funcionamento confiável. Com construção em aço, garante boa durabilidade mesmo em uso frequente. Seu escalonamento de 14 a 28 dentes proporciona equilíbrio entre velocidade e força, sendo ideal tanto para uso urbano quanto recreativo. O conjunto conta com acabamento diferenciado, trazendo visual moderno para a bicicleta sem comprometer a performance. Projetada para quem busca um componente resistente e com ótimo custo-benefício, essa roda livre é compatível com transmissões de 7 marchas e fácil de instalar. Especificações Técnicas Marca: Paco Tipo: Roda livre (sistema de rosca) Velocidades: 7 marchas Relação: 14/28 dentes Compatibilidade: Cubos com rosca Material: Aço Acabamento: 6 catracas douradas e 1 catraca preta (última) Itens Inclusos • 1 Roda livre Paco 7 velocidades', 25.9, 22.69, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-8260a-mjh5dnvzhh5036', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F990966849%2F51554672945', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
