INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998162912', 'Kit 5 Sabonetes Líquido Acnederm Payot', 'Kit 5 Sabonetes Líquido Acnederm Payot, contém: 5 unidades de sabonetes Acnederm. O Sabonete Higienizante Acnederm Payot, foi formulado com Ácido Salicílico, Niacinamida e Óleo de Melaleuca, que conferem limpeza profunda eliminando as impurezas, sem irritar ou ressecar a pele. Controla a oleosidade excessiva, deixando a pele limpa e hidratada ao longo do dia. Desobstrui os poros. Diminui a vermelhidão e o inchaço causado pela acne. Seu uso contínuo ajuda na prevenção de formação de cravos e espinhas. Pele macia e com viço natural. Sensação refrescante. Sem Corantes e Parabenos. Não Comedogênico. Dermatologicamente Testado. Hipoalergênico. Vegano. Livre de ingredientes de origem animal e não testado em animais.', 244.5, 200.5, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rblr-m5k5w59bjpsob8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F619779318%2F22998162912', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
