INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208041162', 'Kit Selo D''água Cabeçote E Bloco Ap 8v Alumínio Billet - Unique 1', 'Produto novo e à pronta entrega! DURANTE O PROCESSO DE FABRICAÇÃO DO BLOCO DO MOTOR, É NECESSÁRIO ABRIR ALGUMAS CAVIDADES PARA USINAGEM. ESSAS CAVIDADES SÃO VEDADES COM O SELO D''ÁGUA, É UMA FORMA BARATA QUE AS MONTADORAS ENCONTRARAM DE EVITAR VAZAMENTOS POR ESTAS CAVIDADES. O KIT CONTÉM QUATRO SELOS, SENDO TRÊS PARA BLOCO E UM PARA DE CABEÇOTE. SELO PARA LATERAL BLOCO AP TEM DIÂMETRO EXTENO DE 36,60MM SELO FRONTAL PARA CABEÇOTE AP 8V TEM DIÂMETRO EXTERNO DE 24,30MM OS SELOS UNIQUE1 SÃO FABRICADOS A PARTIR DE UM TARUGO DE ALUMÍNIO 6061 T6 , USINADAS EM CNC E ACABAMENTO ANODZADO.. TEM MAIOR EFICIÊNCIA E DURABILIDADE QUE OS SELOS ORIGINAIS. PODEM SER USADOS NOS MOTORES: AP 8V DE 1985 A 2013, MD DE 1974 A 1989 - GOL, PARATI, PASSAT, SAVEIRO, SANTANA, VOYAGE, VERSALLES, LOGUS, ESCORT E ROYALE, PAMPA, BELINA, ETC... OU QUALQUER OUTRO BLOCO/CABEÇOTE QUE USE O SELO COM A MESMA MEDIDA. ANTES DE FINALIZAR A COMPRA TIRE TODAS SUAS DÚVIDAS NO CAMPO DE PERGUNTAS. PRODUTO DE ÓTIMA QUALIDADE Fotos reais do produto, não arrisque! Compre o produto original com a Mangoni Racing, Líder em venda no Mercado Livre Desde já, agradecemos sua visita. Queremos muito fazer parte das suas conquistas, portanto, compre conosco e torne-se um cliente especial. A Mangoni Racing segue no mercado há anos, com o objetivo de fornecer os melhores produtos da linha automotiva, quando se trata de alta performance. Além das vendas pela internet, possuímos uma nova e ampla loja física que encontra-se em Serafina Corrêa – RS. Faça sua compra, e venha nos fazer uma visita.', 94.9, 94.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-820lo-mmizew8l4gzr