INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8503117359', 'Criancas Geniais - Chiquinha Gonzaga', 'A coleção crianças geniais apresenta os primeiros anos de vários personagens que marcaram a nossa historia, mostrando que tudo pode ser bem parecido com as coisas que você vive no seu dia dia: família, irmãos, amigos, escola, brincadeiras e ate mesmo alguns probleminhas de percurso.aqui todos eles brincam, estudam, se relaciona-me, principalmente, sonham em transformar o mundo, de maneira diferente e para melhor. Em cada livro, viaje no tempo e inspire-se com tantas historias porque vai valer a pena: afinal, a sua historia ainda esta só começando.', 24.9, 24.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/61cf3190ac6d87438a39bc7e4ce9cfce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F8503117359', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
