INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208306638', 'Camiseta Tommy Hilfiger Original Masculina Chest Insert Logo Azul Marinho', 'Camiseta Tommy Hilfiger Masculina Chest Insert Logo Azul Marinho Estilo e Elegância em uma Camiseta de Marca Renomada. A Camiseta Tommy Hilfiger Masculina Chest Insert Logo Azul Marinho é a escolha perfeita para quem busca um visual autêntico e cheio de personalidade. Com sua cor azul marinho e o logotipo bordado "TOMMY HILFIGER", essa peça se destaca pela sua referência em estilo e elegância. Gola redonda com acabamento canelado para um ajuste confortável Estampa tipográfica com o logo bordado "TOMMY HILFIGER" no centro do peito, adicionando um toque único ao design. Confeccionada em 100% algodão, garantindo qualidade e durabilidade Mais sobre o Produto: A Camiseta Tommy Hilfiger Azul Marinho é versátil e pode ser combinada com jeans, bermudas ou até mesmo por baixo de jaquetas. Seu estilo atemporal permite diversas combinações, tornando-a uma peça indispensável no guarda-roupa masculino. Marca: Tommy Hilfiger Cor: Azul Marinho Confecção: 100% algodão Ref.: THMW0MW36498. Produto 100% Original', 299.99, 159.99, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/sg-11134201-81zur-mmqhb15n0rut4f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1760398124%2F58208306638', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
