INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492513389', 'Cera Tratamento Unha Top Beauty S.O.S Abencoada 6g', 'TOP BEAUTY SOS Unhas Hidratante para Cutícula Abençoada Cerinha promove nutrição e hidratação profunda. Previne manchas brancas e micoses. Cera hidratante para cutículas com óleo de cravo, queratina, óleo de ricino e lanolina vegetal. Antisséptico. Modo de uso: espalhar o TOP BEAUTY SOS Unhas Hidratante para Cutícula Abençoada Cerinha na região das unhas e cuticulas até a completa absorção. Usar diariamente, duas a três vezes ao dia.', 25.96, 25.96, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-7rbmx-lmnkjmyq2gggbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23492513389', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
