INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493580951', 'MOLDURA 2 DIN GM ONIX NOVO 21 A 23 10 POL EPX10GM015 EXPEX', 'Aplicação GM ONIX NOVO 2021 A 2023 A moldura Expex é feita para se encaixar perfeitamente no painel do seu carro. Os produtos Expex são produzidos com matérias primas de primeira qualidade, dando um ótimo acabamento. O seu carro nunca mais será o mesmo com este produto. Sua multimídia de 10 Polegadas irá funcionar perfeitamente com esta moldura específica para seu modelo de carro. Tamanho: 10 Polegadas Padrão: Chinês Cor: Prata e preto Produto Brasileiro ##CONTEÚDO## 1x Moldura para GM ONIX NOVO 2021 A 2023', 172.87, 159.05, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-7rfhb-m3nuknksii935f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F329035577%2F22493580951', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18599336604', 'Super Tweeter Jbl St200 100w Rms 8 Ohms Original', 'O Super Tweeter ST200 é a escolha perfeita para quem busca alta eficiência e baixa distorção na reprodução das altas frequências. Este super tweeter é versátil e pode ser usado em uma variedade de configurações, incluindo sistemas de PA, mini trios automotivos e sistemas de reforço de som. Sua construção robusta inclui uma base e um difusor de alumínio que ajudam a dissipar o calor da bobina móvel, enquanto o acabamento de usinagem diamantada proporciona durabilidade. Com um ângulo de dispersão de 40x40 (HxV) em sua corneta, este super tweeter é capaz de atingir longas distâncias, garantindo uma cobertura eficaz. O diafragma fenólico produz agudos com um timbre agradável e a bobina, construída em forma de kapton e enrolada com fio do tipo CCAW (copper clad aluminium wire), é resistente a altas temperaturas. Além disso, o conjunto magnético com anel de alumínio assegura uma reprodução de alta definição e eficiência em toda a faixa de reprodução, tornando o JBL ST200 uma escolha confiável para quem busca qualidade de áudio excepcional nas altas frequências. Fundada em 1946 por James Bullough Lansing (JBL) a JBL está entre as marcas mais respeitadas no mercado de eletrônicos. A companhia norte-americana virou referência em produtos de áudio pela sua qualidade, os produtos da empresa começaram a fazer sucesso junto a bandas e produtores musicais. A empresa encontrou espaço e se consolidou em um mercado que até então era dominado por produtos importados da China, sem personificação ou marcas conhecidas. Hoje, os produtos da JBL dispensam apresentação, pois os usuários sabem que eles representam qualidade absoluta em áudio. CARACTERÍSTICAS: Modelo: ST200 Dimensões da embalagem: 11.500 x 8.500 x 12.500 CM Dimensões: 61 x 115 x 124 mm Impedância: 8 Ohms Marca: JBL CAR AUDIO Potência: 100W RMS Resposta Frequência: 2.000 a 20.000 Hz Informação adicional: • Peso: 0,813 kg • Peso do ímã: 220 • Peso do conjunto magnético: 650 • Resposta de Frequência do Sistema: 2.000 a 20.000 Hz Incluso: • 1 Super tweeter ST 200 • Manual Técnico • Folheto Garantia EAN: 7896359510832', 142.77, 123.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-820ls-mlqd5edudm9w55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F329035577%2F18599336604', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
