INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27625922158', '[NEW] Mixsoon Bean Sun Serum SPF50+ PA++++, 50mL, 10mL', 'Mixsoon Bean Sun Serum SPF50+ PA++++ [Product Options] 1️⃣ 50ml 2️⃣ 10ml [Product Description] ☀️ Serum-type sunscreen that combines UV protection + skincare benefits in one step 💧 Lightweight watery texture spreads smoothly with no white cast or greasy finish 🍃 Infused with fermented soybean, barley, pomegranate, and pear extracts for hydration and nourishment ✨ Helps improve skin radiance while protecting against UVA & UVB (SPF50+ PA++++) 🧴 Leaves skin dewy, smooth, and comfortable for daily wear 📦 Net content: 50ml / 10ml [Key Features] ✅ SPF50+ PA++++ broad-spectrum UV protection ✅ Serum-like texture (lightweight, breathable, fast-absorbing) ✅ No white cast — suitable for all skin tones ✅ Hydration + brightening + wrinkle-care functional formula ✅ Low-irritation tested — suitable for sensitive skin ✅ Works well under makeup with smooth adherence [Key Ingredients] 🍃 Fermented Soybean Extract — hydration and skin barrier support 🌾 Fermented Barley / Pear / Pomegranate — antioxidant and nourishing care 💧 Hyaluronic Acid — moisture retention and plumping ✨ Niacinamide — brightening and tone improvement 🧬 Adenosine — wrinkle-care support [How to Use] 1️⃣ Apply at the last step of skincare 2️⃣ Take an appropriate amount and spread evenly 3️⃣ Apply 15–30 minutes before sun exposure 4️⃣ Reapply every 2–3 hours as needed [Safety / Store Notice] ⚠️ For external use only ⚠️ Avoid contact with eyes ⚠️ Stop use if irritation occurs 📌 Store away from direct sunlight and high temperatures', 158.3, 158.3, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134207-7rcer-m653edd9hwao03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F27625922158',