INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259437568', 'Salsicha Hot Dog Sadia', 'A Salsicha Hot Dog Sadia é perfeita para um preparo rápido e delicioso! *Modo de Preparo: Retire as salsichas da embalagem e coloque-as em uma panela com água fervente em quantidade suficiente para cobri-las. Deixe-as aquecer durante 3 minutos e sirva.* Ingredientes: Carne mecanicamente separada de ave (frango), água, carne de ave (frango), gordura suína, carne suína, proteína de soja, amido, sal, pele de ave (frango), cebola, aromatizantes: aromas naturais e aroma natural de fumaça, estabilizantes: trifosfato pentassódico e difosfato dissódico, corantes: carmim de cochonilha e extrato de urucum - base norbixina, antioxidante: isoascorbato de sódio, conservador: nitrito de sódio e estabilizante de cor: ácido fosfórico. Contém soja e pode conter lactose. Não contém glúten.', 18.99, 18.99, NULL, 'Food & Beverages > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zvq-miyqbadipam8da', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554829%2F58259437568', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
