INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56608895357', 'Martelo Unha 20mm Cabo Fibra Profissional Vonder', 'O Martelo Unha 20mm Cabo Fibra Profissional Vonder é uma ferramenta indicada para trabalhos de carpintaria, construção e reparos gerais. Com cabeça de 20 mm e cabo em fibra, oferece resistência e durabilidade para uso contínuo em aplicações profissionais e domésticas. Projetado para facilitar o manejo durante o uso diário, o martelo alia precisão na cravação com cabo que proporciona melhor controle e redução de vibrações. Ideal para quem busca um martelo de unha robusto e com acabamento voltado para o trabalho pesado. Características: Marca: Vonder Modelo: 3589020000 Diâmetro da cabeça: 20 mm Cabo: fibra Uso: profissional Benefícios: Desempenho consistente em cravações e remoção de pregos Cabo em fibra para maior controle e conforto Adequado para trabalhos de carpintaria e construção Construção resistente para uso frequente Conteúdo da embalagem: 1 Martelo Unha 20mm com cabo em fibra Vonder (modelo 3589020000)', 50.45, 37.12, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-81ztr-mn30jkd8hr7sc3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F56608895357', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
