INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58262202266', 'Aditivo Combustível Bardahl Proal 200ml Kit 5 Un.', 'BARDAHL PROAL 200ml — Kit 5 Frascos | Aditivo para Etanol APLICAÇÃO: Tanque de combustível de veículos movidos a etanol ou flex quando abastecidos com etanol. BENEFÍCIOS: • Confere características lubrificantes ao etanol • Protege o sistema contra corrosão • Limpa os bicos injetores, as válvulas, carburadores e outros componentes do sistema de alimentação • Reduz o consumo de combustível MODO DE USO: Adicionar 1 frasco (200ml) para até 60L de etanol, em todo abastecimento. Embalagem: Kit com 5 frascos de 200ml Marca: Bardahl (Promax) — Original e Certificado', 142.9, 142.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-823pm-mp42kjy4q1vl17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1819345424%2F58262202266', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
