INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993521333', 'Jogo De Pratos Para Sobremesa 21cm Kit 4pcs Cerâmica Paradiso Alleanza Tropical', 'Transforme a apresentação das suas sobremesas com o Kit de Pratos de Sobremesa Linha Paradiso da Alleanza. Com ilustrações vibrantes de folhagens e flores, além de uma arara em destaque, este conjunto traz um toque de natureza e elegância à sua mesa. Composição do Kit: 4 Pratos de Sobremesa de 21cm de diâmetro Características do Produto: Material Durável: Produzido em cerâmica feldspática branca, conhecida pela alta resistência, garantindo qualidade e longevidade. Decoração Tropical: Ilustrações detalhadas em um processo digital, com temas de folhagens e flores, perfeitas para quem busca sofisticação com um toque natural. Tamanho Ideal: Com 21cm de diâmetro, é ideal para servir sobremesas e pequenas porções de forma charmosa. Praticidade: Pode ser utilizado em micro-ondas e lava-louças, facilitando o uso no dia a dia. Cuidados Especiais: Produto não refratário, não indicado para uso em forno. Observações: Por se tratar de um produto artesanal e decorado digitalmente, podem ocorrer pequenas variações de tonalidade, cor e brilho, tornando cada peça única. Este kit é perfeito para quem deseja uma mesa tropical e sofisticada, acrescentando um toque vibrante e elegante em cada refeição.', 199.9, 199.9, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-7rep4-m2crsps9i1gq51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349137150%2F22993521333', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21498025046', 'Bicicleta Ergométrica Spinning 20kg De Roda De Inercia WCT Fitness', 'Bicicleta Ergométrica Spinning 20kg De Roda De Inercia WCT FitnessBicicleta Ergométrica Spinning WCT Fitness A Bicicleta Ergométrica Spinning WCT Fitness é uma excelente opção para quem busca saúde e diversão em casa. A prática de spinning oferece inúmeros benefícios, incluindo: Benefícios para a Saúde: Queima de calorias (até 700 calorias por hora) Melhoria da saúde cardíaca (redução da pressão arterial e colesterol) Tonificação de músculos (pernas, glúteos, abdômen e braços) Redução da celulite e estresse Aumento da produção de serotonina e dopamina Características: Roda de inércia: 20kg Peso total: 39kg Capacidade máxima do usuário: 120kg Altura recomendada: 1,50m - 1,95m Dimensões da Spinning: Comnto: 0,96m Largura: 0,53m Ajustes de Altura: Altura máxima do guidão: 1,05m Altura mínima do guidão: 0,94m Altura máxima do assento: 1,04m Altura mínima do assento: 0,86m Outras Características: Sistema de giro com fita resistente Pedais de ferro com encaixe para pés Rodas para transporte facilitado Garrafa de água inclusa Recursos Técnicos Avançados: Tipo de resistência: Mecânico Sistema de transmissão: Por correia Computador com funções: Calorias, distância, odômetro, pulso, tempo e velocidade Freio de segurança Ajustes de altura: Para assento e guidão Garantia: 3 meses contra defeito de fábrica Montagem: semi-montada com manual de instruções para fácil montagem.', 1699.9, 1699.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/sg-11134201-7rbl9-m5onhdqi1cw085', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F21498025046', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498042593', 'Poltrona Opalla Giratória Madeira Suede Verde', 'Poltrona Opalla Giratória Madeira Suede D Salla Verde Produzida artesanalmente e com estrutura em Madeira proveniente de Reflorestamento, esta poltrona possui durabilidade, resistência e um excelente acabamento. A Poltrona Opalla é Irreverente, elegante e muito confortável! A opção perfeita para transformar a decoração de seu lar ou escritório. Com o intuito de proporcionar maior comodidade e conforto a poltrona é confeccionada com o assento tipo Pillow em fibra siliconada. E para completar, sua estrutura é composta em madeira de reflorestamento seca e imunizada, é seguramente sustentado pelos pés em madeira; outra evidencia desse móvel são os pespontos com linha de Nylon que ressalta o visual moderno da Poltrona. Um verdadeiro Charme com conforto e sofisticação! Dimensões do Produto Montado: Altura: 81 cm Largura: 81 cm Profundidade: 72 cm Peso: 10 Kg Informações Adicionais: Material da estrutura: Madeira Enchimento do encosto e do assento: Fibra Siliconada Peso Suportado: 120 kg Tipo de Base: Giratória Madeira Tecido / Revestimento: Suede Quantidade de volumes: 1 volumes Produto desmontado (necessita de montagem): Sim Montagem: Não Oferecemos serviço de montagem Recomendações de limpeza e manutenção: Utilizar pano macio, seco ou ligeiramente umedecido com água. Atenção: Pode existir alguma diferença de tonalidade entre a foto e o produto, devido ao tratamento de imagens e à calibração de cores do monitor. Não oferecemos serviço de montagem, mas todos os nossos móveis possuem manual. Garantia: 90 Dias', 607.76, 607.76, NULL, 'Home & Living > Furniture > Sofas', 'https://cf.shopee.com.br/file/sg-11134201-7reop-m2csdrakz8gzce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F22498042593', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
