INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597785146', 'Helicóptero de Brinquedo com Sensor Recarregável Vermelho', 'Helicóptero com sensor: A magia do voo ao alcance de suas mãos. Decole para a diversão! Com esse Super Helicóptero as brincadeiras ao ar livre ficarão muito mais divertidas. Basta carregá-lo em uma entrada USB para ele sair voando. O sensor de gravidade funciona em superfícies planas ou colocando a mão embaixo do brinquedo. É leve e possui um ótimo acabamento. As crianças e os adultos vão adorar! Atenção: Não contém controle remoto. Especificações Ref.: SL386 Alimentação: Acompanha cabo USB Dimensões da embalagem (AXLXC): 14 x 22 x 4 cm Garantia do vendedor: 7 dias Garantia do fabricante: 3 meses Produto original, novo, lacrado e acompanhado de Nota Fiscal.', 46.99, 46.99, NULL, 'Hobbies & Collections > Toys & Games > Remote Control Toys & Accessories', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0a6lx6l3qsna4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1162387686%2F22597785146', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
