INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15663688701', 'Táxi e crônicas no diário nacional', 'Crônicas de Mario de Andrade livro de crônicas sobre a cidade de São Paulo no idos de 1927 a 1932.TÁXI E CRÔNICAS NO DIÁRIO NACIONAL - MÁRIO DE ANDRADE. Relata todos aspectos culturais e mídias dando a visão de jornal com a prosa própria de cronista e exímio analista que escreveu um grande clássico da nossa literatura Macunaíma.Leram , Arte em São Paulo, de 1927, táxi, em toda a sua vigência (1929-30), crônicas de 1931-32 e a série Folclore da Constituição. DESCRIÇÃO DO PRODUTO ISBN13: 9788531907395 Páginas: 480 Publicação: 1ª Edição – 2005 | Editora Garnier Encadernação: Brochura Formato: 14, 0 x 21,0 cm Autor: Mário de Andrade', 109.0, 20.0, NULL, 'Books & Magazines > Others', 'https://cf.shopee.com.br/file/0b8ec21835c2888dc906886cb37a3b9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F15663688701', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
