INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254283650', 'Eudora Niina Secrets Beauty Clips', 'Em edição limitada e ideais para prender o cabelo na hora da maquiagem, skincare ou em diversas ocasiões, os Beauty Clips Niina Secrets evitam que seus fios caiam em seu rosto durante suas atividades. Em um tom de cor-de-rosa cheio de charme e estilo, esses itens são super fáceis e práticos de usar, além disso: -Não marcam; -Não escorregam; -Podem ser usados em diversos tipos de cabelos. Nenhum produto Eudora é testado em animais. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 67.99, 67.99, NULL, 'Beauty > Hair Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-82617-mk2gkivv7r459d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58254283650', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253282242', 'Eudora Imensi Infinite Desodorante Colônia 100ml', 'Imensi Infinite é o desodorante colônia da perfumaria feminina de Eudora que te convida a viver uma experiência paradisíaca na Grécia, explorando esse destino que entrega paisagens exuberantes e horizontes infinitos. Esta fragrância feminina traz um contraste entre frutal brilhante e nuances florais solares da exclusiva Flor do Sol e, somada a ela, combinam-se a cremosidade e o calor das madeiras, com um toque de baunilha ao fundo. Família Olfativa: Floriental Floral. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 159.9, 159.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-825zw-mjhiiukfd7utce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58253282242', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16143293029', 'Travesseiro King Premium de Fibra conforto extra tipo Pluma de Ganso Ecológica 50x90 BF Colchões', 'Um travesseiro premium com o conforto das plumas de ganso e tamanho especial King. Com enchimento de fibras siliconadas com tecnologia ultra macia, a fibra chega a ser 10x mais fina que a tradicional, garantindo muito mais maciez, conforto e durabilidade. O travesseiro é não alérgico, inodoro e pode ser lavado. Acomoda-se perfeitamente ao corpo, assegurando encaixe suave, macio e confortável em qualquer posição. Bons sonhos! Características: Tecido 180 fios Fibra de poliéster siliconada ultra macia Não alérgico Lavável Ultra Macio Cor Branco Composição: Revestimento: Tecido Percal 180 fios - 50 Poliéster 50 Algodão Enchimento: Fibra de poliéster siliconada - 100 Poliéster Marca: BF Colchões Contém: 1 Travesseiro Tamanho King: 50 cm x 90 cm x 23cm', 246.87, 199.0, NULL, 'Home & Living > Bedding > Pillows', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m1e6aahfan3458', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412482669%2F16143293029', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19598967393', 'Colchão Queen Molas Ensacadas com Pillow Top Extra Conforto 158x198x33cm BF Colchões', 'Firmeza, conforto e imponência: conheça o Premium Sleep O Colchão Premium Sleep BF Colchões impressiona pela aparência, medidas generosas e alto nível de conforto, unindo suporte ortopédico e excelente custo beneficio. O pillow top alto acolhe as curvas do corpo enquanto as molas ensacadas trabalham para um descanso real e equilibrado. Feito para quem busca estabilidade, sua estrutura firme garante o alinhamento da coluna durante toda a noite, mesmo com movimentos, oferecendo resistência e durabilidade para noites mais tranquilas e dias sem dores. Por que escolher o Premium Sleep Toque que encanta Revestido em malha belga importada com acabamento matelasse, proporciona toque suave e sofisticado. Pillow Top Max Flowing Espuma D28 exclusiva que alivia pontos de pressão e oferece sensação acolhedora, com cortes 3D que aumentam a respirabilidade e o frescor. Molas que equilibram Molas ensacadas individualmente que absorvem o peso e garantem alinhamento ortopédico, com sustentação precisa para cada parte do corpo. Estrutura que reforça a firmeza Base com EPS premium que aumenta a estabilidade e durabilidade do colchão. Benefícios para o dia a dia: Alinhamento ortopédico que auxilia no alivio de pontos de pressão Proteção Hipoalergênico para um ambiente de sono mais seguro Fabricação própria com mais de 55 anos de experiência Qualidade certificada por INER, ABICOL, ISO 9001 e ISPA Sobre a BF Colchões: Industria brasileira com experiência desde 1968, com produção própria e controle de qualidade em todas as etapas, garantindo produtos com alto padrão de conforto e durabilidade. Características: Colchão Marca: BF Colchões Modelo: Premium Sleep Tamanho: Queen Tecido lateral: Suede Tipo de molas: Ensacadas individualmente Pillow top: Espuma Max Flowing D28 Nível de conforto: Intermediário a firme Suporte de peso: ate 140kg por pessoa Tecido superior: Malha belga bordada em matelasse Estrutura interna: EPS de alta qualidade Conteúdo da Embalagem: 01 Colchão Queen Molas Ensacadas com Pillow Top Extra Conforto 158x198x33cm BF Colchões Dimensões: Altura: 33 cm Largura: 158 cm Profundidade: 198 cm Garantia do Fabricante: 12 Meses Informações de Entrega: Entrega realizada ate o local de acesso permitido pela transportadora. Não realizamos entregas em locais com acesso por estrada de terra, areia, balsa ou barco. Não esta inclusa a subida por escadas ou elevadores', 4562.87, 2979.0, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/br-11134207-820m7-mmabaxuhzvnq85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412482669%2F19598967393', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
