INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57557590539', 'Kit 3 Blister Quadruplo Pokémon Evoluções Prismáticas Copag', 'Você está pronto para elevar sua coleção Pokémon a um novo nível? O Blister Quadruplo Jogo Pokémon Evoluções Prismáticas Copag é a escolha perfeita para os treinadores que querem adicionar cartas poderosas e estratégicas ao deck. Esse blister traz não só personagens icônicos, mas também benefícios para intensificar seu jogo! SOBRE O PRODUTO: - 3 Blister Quadruplo Jogo Pokémon Evoluções Prismáticas Copag. - Personagens: Vaporeon, Jolteon e Flareon. - Coleção: Escarlate e Violeta - Evoluções Prismáticas. - Formato das cartas:63mmx88mm. - Composição: Papel e Plástico. - Personagens: Vaporeon, Jolteon e Flareon. - 12 pacotes de Booster, sendo 6 unidades de cartas em cada blister. - 3 cartas promocionais Flareon, Jolteon ou Vaporeon. O Blister Quádruplo Jogo Pokémon Evoluções Prismáticas Copag é perfeito para quem busca emoção em cada booster e cartas que elevam sua jogabilidade! Garanta o seu agora e faça parte da evolução Pokémon! Surgiu alguma dúvida? Entre em contato com a gente! Boas Compras :)', 249.98, 244.98, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-82614-mm6ea4608zy9e8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371678536%2F57557590539', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19098540611', 'Vermífugo Drontal Puppy Suspensão 20ml para Cães Filhotes Elanco', 'PRODUTO ORIGINAL COM NOTA FISCAL! - - - - - DESCRIÇÃO: O Vermífugo Drontal Puppy é indicado para o tratamento e controle das verminoses intestinais e de giardíase em cães filhotes e adultos de raças miniatura, apresentando excelentes resultando contra parasitas cestoides (vermes chatos), nematódeos (vermes redondos) e protozoários. - - - - - MODO DE USO: Drontal Puppy deve ser administrado exclusivamente por via oral, com auxílio da seringa dosadora. O produto é muito bem tolerado, dispensando regime especial ou jejum prévio. Agite bem,antes de usar. - - - - - Enviamos o seu pedido o quanto antes possível! Obrigado pela preferência.', 133.0, 71.91, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdkn83x0vvzt35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442964228%2F19098540611', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799231092', 'Kit 3 Protetor Solar Rosto FPS60 40g Dermachem', 'PRODUTO ORIGINAL COM NOTA FISCAL! - - - - - APRESENTAÇÃO: Kit com 3 Unidades - - - - - DESCRIÇÃO: Protetor solar Facial FPS 60 Dermachem, foi formulado com a melhor tecnologia de ativos do mercado em termos de proteção solar contra radiação UVA e UVB, ação antioxidante, clareador e controlador da oleosidade. A Niacinamida auxilia no efeito clareador e controlador da oleosidade e a vitamina E atua na proteção da pele contra o envelhecimento precoce. Além desses ativos contém agentes formadores de filme e emolientes que ajudam na resistência à água e ao suor e que proporcionam toque seco com efeito sedoso e matte prolongado. - - - - - MODO DE USO: Aplique o produto abundantemente na face e colo pelo menos 15 a 20 minutos antes da exposição ao sol. Espalhe o produto até total absorção. Reaplicar sempre que necessário, ou após sudorese intensa e após lavar-se. Ideal reaplicar a cada 2 horas em exposição solar intensa. Uso diário. - - - - - Enviamos o seu pedido o quanto antes possível! Obrigado pela preferência.', 119.8, 63.13, NULL, 'Beauty > Beauty Sets & Packages', 'https://cf.shopee.com.br/file/br-11134207-820m1-mopseogvva4m64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442964228%2F20799231092', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42672796499', 'Kit 2 Protetor Solar Nutriex Fps 30 Toque Seco 120ml Oil Free Hipoalergênico', 'Kit 2 Protetor Solar Nutriex 30FPS 120ML O Protetor Solar Nutriex FPS 30 foi desenvolvido com a exclusiva tecnologia Bioactive E®, que alia nutrição e proteção avançada para a pele. Sua fórmula com Vitamina E ajuda a prevenir o envelhecimento precoce, protegendo contra os danos causados pelos raios UVA e UVB, além de oferecer resistência superior à água e ao suor. Com toque seco, rápida absorção e fragrância suave, o protetor não deixa a pele esbranquiçada, proporciona sensação agradável e é indicado para uso diário em todos os tipos de pele. Dermatologicamente testado, não provoca acne e é ideal tanto para atividades ao ar livre quanto para uso cotidiano. Benefícios: * FPS 30 proteção eficaz contra os raios solares * Bioactive E® + Vitamina E ação antioxidante que combate o envelhecimento precoce * Hipoalergênico e dermatologicamente testado * Oil Free não oleoso, não obstrui os poros * Toque seco e rápida absorção * Fragrância suave e aplicação fácil * Não deixa a pele esbranquiçada * Muito resistente à água e ao suor * Proteção equilibrada: UVA superior a 1/3 de UVB * Indicado para uso diário Modo de Aplicar: Aplique uma camada generosa do protetor solar sobre a pele antes da exposição ao sol. Reaplique sempre que necessário, especialmente após suar intensamente, nadar, se secar com toalha ou durante períodos prolongados de exposição. Para crianças menores de 6 meses, consulte um médico antes do uso. Nuvem de tags: Protetor Solar, Nutriex, Fps 30, Bioactive E, Vitamina E, Toque Seco, Uso Diário, Hipoalergênico, Oil Free, Resistente Água, Resistente Suor, Proteção Uva, Proteção Uvb, Pele Saudável, Anti Envelhecimento, Rápida Absorção, Não Oleoso, Não Provoca Acne.', 49.9, 37.9, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-824j8-mfeex57mv2fj37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944577712%2F42672796499', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
