INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49012843154', 'Bituqueira Coletor De Bitucas Cinzeiro de Chão com Tampa alto Cor Preto jardim praças parques ambientes aberto', 'Mantenha seus espaços sempre limpos e organizados com a nossa bituqueira de chão em alumínio preto. Desenvolvida para coletar com eficiência, ela é a solução ideal para empresas, condomínios, bares, restaurantes, portarias e áreas externas destinadas a fumantes. Fabricada 100% em alumínio, ela não enferruja e possui pintura eletrostática de alta durabilidade, garantindo resistência ao uso contínuo e às variações climáticas. Leve e prática, pode ser lavada com água e sabão, facilitando a limpeza e a manutenção diária do ambiente. Com seu design moderno, combina funcionalidade e estética para manter seus espaços livres de resíduos e com uma apresentação impecável. Ambientes para colocar: - Portarias e entradas de empresas. - Condomínios residenciais e comerciais. - Estacionamentos e áreas externas. - Áreas de fumantes em bares, restaurantes e eventos. - Hospitais, universidades e estabelecimentos públicos. Diferente dos concorrentes a nossa bituqueira: - Alta capacidade de armazenamento. - Leve, resistente e fácil de limpar. - Pintura eletrostática: maior durabilidade e acabamento superior. - Material 100% alumínio: não enferruja, ideal para áreas externas. - Design discreto e moderno que se adapta a diversos ambientes. Especificações Técnicas: Cor: Preto. Capacidade: Grande Capacidade de Armazenamento. Ferrugem: Não Enferruja. Limpeza: Pode lavar com água. Material: 100% Alumínio. Medidas da Bituqueira: Altura: 90 cm / Diâmetro Base: 25 cm. Peso: 840 Gr.', 408.0, 299.0, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/br-11134207-820lv-mpwm7o1nvtvn38', 'https://shope.ee/an_redir?origin_link=https%3A%