INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260222543', 'Melhor Kit 3 Aditivo Combustivel Gasolina 250ml limpeza de bicos e sistema via tanque BraClean', 'Kit com 3 frascos de Aditivo Gasolina 250ml. Uso via tanque para auxiliar na remoção de resíduos em bicos, válvulas e câmara de combustão, contribuindo para funcionamento regular. Instruções de uso 1- Com o tanque baixo, adicione um frasco. 2- Abasteça em seguida para mistura uniforme. 3- Conduza normalmente. 4- Repita conforme periodicidade do rótulo. 5- Não combine com outros aditivos. Cada frasco de 250ml trata até 50 litros. Reconhecimento de Wilson Fittipaldi Jr, presença técnica em Porsche Cup Brasil e desenvolvimento alinhado a requisitos usuais de equipamento de fábrica.', 65.8, 65.8, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134275-820ll-mnx09u07yebk59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F731959256%2F58260222543', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
