INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594345207', 'Chapinha Profissional Taiff Titanium Progress Visor Digital 250°C Cabo 3m Bivolt Prancha Alisadora', 'Chapinha Taiff Titanium Progress — Titanium, Visor Digital, 250°C, Bivolt Chapinha de alto desempenho com perfil de titanium, visor digital de temperatura e cabo giratório de 3 metros. Para quem precisa de controle preciso e resultado profissional. TECNOLOGIA Perfil de titanium — deslizamento mais suave que cerâmica comum, menor resistência mecânica sobre os fios Aquecimento PTC — temperatura uniforme e estável ao longo de toda a placa, sem variação brusca Aquecimento instantâneo — atinge a temperatura configurada em segundos, sem tempo de espera relevante Visor digital — exibição da temperatura em tempo real, controle preciso do nível de calor por tipo de cabelo DESEMPENHO Temperatura máxima: 250°C Cabo giratório: 3 metros — amplitude total de movimento sem travamento Voltagem: Bivolt automático (110V / 220V) ESPECIFICAÇÕES TÉCNICAS Marca: Taiff | Modelo: Titanium Progress Cor: Preta Dimensões: 3,5 x 3,2 x 28,7 cm Dimensões embaladas: 4,6 x 15,1 x 32,3 cm GARANTIA 6 meses — garantia oferecida pelo fabricante Taiff Marca: Taiff | Voltagem: Bivolt', 502.66, 459.9, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-824ik-mpmcstvkkpvxde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F23594345207', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198387768', 'Kit Faixa Lateral + Adesivo Track Gol Voyage G6 2013/2016', 'Adesivo Genérico. As Faixas Decorativas Adesivas além de determinar, em muitos casos, o modelo do veículo, também personalizam o seu carro e protegem a pintura. As Faixas Automotivas Decorativas são produzidas em vinil automotivo autocolante importado, dispensando a utilização de produtos para a fixação e já possuem verniz automotivo. Dessa forma, as faixas estão protegidas da ação do tempo (Exposição ao sol e a chuva). Kit Faixas Laterais Preto + Adesivo Traseiro Track Gol e Voyage G6 2013, 2014, 2015 e 2016 Características:1 Jogo de Faixas Laterais Track / Fabricado em Vinil Transparente / Dimensões: 163,2 x 12,3 cm2 Adesivos Traseiro Track / Fabricado em Vinil Transparente / Dimensões: 13,1 x 1,5 cm Características Dos Adesivos: Modelo Original.Quantidade: 1 Kit Completo.O adesivo já possui uma camada de verniz automotivo com proteção UV, elevando a qualidade do impresso e conferindo maior durabilidade.Observações:Material autocolante.Resistente à chuva e raios UV.Embalagem segura para o transporte.Vinil importado.Instruções Para Aplicação:1 - Limpe e remova qualquer impureza na área de aplicação do produto.2 - Limpe as mãos e remova o protetor do liner. Procure ter o mínimo de contato com a face adesiva.3 - Centralize o produto no local da aplicação. Após esse posicionamento,pressione o produto gradativamente, sempre do centro para as bordas.Procure retirar todas as bolhas.4 - Após finalizar a instalação, não tente retirar a peça para reposicioná-la,pois isso danificará o produto.OBS: Para limpeza e conservação do produto, utilize apenas água e sabão neutro e/ou automotivo.Recomendamos que a aplicação seja feita por um profissional. Garantia de 1 ano.', 50.12, 45.6, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-7reqa-m80sr53j2y6p70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1466989517%2F22198387768', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
