INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294446586', 'Pincel Silicone e Bamboo', 'O Pincel Silicone e Bamboo é perfeito para espalhar de maneira uniforme ovos, molhos, manteiga ou o que mais você desejar sobre massas delicadas ou outras preparações. Prático para utilizar e lavar, pode ser levado à máquina de lavar louças e ainda resiste ao calor de 240°C sem deformar. A alça em bamboo possui um orifício para ser pendurada, ficando à mostra para facilitar seu dia a dia. Peça já o seu Pincel Silicone e Bamboo Mor e complete sua coleção.', 19.0, 19.0, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-824ge-mfbbjr3fsdu56e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F23294446586', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
