INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23596314456', 'Shiseido Clear protetora solar SPF 50+, 20g', 'Protetor solar claro FPS 50+ #1 Vara de proteção solar nos EUA* Protetor solar ativo em movimento. O protetor solar claro da Shiseido''s Clear Sunscreen FPS 50+ agora inclui o SynchroShield™ Tecnologia de tecnologia. Nossa inovadora tecnologia WetForce x HeatForce cria um véu de proteção invisível e leve que se torna mais eficaz em água e calor*. Oferece proteção superior que passa transparente e absorve rapidamente sem qualquer resíduo para uso confortável. Esta fórmula oferece proteção UV invisível para rosto e corpo. Deslize o bastão claro sob ou sobre a maquiagem para facilitar a cobertura portátil em dias ativos e externos. Detalhes da Fórmula: Livre de oxibenzona e octinoxato. Para todos os tipos de pele. Testado por dermatologista. Testado pelo oftalmologista. Não comedogênico. Resistente a água resistente a 80 minutos Após a aplicação, faça 4 horas após a aplicação: A mulher respondeu a sua pele e se manteve hidratada. O produto respondeu a suor e a água do que outros protetores solares 90% das mulheres responderam ao produto foi mais resistente ao suor e água do que outros protetores solares usados antes. A tecnologia HeatForce é ativada em dias quentes, após a aplicação da fórmula * A tecnologia HeatForce é ativada em dias quentes, após a aplicação da fórmula na pele. Ativar a tecnologia WetForce, expor a área aplicada à água ou transpiração por 30 minutos. Fonte: Circana/EUA Prestige Beauty Departamento Total/Especialidade, Rosto Em Sol Vendas Produto, 0,7 oz tamanho, Baseado em Forma/Textura de Skincare, Anual 2022', 179.86, 179.86, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134207-7rd5q-lu8vg8qnfzv6e0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F23596314456', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22634415925', 'innisfree Jeju Cherry Blossom Tone Up Creme De Tom De Cerejeira, 50ml', 'Descrição do produto em inglês após português Recurso Um creme enriquecido com flor de cerejeira Jeju Flor de cerejeira Jeju torna A pele pura, brilhante e vitalizada. A betaína natural extraída da beterraba de açúcar evita que a umidade da pele evapração, mantendo a pele totalmente hidratada e flexível. O efeito de tom natural corrige a tez pura e brilhante. -Volume 50ml -Como Usar Aplique uma quantidade adequada na última etapa do cuidado com a pele. Espalhe sobre o rosto e pescoço e deixe absorver. Depois de usar o creme de tonificação de flor de cerejeira Jeju (resultados de pesquisa de satisfação de satisfação do cliente) "Eu Sinto um efeito de tom imediato." "Eu Sinto que meu rosto nu tem naturalmente iluminado." "Eu Sinto que minha pele está viva." Minha pele fica úmida e brilhante." ************************************************** -Feature A cream enriched with Jeju cherry blossom Jeju cherry blossom makes the skin pure, bright, and vitalized. The natural betaine extracted from sugar beet prevents the moisture of the skin from evapration, keeping the skin fully hydarated and supple. It''s natural tone up effect corrects the complexion pure and bright. -Volume 50ml -How To Use Apply a suitable amount at the last step of skincare. Spread over face and neck and let it absorb. - After using Jeju Cherry Blossom Tone Up Cream (Customer Satisfaction Survey Results) "I feel an immediate tone-up effect." "I feel like my bare face has naturally brightened." "I feel like my skin is alive." "My skin feels moist and bright."', 86.07, 86.07, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134207-7r98o-lkrj9rwg4xgmdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F22634415925', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
