INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593957220', 'Compresso 3/4HP R290 Tecumseh AE2430U-ES3C AE1653BR - 220V', 'Compresso 3/4HP R290 Tecumseh AE2430U-ES3C AE1653BR - 220V O Compressor Tecumseh 3/4HP R290 AE2430U-ES3C AE1653BR 220V é uma excelente escolha para quem busca eficiência e sustentabilidade em sistemas de refrigeração. Compatível com o gás R290, um refrigerante ecológico, esse modelo oferece uma operação de baixo impacto ambiental e alta performance. Sua potência de 3/4HP garante excelente capacidade de resfriamento, sendo ideal para câmaras frigoríficas, expositores refrigerados e outros sistemas de climatização. Desenvolvido com tecnologia de ponta, o compressor Tecumseh AE2430U-ES3C se destaca pela eficiência energética, proporcionando baixo consumo de energia e operação silenciosa. Seu design robusto e confiável garante uma longa vida útil, reduzindo a necessidade de manutenção e proporcionando estabilidade no resfriamento. Além disso, a compatibilidade com o R290 torna esse modelo uma opção moderna e sustentável para quem deseja reduzir a pegada de carbono de seus sistemas de refrigeração. Com sua construção eficiente, o Compressor Tecumseh 3/4HP R290 é ideal para quem procura qualidade e desempenho em equipamentos de refrigeração. Sua durabilidade, associada a baixo consumo de energia, torna-o uma excelente opção para quem deseja otimizar os custos operacionais e garantir um resfriamento constante e eficaz. Seja para uso comercial ou industrial, esse compressor é a escolha certa para quem valoriza desempenho, confiabilidade e compromisso com o meio ambiente.', 839.9, 839.9, NULL, 'Home Appliances > Kitchen Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rfgg-m97f3g8ro3klb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F22593957220', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
