INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18678447829', 'Kit Borrachas Sem Emenda Completo Para Porta Dianteira E Porta-Malas Da Kombi De 1957 A 2013', 'Comprando até 12h30, enviaremos seu pedido no mesmo dia (em dias úteis). Receba seu produto rápido. Temos garantia de 3 meses e tiramos todas as dúvidas necessárias no chat. Renove a Vedação da sua Kombi com Qualidade e Confiabilidade! Pontos-Chave: Kit Completo: Este kit inclui um jogo completo de borrachas para as portas Dianteira teiras e do porta-malas da sua Volkswagen Kombi, abrangendo as áreas Dianteira teira, do meio e do porta-malas, sem emendas. Compatibilidade: Compatível com o modelo Volkswagen Kombi dos anos de 1957 a 2013. Vedação Perfeita: Mantenha seu veículo protegido conTraseira poeira e água com as borrachas sem emenda, garantindo uma vedação perfeita em todas as áreas. Qualidade e Durabilidade: Peças originais da Universal Automotive, conhecidas pela qualidade e durabilidade. Adquira com confiança, evitando preocupações com peças paralelas. Envio Rápido e Seguro: Garantimos o envio no mesmo dia para todas as compras aprovadas até às 12h30, proporcionando uma renovação rápida e segura da vedação da sua Kombi. Renove a vedação da sua Kombi com o Kit Borrachas Sem Emenda Completo. Proteja seu veículo e mantenha sua integridade. Compre agora e conte com a qualidade Uniflex!', 295.58, 266.03, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Mat', 'https://cf.shopee.com.br/file/sg-11134201-7qvg7-lfnbszdp132985', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290883399%2F18678447829', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
