INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18398979024', 'Kit Som Automotivo com 2 Drivers 2 Super Tweeters 2 Cornetas Longas 120W 8 Ohms Orion', 'Mais de 15 anos de experiencia no mercado com os melhores produtos e o melhor atendimento! KIT 2 DRIVERS + 2 SUPER TWEETERS + 2 CORNETAS LONGAS Este kit contem 2 drivers, 2 tweeters e 2 cornetas longas no total de 480W de potencia RMS, ideal para reproduzir frequencias medias e agudas, com total definicao sonora para o seu projeto de som. Carcaca super resistente e duravel, qualidade e desempenho reunidos em um so kit. Especificacoes tecnicas do Driver: Potencia: 120 W RMS (cada) Impedancia Nominal: 8 ohms Sensibilidade driver: 109 Db Resposta de frequencia driver: 800 a 20000Hz Carcaca em Polipropileno Diagrama Fenolico Ima Ferrite de Bario Especificacoes tecnicas do Tweeter: Potencia: 120 W RMS (cada) Impedancia Nominal: 8 ohms Sensibilidade tweeter: 111 Db Resposta de frequencia tweeter: 4000 a 20000Hz Bobina Simples Carcaca em Polipropileno Ima Ferrite de Bario Especificacoes tecnicas da Corneta: Corneta Longa 25 cm Fabricado em polipropileno Bocal Redondo Eficiencia de Dissipacao de Frequencias Medias Diametro aproximado da Garganta: 3,5 cm Diametro aproximado da Boca: 15 cm Altura aproximada: 25 cm Conteudo da Embalagem: 2 Drivers, 2 Super Tweeter e 2 Cornetas Longas. FABRICANTE: ORION AUDIO', 184.99, 184.99, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-loof3sljfmb63e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F625420381%2F18398979024', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21198074871', 'Loção Hidratante Corporal Infantil Mustela Hydra Bebê com Abacate Orgânico 300ml', 'A pele dos bebês é como a pele dos adultos: precisa se manter hidratada para permanecer saudável. Hydra Bebê hidrata a pele de forma imediata e duradoura, deixando-a macia e flexível. A sua textura fluida e leve é perfeita para cuidar da pele dos pequenos. Com 97% de ingredientes de origem natural e Abacate de cultivo orgânico, que protege e fortalece a barreira da pele. Pode ser usado diariamente, desde o nascimento. Fórmula com textura fluida e cheirinho delicado de Mustela.', 170.95, 170.95, NULL, 'Beauty > Bath & Body Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd5c-m76ydk67h9me6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F21198074871', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
