INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202594855', 'Linguiça Toscana Sadia', 'A Linguiça Toscana Sadia é feita com carne suína selecionada e temperos equilibrados, garantindo um sabor irresistível e uma textura macia em cada mordida. Prepare seu produto na panela, airfryer, forno ou churrasqueira. Para sua segurança, siga as instruções abaixo: * Mantenha o produto cru separado dos outros alimentos. * Lave com água e sabão as superfícies de trabalho, incluindo as tábuas de corte, utensílios e mãos depois de manusear o produto cru. * Consuma somente após cozido, frito ou assado completamente.', 26.99, 26.99, NULL, 'Food & Beverages > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zue-miyqbuhybdoi34', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554774%2F58202594855', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21396988257', 'Sapato Boss Confort 59103 Rafarillo', 'O Sapato Boss Confort 59103 da Rafarillo é a escolha ideal para homens que buscam unir elegância e conforto em um só calçado. Disponível nas sofisticadas cores café e preto, este sapato é perfeito para diversas graças, desde reuniões de trabalho até eventos sociais. Confeccionado em couro legítimo, seu acabamento sofisticado garante durabilidade e um visual clássico que nunca sai de moda. O modelo conta com tecnologia de conforto, que inclui uma palmilha acolchoada e um forro interno, proporcionando uma experiência agradável mesmo em longas jornadas. O solado emborrachado oferece excelente tração e estabilidade, enquanto o design atemporal se adapta facilmente a diferentes estilos e roupas. Seja no dia a dia ou em eventos especiais, o Sapato Boss Confort 59103 é a escolha perfeita para o homem moderno que valoriza qualidade e sofisticação. Ficha Técnica: Modelo: Sapato Boss Confort 59103 Marca: Rafarillo Material Externo: Couro Legítimo Material Interno: Forro Masculino Externo Palmilha: Acolchoada e anatômica Solado: Emborrachado com aderência Fechamento: Cadarço Cores Disponíveis: Café e Preto Indicação: Uso formal e semi-formal Tamanhos Disponíveis: 38 ao 44 Peso: Aproximadamente 1 kg (o par, variação conforme o tamanho) Origem: Nacional. O Sapato Boss Confort 59103 da Rafarillo é uma combinação perfeita de estilo e conforto, ideal para o homem que deseja se destacar com sofisticação em qualquer situação.', 369.9, 322.99, NULL, 'Men Shoes > Oxfords & Lace-Ups', 'https://cf.shopee.com.br/file/sg-11134201-7qvfv-lhh13hc51wrtd9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F865304201%2F21396988257', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58212242286', 'KIT COM 3 BODY SPLASH FEMININO SUCCÈS VERT + AURA + INFALÍVEL 200ML - PRIMACIAL PERFUME FRESCO FLORAL', 'Kit Body Splash Succès Vert + Aura + Infalível Kit Feminino Completo | Frescor, Doçura e Presença Um kit com três fragrâncias que se complementam perfeitamente para todas as ocasiões. Do frescor leve ao doce envolvente e ao floral marcante, você tem opções para cada momento do seu dia. Ideal para quem gosta de variar o perfume e estar sempre cheirosa com diferentes estilos. Sobre as Fragrâncias: Succès Vert – Fresco, leve e sofisticado Uma fragrância refrescante com toque cítrico e elegante. Perfeita para o dia a dia, trabalho e momentos em que você quer leveza e energia. Pirâmide Olfativa Topo: Limão Siciliano, Bergamota, Cedro Coração: Jacinto, Pimenta Rosa, Jasmim Fundo: Patchouli, Almíscar, Vetiver, Âmbar Aura – Doce, envolvente e confortável Uma fragrância cremosa e acolhedora, com notas quentes e adocicadas que abraçam a pele. Sofisticada e marcante na medida certa. Pirâmide Olfativa Topo: Baunilha, Cacau e Gengibre Coração: Caviar de Baunilha Fundo: Lavanda e Baunilha Infalível – Marcante, feminino e sedutor Uma fragrância intensa e envolvente, com perfil floral frutado e fundo quente. Ideal para quem quer deixar rastro e ser lembrada. Pirâmide Olfativa Topo: Jasmim, Maçã Vermelha e Pêssego Coração: Magnólia, Framboesa, Rosa e Muguet Fundo: Fava Tonka, Baunilha, Âmbar e Musk Quando Usar: 🌤️ Dia: Excelente (Succès Vert e Aura) 🌙 Noite: Excelente (Infalível) 📦 Detalhes do Produto: ✔ Contém 3 body splashes de 200ml cada ✔ Fragrâncias femininas versáteis ✔ Perfumes leves e ideais para reaplicação ✔ Ótimo para uso diário ✔ Excelente custo-benefício em kit 💡 Dica de uso: Use o Succès Vert durante o dia para frescor, o Aura para momentos mais confortáveis e o Infalível quando quiser mais presença. Você também pode alternar conforme o seu humor ou ocasião.', 210.0, 115.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-820l5-mpaw9rkbk5j456', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295467768%2F58212242286', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
