INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25890739771', 'Kit Teclado Mouse Gamer KEEDI-TEC814 Membrana LED USB Controlador Volume', 'KIT TECLADO E MOUSE KEEDI-TEC814 - Teclado de membrana de alta qualidade - Iluminação LED com 3 cores simultâneas, oferecendo um visual dinâmico e personalizável - Teclas com espaçamento de 7mm, ideal para uma jogabilidade mais confortável e precisa - Iluminação retroiluminada ao redor das teclas, perfeita para jogar em ambientes com pouca luz - Design moderno e arrojado, desenvolvido pensando na experiência dos melhores jogadores ATENÇÃO A tecla "?" funciona pressionando Alt + W no layout de teclado ABNT2 ; ABNT A tecla "?" próxima do ">" funciona apenas alterando o layout do teclado para Americano ou Chinês Caso troque para o layout Americano, as teclas "ç","´","[" iram mudar para outras. ESPECIFICAÇÕES: Marca: KEEDI Modelo: KEEDI-TEC814 Material: ABS de alta resistência Tipo: Teclado de Membrana Teclas suaves e silenciosas, proporcionando um uso confortável e discreto Teclas multimídia para acesso rápido a funções do sistema Conexão USB 2.0, garantindo resposta rápida aos comandos Chaves com padrão brasileiro (ABNT2) Compatível com: Windows/MAC/Linux Peso ideal para maior estabilidade durante o uso Compatível com Windows 2000 / XP / 2003 / Vista / Win 7 / Win 8 e 10 / Linux e MAC Teclas finas com impressão a laser, aumentando a durabilidade Sistema de drenagem para evitar danos causados por líquidos Controlador de volume integrado no teclado Com o KEEDI-TEC814, você tem um teclado de alta performance, praticidade e um design que vai elevar sua experiência de jogo a outro nível.', 142.82, 98.5, NULL, 'Computers & Accessories > Keyboards & Mice > Keyboards', 'https://cf.shopee.com.br/file/sg-11134201-823qr-mpc97voqykukfd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com