INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19026315211', 'Cdi Biz 100 1998-2005 Magnetron', 'Recupere a força da sua moto com um CDI Magnetron novinho! CDIs e TCIs definem o momento exato da queima, ajustando o ponto de ignição. Os módulos Magnetron garante precisão absoluta no tempo, otimizando a potência e a resposta do motor. Não espere ficar na mão — invista em um CDI novo e rode com tranquilidade! Atenção este Cdi Não possui corte !!! *Não tem corte de giro* Compatível com HONDA: C 100 DREAM 1992 C 100 DREAM 1993 C 100 DREAM 1994 C 100 DREAM 1995 C 100 DREAM 1996 C 100 DREAM 1997 C 100 DREAM 1998 C 100 BIZ 1998 C 100 BIZ 1999 C 100 BIZ 2000 C 100 BIZ 2001 C 100 BIZ 2002 C 100 BIZ 2003 C 100 BIZ 2004 C 100 BIZ 2005 C 100 ES BIZ 1998 C 100 ES BIZ 1999 C 100 ES BIZ 2000 C 100 ES BIZ 2001 C 100 ES BIZ 2002 C 100 ES BIZ 2003 C 100 ES BIZ 2004 C 100 ES BIZ 2005 C 100 + BIZ 2002 C 100 + BIZ 2003 C 100 + BIZ 2004 C 100 + BIZ 2005 Conteúdo da Embalagem: 01 CDI Magnetron Sem corte Código do Fabricante (Magnetron): 90271190 Código Original (OEM) do CDI: 30410-GB6-921 / 30410-KEV-901 Especificações Técnicas: - Tipo: CDI eletrônico AC (corrente alternada) - Voltagem: 12V - 5 Pinos - Material: Caixa plástica resistente com componentes internos de alta qualidade - Pinos: De acordo com padrão original Honda (conectores compatíveis com o chicote original) - Equivalente a Peça Original - Ideal para Reposição - Alta Resistência e Durabilidade - Tratamentos contra a oxidação - Confeccionado com a melhor matéria-prima - Melhor condutibilidade e maior vida útil da peça - Material leve e resistente - Ótimo acabamento, proporcionando uma instalação sem adaptações - Excelente qualidade e acabamento - Produto desenvolvido com os mesmos parâmetros e encaixes do original, substituindo o mesmo sem nenhum problema ou adaptação. - Elaborado com matéria-prima de alta qualidade - Testado e aprovado dentro das normas de segurança. Importante !! Antes de comprar, verifique o modelo compatível a sua moto. Para a instalação do produto corretamente, leve ao mecânico de sua confiança! Não nos responsabilizamos pelo mau uso do produto.', 71.9, 60.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Ignition', 'https://cf.shopee.com.br/file/br-11134207-820lr-mpb0ci248k5cb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F19026315211', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
