INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55657967283', 'Casa Casinha de Cachorro Médio Grande Porte N5', 'PROTEGE SEU AMIGÃO CONTRA CHUVA E FRIO!! N5 TAMANHO - 49cm de Altura X 59cm de Comprimento X 49cm de Largura Apresentamos a casinha Para Cachorro N5, um produto de alta qualidade da marca UNISHOP. Esta casinha é perfeita para o seu cão de PORTE MÉDIO, proporcionando um espaço confortável e seguro para ele descansar e se proteger. Feita de polietileno, um material resistente e durável, esta casinha é impermeável, garantindo que o seu pet estará protegido das condições climáticas adversas. Além disso, é desmontável, o que facilita a limpeza e o transporte, caso seja necessário. Com 49 cm de altura, esta casinha oferece espaço suficiente para o seu pet se movimentar com conforto. O design elegante na cor preta combina com qualquer decoração, seja no interior da sua casa ou no jardim, quintal. A Casa Casinha Para Cachorro Unishop N5 é uma excelente escolha para proporcionar ao seu pet um espaço só dele, onde ele se sentirá seguro e confortável. Adquira já a sua e proporcione ao seu melhor amigo o conforto que ele merece.', 149.98, 99.5, NULL, 'Pets > Pet Accessories > Pet Furniture', 'https://cf.shopee.com.br/file/sg-11134201-8261t-mmg4xq69syrn7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F908280603%2F55657967283', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
