INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994458138', 'Ar Condicionado Split 9000 BTU/h Prime Quente E Frio 220V', 'Ar Condicionado Split 9000 BTU/h Prime Air 9QC Quente E Frio 220VEleve seu conforto e bem-estar com o Ar-Condicionado Split 9000 BTU/h Prime Air 9QC Quente e Frio! Imagine chegar em casa e encontrar o clima perfeito em qualquer estação. Com tecnologia Inverter e classificação energética A, este ar-condicionado oferece máximo conforto com economia de energia, mantendo seu ambiente ideal sem preocupações com a conta de luz. Seu gás R32 garante maior eficiência e menor impacto ambiental, enquanto as aletas anticorrosivas prolongam a vida útil do aparelho. Escolha entre 5 modos de operação: refrigere no verão, aqueça no inverno, ajuste a umidade ou ventile conforme sua preferência. Com funções inteligentes como Timer, Turbo e Modo Sleep, você personaliza o clima para cada momento. O filtro lavável facilita a manutenção, e o filtro de proteção contra vírus (com kit opcional) traz ainda mais segurança para sua família. O Ar-Condicionado Inverter 9000 BTU/h Prime Air 9QC é a escolha certa para quem busca conforto, economia e tranquilidade. Especificações Técnicas: Altura do produto: 20 cm Largura do produto: 72,5 cm Comprimento do produto: 32,5 cm Peso do produto: 25,5 kg Altura com embalagem: 80 cm Largura com embalagem: 79,9 cm Comprimento com embalagem: 32,5 cm Peso com embalagem: 27,5 kg Observação: Somente faturamos para o nosso consumidor final, ou seja, não faturamos pedidos para CNPJ por este portal de vendas;', 1799.9, 1673.91, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-824i2-meeawzy1bsw652', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F22994458138', NULL, NULL, '2026-07-28T02:11:31.708458+